\HLAClausePlacedBlock{121.980}{69.786}{400.030}{%
  \HLAClauseParagraph{\resizebox{399.943bp}{!}{\mbox{identifier enclosed in brackets in which the opening bracket is preceded with an asterisk. In XML,}}\newline{}\resizebox{400.030bp}{!}{\mbox{every XML attribute has a corresponding note attribute. This attribute shall receive the note pointers}}\newline{}\resizebox{382.335bp}{!}{\mbox{for the corresponding value attribute; the text of the note shall be recorded in the notes element.}}}
}
\HLAStableID{m7.p115.b02}
