  \HLAClauseParagraph{\resizebox{321.784bp}{!}{\mbox{http://standards.ieee.org/downloads/1516/1516.2-2025/IEEE1516-DIF-2025.xsd}}}
}
\end{HLAClauseSemanticPage}

