\HLAStableID{m7.p116.b04}
\HLAClausePlacedBlock{90.000}{157.806}{432.022}{%
  \HLAClauseParagraph{\resizebox{432.022bp}{!}{\mbox{The OMT Conformance XML Schema is more restrictive than the OMT DIF XML Schema. It enables}}\newline{}\resizebox{431.943bp}{!}{\mbox{automated conformance testing of OMT documents by using XML validation. Most but not all conformance}}\newline{}\resizebox{256.549bp}{!}{\mbox{tests, as defined in Clause 6, are expressed in the XML Schema.}}}
}
\HLAStableID{m7.p116.b05}
\HLAClausePlacedBlock{90.000}{205.805}{432.000}{%
  \HLAClauseParagraph{\resizebox{358.080bp}{!}{\mbox{Conformance tests not expressed in the OMT Conformance XML Schema are as follows:}}}
