\HLAStableID{m7.p116.b06}
\HLAClausePlacedBlock{121.981}{223.805}{402.119}{%
  \HLAClauseLabeledItem{1)}{\resizebox{379.923bp}{!}{\mbox{Attribute names shall not duplicate (overload) the names of attributes of this class or any}}\newline{}\resizebox{94.383bp}{!}{\mbox{higher-level superclass.}}}
