\HLAStableID{m7.p116.b07}
\HLAClausePlacedBlock{121.981}{250.804}{402.119}{%
  \HLAClauseLabeledItem{2)}{\resizebox{380.032bp}{!}{\mbox{Parameter names shall not duplicate (overload) the names of parameters of this class or any}}\newline{}\resizebox{91.861bp}{!}{\mbox{higher-level superclass}}}
}
\HLAStableID{m7.p116.b08}
\HLAClausePlacedBlock{90.000}{298.140}{271.730}{%
  \HLAAnnexSubclauseHeading{E.1 OMT conformance XML Schema declaration}
}
\HLAStableID{m7.p116.b09}
\HLAClausePlacedBlock{90.000}{338.766}{432.000}{%
  \HLAClauseParagraph{\resizebox{407.933bp}{!}{\mbox{The following file shall include the OMT DIF XML Schema. This file accompanies this specification.}}}
