\HLAStableID{m7.p116.b10}
\HLAClausePlacedBlock{89.999}{358.805}{432.001}{%
  \HLAClauseParagraph{\resizebox{326.977bp}{!}{\mbox{http://standards.ieee.org/downloads/1516/1516.2-2025/IEEE1516-OMT-2025.xsd}}}
}
\end{HLAClauseSemanticPage}

