    \resizebox{142.529bp}{!}{\mbox{\textbf{4. HLA OMT components}}}\par}
}
\HLAStableID{m4.p033.b10}
\HLAClausePlacedBlock{90.000}{226.806}{432.036}{%
  \HLAClauseParagraph{\resizebox{431.996bp}{!}{\mbox{HLA object models are composed of a group of interrelated components specifying information about}}\newline{}\resizebox{431.866bp}{!}{\mbox{classes of objects and their attributes and interactions and their parameters. The information content of these}}\newline{}\resizebox{431.964bp}{!}{\mbox{components can be represented in many different ways or presentations. A presentation is the formatting of}}\newline{}\resizebox{431.951bp}{!}{\mbox{the information contained in the object model in a particular manner for a particular purpose. For example,}}\newline{}\resizebox{432.036bp}{!}{\mbox{the OMT tabular format is designed for presentation on a printed page, whereas the OMT data interchange}}\newline{}\resizebox{431.965bp}{!}{\mbox{format (DIF) is a presentation designed for passing an object model between tools. All HLA object models}}\newline{}\resizebox{432.002bp}{!}{\mbox{shall be capable of being presented in both the OMT tabular format and the OMT DIF (the primary and}}\newline{}\resizebox{432.032bp}{!}{\mbox{authoritative format). This standard defines the OMT content and presents it in OMT tabular format}}\newline{}\resizebox{46.340bp}{!}{\mbox{throughout.}}}
}
\HLAStableID{m4.p033.b11}
\HLAClausePlacedBlock{90.000}{346.804}{432.000}{%
  \HLAClauseParagraph{\resizebox{194.876bp}{!}{\mbox{The OMT consists of the following components:}}}
}
\HLAStableID{m4.p033.b12}
\HLAClausePlacedBlock{100.020}{361.804}{421.987}{%
  \HLAClauseDashItem{\resizebox{400.027bp}{!}{\mbox{\textit{Object model identification table}: To associate important identifying information with the HLA}}\newline{}\resizebox{51.930bp}{!}{\mbox{object model}}}
}
\HLAStableID{m4.p033.b13}
\HLAClausePlacedBlock{100.020}{388.803}{421.991}{%
  \HLAClauseDashItem{\resizebox{400.031bp}{!}{\mbox{\textit{Object class structure table}: To record the namespace of all federate or federation object classes and}}\newline{}\resizebox{176.520bp}{!}{\mbox{to describe their class-subclass relationships}}}
}
\HLAStableID{m4.p033.b14}
\HLAClausePlacedBlock{100.019}{415.803}{421.981}{%
  \HLAClauseDashItem{\resizebox{400.005bp}{!}{\mbox{\textit{Interaction class structure table}: To record the namespace of all federate or federation interaction}}\newline{}\resizebox{223.711bp}{!}{\mbox{classes and to describe their class-subclass relationships}}}
}
\HLAStableID{m4.p033.b15}
\HLAClausePlacedBlock{100.019}{442.802}{421.981}{%
  \HLAClauseDashItem{\resizebox{323.078bp}{!}{\mbox{\textit{Attribute table}: To specify features of object attributes in a federate or federation}}}
}
\HLAStableID{m4.p033.b16}
\HLAClausePlacedBlock{100.019}{457.802}{421.981}{%
  \HLAClauseDashItem{\resizebox{399.968bp}{!}{\mbox{\textit{Directed interaction class table:}\space{}To specify features of directed interactions for objects in a federate}}\newline{}\resizebox{51.364bp}{!}{\mbox{or federation}}}
}
\HLAStableID{m4.p033.b17}
\HLAClausePlacedBlock{100.019}{484.802}{421.981}{%
  \HLAClauseDashItem{\resizebox{355.465bp}{!}{\mbox{\textit{Parameter table}: To specify features of interaction parameters in a federate or federation}}}
}
\HLAStableID{m4.p033.b18}
\HLAClausePlacedBlock{100.019}{499.801}{421.981}{%
  \HLAClauseDashItem{\resizebox{353.977bp}{!}{\mbox{\textit{Dimension table}: To specify dimensions for filtering instance attributes and interactions}}}
}
\HLAStableID{m4.p033.b19}
\HLAClausePlacedBlock{100.019}{514.801}{421.981}{%
  \HLAClauseDashItem{\resizebox{286.505bp}{!}{\mbox{\textit{Time representation table}: To specify the representation of time values}}}
}
\HLAStableID{m4.p033.b20}
\HLAClausePlacedBlock{100.019}{529.801}{421.981}{%
  \HLAClauseDashItem{\resizebox{334.285bp}{!}{\mbox{\textit{User-supplied tag table}: To specify the representation of tags used in HLA services}}}
}
\HLAStableID{m4.p033.b21}
\HLAClausePlacedBlock{100.018}{544.801}{421.982}{%
  \HLAClauseDashItem{\resizebox{399.954bp}{!}{\mbox{\textit{Synchronization table}: To specify representation and data types used in HLA synchronization}}\newline{}\resizebox{32.200bp}{!}{\mbox{services}}}
}
\HLAStableID{m4.p033.b22}
\HLAClausePlacedBlock{100.018}{571.800}{421.982}{%
  \HLAClauseDashItem{\resizebox{299.861bp}{!}{\mbox{\textit{Transportation type table}: To describe the transportation mechanisms used}}}
}
\HLAStableID{m4.p033.b23}
\HLAClausePlacedBlock{100.017}{586.800}{421.983}{%
  \HLAClauseDashItem{\resizebox{214.661bp}{!}{\mbox{\textit{Update rate table}: To specify update rate information}}}
}
\HLAStableID{m4.p033.b24}
\HLAClausePlacedBlock{100.017}{601.800}{421.983}{%
  \HLAClauseDashItem{\resizebox{291.192bp}{!}{\mbox{\textit{Switches table}: To specify initial settings for parameters used by the RTI}}}
}
\HLAStableID{m4.p033.b25}
\HLAClausePlacedBlock{100.017}{616.799}{421.983}{%
  \HLAClauseDashItem{\resizebox{310.303bp}{!}{\mbox{\textit{Data type tables}: To specify details of data representation in the object model}}}
}
\HLAStableID{m4.p033.b26}
\HLAClausePlacedBlock{100.017}{631.799}{421.983}{%
  \HLAClauseDashItem{\resizebox{240.741bp}{!}{\mbox{\textit{Notes table}: To expand explanations of any OMT table item}}}
}
\HLAStableID{m4.p033.b27}
\HLAClausePlacedBlock{100.017}{646.799}{422.021}{%
  \HLAClauseDashItem{\resizebox{400.061bp}{!}{\mbox{\textit{Interface specification services usage table}: To specify the HLA services used by a federate or in a}}\newline{}\resizebox{40.493bp}{!}{\mbox{federation}}}
}
\HLAStableID{m4.p033.b28}
\HLAClausePlacedBlock{100.017}{673.798}{422.031}{%
  \HLAClauseDashItem{\resizebox{400.071bp}{!}{\mbox{\textit{FOM/SOM lexicon}: To define all of the objects, attributes, interactions, and parameters used in the}}\newline{}\resizebox{74.961bp}{!}{\mbox{HLA object model}}}
}
