\begin{HLAClauseSemanticPage}{33}
\HLAStableID{m4.page.034}
\HLAStableID{m4.p034.b01}
\HLAClausePlacedBlock{90.000}{69.786}{432.034}{%
  \HLAClauseParagraph{\resizebox{431.951bp}{!}{\mbox{All of the OMT components shall be completed when specifying an HLA object model for both federations}}\newline{}\resizebox{432.034bp}{!}{\mbox{and individual federates. However, certain tables may be empty or devoid of domain-specific content. For}}\newline{}\resizebox{431.977bp}{!}{\mbox{instance, although federations typically support interactions among their federates, some federates (such as a}}\newline{}\resizebox{431.999bp}{!}{\mbox{stealth viewer) might not be involved in interactions. In this situation, the interaction class structure table}}\newline{}\resizebox{431.949bp}{!}{\mbox{would contain only the single interaction class required by the HLA and the parameter table would be empty}}\newline{}\resizebox{431.992bp}{!}{\mbox{in that federate’s SOM or supporting SOM module. It is also expected that federates commonly have objects}}\newline{}\resizebox{432.022bp}{!}{\mbox{with attributes of interest across the federation; in such cases, these objects and attributes shall be}}\newline{}\resizebox{432.027bp}{!}{\mbox{documented. However, a federate or an entire federation may exchange information solely via interactions;}}\newline{}\resizebox{431.975bp}{!}{\mbox{in which case, its object class structure table and attribute table would contain only HLA-required data. The}}\newline{}\resizebox{365.557bp}{!}{\mbox{specific rules for the applicability of each OMT table are provided in the table descriptions.}}}
}
\HLAStableID{m4.p034.b02}
\HLAClausePlacedBlock{90.000}{189.784}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.994bp}{!}{\mbox{The final HLA OMT component, the FOM/SOM lexicon, is essential to help users understand the semantics}}\newline{}\resizebox{173.205bp}{!}{\mbox{of the terms used in an HLA object model.}}}
}
\HLAStableID{m4.p034.b03}
\HLAClausePlacedBlock{89.999}{221.763}{432.064}{%
  \HLAClauseParagraph{\resizebox{431.996bp}{!}{\mbox{The HLA MOM specifies a designated set of information elements that are associated with federation}}\newline{}\resizebox{432.029bp}{!}{\mbox{executions. Implementation of the MOM information elements as specified in IEEE Std 1516.1-2025}}\newline{}\resizebox{432.028bp}{!}{\mbox{provides a mechanism for management of federation executions using existing HLA services. Inclusion of}}\newline{}\resizebox{432.030bp}{!}{\mbox{the MOM is required for all FOMs and is achieved by incorporating the MOM data using a MOM and MIM.}}\newline{}\resizebox{432.064bp}{!}{\mbox{In addition, federates that have an inherent capability to interact with or extend the MOM shall include the}}\newline{}\resizebox{432.035bp}{!}{\mbox{MOM in their SOM. Inclusion of the MOM means the inclusion of a MIM that contains all tables in}}\newline{}\resizebox{326.435bp}{!}{\mbox{Clause 11 of IEEE Std 1516.1-2025, along with any applicable MOM extensions.}}}
}
\HLAStableID{m4.p034.b04}
\HLAClausePlacedBlock{89.999}{308.762}{432.082}{%
  \HLAClauseParagraph{\resizebox{432.082bp}{!}{\mbox{The last row in any OMT table is labeled “Note\textit{.}” This allows the object model developer to associate one or}}\newline{}\resizebox{432.038bp}{!}{\mbox{more notes with the entire table. If no note is being provided for that table, a value of “NA” should be}}\newline{}\resizebox{432.039bp}{!}{\mbox{entered. Although the “Note” row is not explicitly identified or discussed in the table descriptions, it is}}\newline{}\resizebox{390.281bp}{!}{\mbox{shown in the table examples for illustration purposes. The notes feature is fully explained in 4.15.}}}
}
\HLAStableID{m4.p034.b05}
\HLAClausePlacedBlock{89.998}{362.761}{432.044}{%
  \HLAClauseParagraph{\resizebox{432.027bp}{!}{\mbox{A FOM or SOM is specified using one or more FOM or SOM modules. For a FOM, a MIM is also required}}\newline{}\resizebox{432.019bp}{!}{\mbox{whereas for a SOM, inclusion of a MIM depends on federate capabilities with respect to the MOM. Any}}\newline{}\resizebox{432.003bp}{!}{\mbox{FOM, SOM, FOM module, or SOM module that fully conforms to all of the rules and constraints stated in}}\newline{}\resizebox{431.965bp}{!}{\mbox{this specification is a\space{}\textit{compliant object model}. A FOM or SOM module is compliant if it conforms to all}}\newline{}\resizebox{432.044bp}{!}{\mbox{rules and constraints for a compliant object model as well as all rules and constraints that apply to FOM or}}\newline{}\resizebox{432.004bp}{!}{\mbox{SOM modules. A MIM is compliant if it conforms to all rules and constraints of a compliant object model}}\newline{}\resizebox{385.830bp}{!}{\mbox{and contains at least the information provided in the standard MIM (see IEEE Std 1516.1-2025).}}}
}
\HLAStableID{m4.p034.b06}
\HLAClausePlacedBlock{89.999}{449.760}{432.033}{%
  \HLAClauseParagraph{\resizebox{431.994bp}{!}{\mbox{The basics of each OMT component are presented in the following separate subclauses. The template format}}\newline{}\resizebox{431.948bp}{!}{\mbox{for each component is provided and described, and criteria are suggested to help guide decisions on when to}}\newline{}\resizebox{432.032bp}{!}{\mbox{include specific federate or federation features within each of these components for a specific HLA object}}\newline{}\resizebox{432.020bp}{!}{\mbox{model. Examples of the usage of each OMT component are also provided; these examples are for illustrative}}\newline{}\resizebox{432.016bp}{!}{\mbox{purposes only, and they are not meant to imply any additional requirements. Clause 7 specifies the rules and}}\newline{}\resizebox{432.000bp}{!}{\mbox{principles for merging FOM modules and SOM modules. Annex A specifies the notations used in describing}}\newline{}\resizebox{50.512bp}{!}{\mbox{OMT tables.}}}
}
\HLAStableID{m4.p034.b07}
\HLAClausePlacedBlock{90.000}{540.383}{188.030}{%
  \HLASubclauseHeading{4.1 Object model identification table}
}
\HLAStableID{m4.p034.b08}
\HLAClausePlacedBlock{90.000}{563.686}{124.955}{%
  \HLAMinorClauseHeading{4.1.1 Purpose/background}
}
\HLAStableID{m4.p034.b09}
\HLAClausePlacedBlock{90.000}{587.825}{432.024}{%
  \HLAClauseParagraph{\resizebox{431.988bp}{!}{\mbox{A key design goal for all HLA object models is to facilitate reuse. HLA object models provide information}}\newline{}\resizebox{431.964bp}{!}{\mbox{that enables inferences to be drawn regarding the reuse potential of individual federates for new}}\newline{}\resizebox{432.021bp}{!}{\mbox{applications. Reuse can also occur at the level of the object model. An existing FOM or FOM module may}}\newline{}\resizebox{431.827bp}{!}{\mbox{provide a foundation for the development of new FOMs, or SOMs or SOM modules may be merged to form}}\newline{}\resizebox{432.015bp}{!}{\mbox{new FOMs. In either case, to expedite reuse, it is important to include a minimum but sufficient degree of}}\newline{}\resizebox{431.941bp}{!}{\mbox{descriptive information in the object model. For instance, when federation developers wish to pose detailed}}\newline{}\resizebox{432.005bp}{!}{\mbox{questions about how a federate or federation was constructed, point of contact (POC) information within an}}\newline{}\resizebox{432.024bp}{!}{\mbox{HLA object model is extremely important. The purpose of this table is to document certain key identifying}}\newline{}\resizebox{193.783bp}{!}{\mbox{information within the object model description.}}}
}
\end{HLAClauseSemanticPage}

