\HLAStableID{m4.p035.b02}
\HLAClausePlacedBlock{90.000}{93.785}{432.059}{%
  \HLAClauseParagraph{\resizebox{432.059bp}{!}{\mbox{The information that identifies HLA object models shall be provided in a simple two-column table. The}}\newline{}\resizebox{432.009bp}{!}{\mbox{first column (Category) specifies the categories of data that shall be provided in this table. The second}}\newline{}\resizebox{431.946bp}{!}{\mbox{column (Information) shall specify the required information. Entries shall be provided for all rows. “NA”}}\newline{}\resizebox{431.975bp}{!}{\mbox{shall be entered in any row for which no information is appropriate. Definitions of the categories,}}\newline{}\resizebox{206.702bp}{!}{\mbox{descriptions, and occurrences are shown in Table 1.}}}
}
\HLAStableID{m4.p035.b03}
\HLAClausePlacedBlock{90.001}{158.764}{431.999}{%
  \HLAClauseParagraph{\resizebox{431.964bp}{!}{\mbox{The concept of FOM modules and SOM modules is supported via the “References” field of this table.}}\newline{}\resizebox{431.991bp}{!}{\mbox{“Dependent” modules in this context are those that contain references to data in other module(s), such as}}\newline{}\resizebox{431.915bp}{!}{\mbox{object class definitions or data type definitions. “Standalone” modules do not contain such references.}}\newline{}\resizebox{342.551bp}{!}{\mbox{Table 2 provides the structure to be used to describe the Table 1 metadata elements.}}}
}
\HLAStableID{m4.p035.b04}
\HLAClausePlacedBlock{216.841}{225.645}{175.523}{%
  \HLATableCaption{Table 1—OMT metadata descriptions}
}
