  \resizebox{229.150bp}{!}{\mbox{\textit{Type}: This field shall specify the type that the object model rep-}}\newline{}\resizebox{127.534bp}{!}{\mbox{resents; valid values are as follows:}}\newline{}\resizebox{174.941bp}{!}{\mbox{\textit{— FOM}: the object model describes a federation}}\newline{}\resizebox{166.458bp}{!}{\mbox{\textit{— SOM}: the object model describes a federate}}
