\HLAClausePlacedBlock{90.000}{69.383}{162.406}{%
  \HLASubclauseHeading{4.2 Object class structure table}
}
\HLAStableID{m4.p039.b02}
\HLAClausePlacedBlock{90.000}{96.646}{124.955}{%
  \HLAMinorClauseHeading{4.2.1 Purpose/background}
}
\HLAStableID{m4.p039.b03}
\HLAClausePlacedBlock{89.999}{122.765}{432.034}{%
  \HLAClauseParagraph{\resizebox{431.962bp}{!}{\mbox{The object class structure of an HLA object model is defined by a set of relations among classes of objects}}\newline{}\resizebox{432.014bp}{!}{\mbox{from the simulation or federation domain. An HLA object class is a collection of objects with certain}}\newline{}\resizebox{432.034bp}{!}{\mbox{characteristics in common (e.g., attributes and directed interactions). Each of the individual objects that are}}\newline{}\resizebox{235.694bp}{!}{\mbox{realizations of a class is said to be an instance of that class.}}}
}
\HLAStableID{m4.p039.b04}
\HLAClausePlacedBlock{89.999}{184.805}{432.098}{%
  \HLAClauseParagraph{\resizebox{432.048bp}{!}{\mbox{An HLA object class structure shall be defined by hierarchical relationships among classes of objects. Class}}\newline{}\resizebox{432.093bp}{!}{\mbox{relationships shall be represented by the inclusion of the associated class names in the appropriate columns of}}\newline{}\resizebox{431.967bp}{!}{\mbox{the object class structure table. Relationships among classes at nonadjacent levels of a class hierarchy can be}}\newline{}\resizebox{432.098bp}{!}{\mbox{derived through transitivity: if A is a superclass of B, and B is a superclass of C, A is also a superclass of C.}}\newline{}\resizebox{428.665bp}{!}{\mbox{Superclass and subclass play inverse roles in these relations: if A is a superclass of B, B is a subclass of A.}}}
}
\HLAStableID{m4.p039.b05}
\HLAClausePlacedBlock{89.999}{258.784}{432.015}{%
  \HLAClauseParagraph{\resizebox{431.971bp}{!}{\mbox{Subclasses can be considered to be specializations, or refinements, of their superclasses. Subclasses shall}}\newline{}\resizebox{431.990bp}{!}{\mbox{always inherit the attributes of their superclasses, and they may possess additional attributes to provide the}}\newline{}\resizebox{431.990bp}{!}{\mbox{desired specialization. For instance, suppose a “Circle” class is defined as a subclass of a “Figure” class.}}\newline{}\resizebox{431.998bp}{!}{\mbox{Attributes defined for the Figure class are those that apply to all types of figures, such as “Color” or “Line}}\newline{}\resizebox{432.014bp}{!}{\mbox{Thickness.” The Circle subclass automatically inherits the attributes of the Figure class; however, an}}\newline{}\resizebox{421.906bp}{!}{\mbox{additional “Radius” attribute might also be defined that is only appropriate for this special type of figure.}}}
}
\HLAStableID{m4.p039.b06}
\HLAClausePlacedBlock{90.000}{344.763}{432.022}{%
  \HLAClauseParagraph{\resizebox{431.952bp}{!}{\mbox{A class is a leaf of a class structure if it has no subclasses. The object class “HLAobjectRoot” shall be a}}\newline{}\resizebox{432.010bp}{!}{\mbox{superclass of all other object classes in a FOM, FOM module, SOM, or SOM module. The HLA object}}\newline{}\resizebox{432.022bp}{!}{\mbox{model shall support only single inheritance; in this mechanism, each class has at most one immediate}}\newline{}\resizebox{43.535bp}{!}{\mbox{superclass.}}}
}
\HLAStableID{m4.p039.b07}
\HLAClausePlacedBlock{90.000}{406.803}{432.000}{%
  \HLAClauseParagraph{\resizebox{256.190bp}{!}{\mbox{HLA defines the following three types of object class attributes:}}}
}
\HLAStableID{m4.p039.b08}
\HLAClausePlacedBlock{100.020}{432.782}{421.980}{%
  \HLAClauseDashItem{\resizebox{399.978bp}{!}{\mbox{\textbf{declared attributes:}\space{}The set of class attributes of an object class that are associated with that object}}\newline{}\resizebox{153.583bp}{!}{\mbox{class in the object class hierarchy tree.}}}
}
\HLAStableID{m4.p039.b09}
\HLAClausePlacedBlock{100.020}{459.782}{422.047}{%
  \HLAClauseDashItem{\resizebox{400.087bp}{!}{\mbox{\textbf{inherited attributes:}\space{}The set of class attributes of an object class that was declared in a superclass}}\newline{}\resizebox{208.741bp}{!}{\mbox{of that object class in the object class hierarchy tree.}}}
}
\HLAStableID{m4.p039.b10}
\HLAClausePlacedBlock{100.020}{486.782}{422.021}{%
  \HLAClauseDashItem{\resizebox{400.061bp}{!}{\mbox{\textbf{available attributes:}\space{}The set of declared attributes of an object class in union with the set of}}\newline{}\resizebox{154.955bp}{!}{\mbox{inherited attributes of that object class.}}}
}
\HLAStableID{m4.p039.b11}
\HLAClausePlacedBlock{90.000}{522.781}{432.000}{%
  \HLAClauseParagraph{\resizebox{352.838bp}{!}{\mbox{HLA defines the following three types of directed interaction classes for an object class:}}}
}
\HLAStableID{m4.p039.b12}
\HLAClausePlacedBlock{100.020}{537.781}{422.025}{%
  \HLAClauseDashItem{\resizebox{400.065bp}{!}{\mbox{\textbf{declared directed interaction class:}\space{}The set of class directed interactions of a particular object}}\newline{}\resizebox{400.010bp}{!}{\mbox{class that are listed in the federation object model (FOM) as being associated with that object class}}\newline{}\resizebox{131.508bp}{!}{\mbox{in the object class hierarchy tree.}}}
}
\HLAStableID{m4.p039.b13}
\HLAClausePlacedBlock{100.020}{576.780}{422.024}{%
  \HLAClauseDashItem{\resizebox{400.042bp}{!}{\mbox{\textbf{inherited directed interaction class:}\space{}A directed interaction class of an object class that was}}\newline{}\resizebox{400.064bp}{!}{\mbox{declared in a superclass of that object class in the object class hierarchy tree defined in the federation}}\newline{}\resizebox{85.255bp}{!}{\mbox{object model (FOM).}}}
}
\HLAStableID{m4.p039.b14}
\HLAClausePlacedBlock{100.021}{615.779}{421.979}{%
  \HLAClauseDashItem{\resizebox{399.968bp}{!}{\mbox{\textbf{available directed interaction class:}\space{}any directed interaction class defined for a given object class}}\newline{}\resizebox{320.460bp}{!}{\mbox{in union with the set of inherited directed interaction classes of that object class.}}}
}
\HLAStableID{m4.p039.b15}
\HLAClausePlacedBlock{89.999}{651.779}{432.065}{%
  \HLAClauseParagraph{\resizebox{432.064bp}{!}{\mbox{Federates participating in a federation execution may subscribe to attributes of object classes at any level of}}\newline{}\resizebox{431.976bp}{!}{\mbox{the class hierarchy. Conditions and circumstances surrounding discovery and reflection of instance attributes}}\newline{}\resizebox{159.048bp}{!}{\mbox{are described in IEEE Std 1516.1-2025.}}}
}
\end{HLAClauseSemanticPage}

% M4 semantic reconstruction of physical page 40 / printed page 39.
\begin{HLAClauseSemanticPage}{39}
\HLAStableID{m4.page.040}
\HLAStableID{m4.p040.b01}
\HLAClausePlacedBlock{90.000}{69.786}{432.042}{%
  \HLAClauseParagraph{\resizebox{432.042bp}{!}{\mbox{Object classes provide the means for federation participants to subscribe to information about all individual}}\newline{}\resizebox{431.983bp}{!}{\mbox{instances of HLA objects with common characteristics, such as all sports cars or all fighter jets. Classes are}}\newline{}\resizebox{432.021bp}{!}{\mbox{also essential to specifying characteristics (attributes) of simulation objects, because these are defined}}\newline{}\resizebox{431.920bp}{!}{\mbox{relative to classes of objects, not unique to individual instances. In addition, because basic HLA services (as}}\newline{}\resizebox{431.985bp}{!}{\mbox{described in IEEE Std 1516.1-2025) support subscriptions to object class attributes by federates}}\newline{}\resizebox{432.006bp}{!}{\mbox{participating in a federation execution, the RTI requires knowledge of all object classes and their attributes if}}\newline{}\resizebox{419.135bp}{!}{\mbox{it is to support distribution of HLA object information by class to the federates of a federation execution.}}}
}
\HLAStableID{m4.p040.b02}
\HLAClausePlacedBlock{90.001}{165.784}{432.006}{%
  \HLAClauseParagraph{\resizebox{431.959bp}{!}{\mbox{A class hierarchy expands the capabilities of a flat classification scheme by enabling federates to subscribe}}\newline{}\resizebox{431.926bp}{!}{\mbox{to information about broad superclasses of objects, such as all ground vehicles, all air vehicles, or all sea}}\newline{}\resizebox{431.993bp}{!}{\mbox{vehicles. IEEE Std 1516.1-2025 supports subscription to attributes of any class in an object class hierarchy}}\newline{}\resizebox{432.005bp}{!}{\mbox{so that federates can easily subscribe to attributes of all or only those classes of interest. An object class}}\newline{}\resizebox{431.990bp}{!}{\mbox{hierarchy also supports simplification of the specification of attributes by placing common attributes of}}\newline{}\resizebox{431.991bp}{!}{\mbox{multiple subclasses in a common superclass. Thus, class hierarchies enable simpler management of the}}\newline{}\resizebox{376.156bp}{!}{\mbox{interests of different federates in the objects and attributes involved in a federation execution.}}}
}
\HLAStableID{m4.p040.b03}
\HLAClausePlacedBlock{90.002}{263.623}{84.959}{%
  \HLAMinorClauseHeading{4.2.2 Table format}
}
\HLAStableID{m4.p040.b04}
\HLAClausePlacedBlock{90.001}{289.803}{432.090}{%
  \HLAClauseParagraph{\resizebox{432.006bp}{!}{\mbox{The object class structure template of Table 4 provides a format for representing the class-subclass hierarchy}}\newline{}\resizebox{432.027bp}{!}{\mbox{of object classes. It shall be populated by first entering the root class of all object classes in the left-most}}\newline{}\resizebox{432.089bp}{!}{\mbox{column; this object class is named “HLAobjectRoot.” Then, the most general object classes shall be entered}}\newline{}\resizebox{431.951bp}{!}{\mbox{in the next column, followed by all of their immediate subclasses in the next column, and then further levels}}\newline{}\resizebox{432.032bp}{!}{\mbox{of subclasses, as required. The number of intermediate columns used depends on the needs of the federate or}}\newline{}\resizebox{432.032bp}{!}{\mbox{federation. A federate or federation that uses a deeper hierarchy than illustrated by the template of the table}}\newline{}\resizebox{432.009bp}{!}{\mbox{shall add columns as needed. Finally, the most specific object classes shall be specified in the right-most}}\newline{}\resizebox{325.549bp}{!}{\mbox{column. Object class names shall adhere to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p040.b05}
\HLAClausePlacedBlock{90.001}{399.782}{432.069}{%
  \HLAClauseParagraph{\resizebox{432.069bp}{!}{\mbox{Although individual class names need not be unique, all object classes shall be uniquely identifiable in an}}\newline{}\resizebox{407.228bp}{!}{\mbox{HLA object model when concatenated (via dot notation) with the names of higher-level superclasses.}}}
}
\HLAStableID{m4.p040.b06}
\HLAClausePlacedBlock{90.001}{437.761}{432.057}{%
  \HLAClauseParagraph{\resizebox{432.030bp}{!}{\mbox{Each object class in the object class structure table shall be followed by information on publication and}}\newline{}\resizebox{432.057bp}{!}{\mbox{subscription capabilities enclosed in parentheses, as designated in the template using the abbreviated}}\newline{}\resizebox{86.553bp}{!}{\mbox{variable name\space{}\textit{<p/s>.}}}}
}
\HLAStableID{m4.p040.b07}
\HLAClausePlacedBlock{90.002}{487.801}{431.998}{%
  \HLAClauseParagraph{\resizebox{287.744bp}{!}{\mbox{For a SOM or SOM module, valid entries for\space{}\textit{<p/s>}\space{}shall be as follows:}}}
}
\HLAStableID{m4.p040.b08}
\HLAClausePlacedBlock{100.022}{513.781}{421.978}{%
  \HLAClauseDashItem{\resizebox{359.168bp}{!}{\mbox{\textit{P (Publish)}: The federate is capable of publishing at least one attribute of the object class.}}}
}
\HLAStableID{m4.p040.b09}
\HLAClausePlacedBlock{100.021}{528.780}{421.979}{%
  \HLAClauseDashItem{\resizebox{383.650bp}{!}{\mbox{\textit{S (Subscribe)}: The federate is capable of subscribing to at least one attribute of the object class.}}}
}
\HLAStableID{m4.p040.b10}
\HLAClausePlacedBlock{100.021}{543.780}{422.033}{%
  \HLAClauseDashItem{\resizebox{400.073bp}{!}{\mbox{\textit{PS (PublishSubscribe)}: The federate is capable of publishing at least one attribute and subscribing to}}\newline{}\resizebox{157.687bp}{!}{\mbox{at least one attribute of the object class.}}}
}
\HLAStableID{m4.p040.b11}
\HLAClausePlacedBlock{100.021}{570.780}{421.979}{%
  \HLAClauseDashItem{\resizebox{399.982bp}{!}{\mbox{\textit{N (Neither)}: The federate is incapable of either publishing or subscribing to any attributes of the}}\newline{}\resizebox{48.901bp}{!}{\mbox{object class.}}}
}
\HLAStableID{m4.p040.b12}
\HLAClausePlacedBlock{90.001}{609.779}{432.051}{%
  \HLAClauseParagraph{\resizebox{431.996bp}{!}{\mbox{For a FOM or FOM module, the same entries for\space{}\textit{<p/s>}\space{}are valid. However, an object class is classified as}}\newline{}\resizebox{432.051bp}{!}{\mbox{\textit{Publish}\space{}or\space{}\textit{Subscribe}\space{}in the federation if at least one federate is capable of publishing or subscribing to at}}\newline{}\resizebox{204.958bp}{!}{\mbox{least one attribute in the context of the object class.}}}
}
\HLAStableID{m4.p040.b13}
\HLAClausePlacedBlock{90.000}{660.778}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.940bp}{!}{\mbox{Classes designated as\space{}\textit{Subscribe}\space{}or\space{}\textit{Neither}\space{}can have no registered instances, but they can have subclasses}}\newline{}\resizebox{90.158bp}{!}{\mbox{that can be registered.}}}
}
\end{HLAClauseSemanticPage}

