% M4 semantic reconstruction of physical page 42 / printed page 41.
\begin{HLAClauseSemanticPage}{41}
\HLAStableID{m4.page.042}
\HLAStableID{m4.p042.b01}
\HLAClausePlacedBlock{90.000}{69.786}{432.034}{%
  \HLAClauseParagraph{\resizebox{431.989bp}{!}{\mbox{For individual federates, it is the intrinsic functionality (expressed as classes of objects) that the federate can}}\newline{}\resizebox{432.010bp}{!}{\mbox{offer to future HLA federations—and any object classes whose instances (and associated instance attribute}}\newline{}\resizebox{431.974bp}{!}{\mbox{values) may potentially represent useful information if generated by other HLA federates—that defines the}}\newline{}\resizebox{432.018bp}{!}{\mbox{content of the object class structure table. The structure of the object class hierarchy is driven by how the}}\newline{}\resizebox{432.033bp}{!}{\mbox{federate supports class publication and subscription. Rich, deep SOM class hierarchies can provide federates}}\newline{}\resizebox{422.452bp}{!}{\mbox{with a significant degree of flexibility in how they can support and participate in federations in the future.}}}
}
\HLAStableID{m4.p042.b02}
\HLAClausePlacedBlock{90.001}{156.784}{432.084}{%
  \HLAClauseParagraph{\resizebox{432.000bp}{!}{\mbox{For federations, it is the subscription requirements of the collective set of simulations participating in the}}\newline{}\resizebox{431.892bp}{!}{\mbox{federation that drives the content and structure of the object class hierarchy. Although a set of object classes}}\newline{}\resizebox{432.030bp}{!}{\mbox{for the most specific types of entities involved in a federation (e.g., cruiser, refrigerator) may completely}}\newline{}\resizebox{431.988bp}{!}{\mbox{satisfy the subscription requirements of some types of HLA applications, additional higher-level object}}\newline{}\resizebox{432.035bp}{!}{\mbox{classes would be needed if federates wish to be able to subscribe to HLA object information at higher levels}}\newline{}\resizebox{432.019bp}{!}{\mbox{of abstraction (e.g., navy surface ships, kitchen appliances). For a federate to be able to subscribe to HLA}}\newline{}\resizebox{432.083bp}{!}{\mbox{object information at a desired level of abstraction, an object class at that level of abstraction shall appear in}}\newline{}\resizebox{125.446bp}{!}{\mbox{the object class structure table.}}}
}
\HLAStableID{m4.p042.b03}
\HLAClausePlacedBlock{90.002}{267.783}{432.038}{%
  \HLAClauseParagraph{\resizebox{432.038bp}{!}{\mbox{For example, suppose a federation involved air, land, and sea forces of many specific types. If a particular}}\newline{}\resizebox{431.946bp}{!}{\mbox{federate did not require notification of the specific types of land vehicles, but did require notification of land}}\newline{}\resizebox{432.023bp}{!}{\mbox{vehicles in its area of interest, a suitable class (such as\space{}\textit{GroundVehicle}) that contained specific vehicle types}}\newline{}\resizebox{211.654bp}{!}{\mbox{as subclasses would be needed to make this possible.}}}
}
\HLAStableID{m4.p042.b04}
\HLAClausePlacedBlock{90.002}{330.782}{432.055}{%
  \HLAClauseParagraph{\resizebox{432.037bp}{!}{\mbox{Although classes are clearly needed for all objects of interest in a federation, many alternative class}}\newline{}\resizebox{432.055bp}{!}{\mbox{hierarchies can be devised to cover any given set of objects. The demarcations and levels of classes selected}}\newline{}\resizebox{432.041bp}{!}{\mbox{for an HLA FOM are the result of the federation development process. Object class hierarchies that already}}\newline{}\resizebox{432.018bp}{!}{\mbox{exist for individual FOM modules, SOM modules, and SOMs may be incorporated into a FOM object class}}\newline{}\resizebox{256.741bp}{!}{\mbox{hierarchy if they meet the interests of the federation as a whole.}}}
}
\HLAStableID{m4.p042.b05}
\HLAClausePlacedBlock{90.003}{408.641}{66.063}{%
  \HLAMinorClauseHeading{4.2.4 Example}
}
\HLAStableID{m4.p042.b06}
\HLAClausePlacedBlock{90.003}{438.780}{432.098}{%
  \HLAClauseParagraph{\resizebox{431.995bp}{!}{\mbox{Table 5 provides an example of how the object class structure table can be used to represent a simple system.}}\newline{}\resizebox{431.986bp}{!}{\mbox{In this case, the system being represented is a typical neighborhood restaurant. The simulation of this}}\newline{}\resizebox{432.057bp}{!}{\mbox{restaurant’s operations can be considered to be a potential federate in a larger scale federation, perhaps}}\newline{}\resizebox{432.098bp}{!}{\mbox{representing the combined, coordinated operation of a chain of restaurants. The intent of this example is not}}\newline{}\resizebox{432.004bp}{!}{\mbox{to specify a complete SOM for this system, but rather to provide partial illustrations of how the OMT tables}}\newline{}\resizebox{245.402bp}{!}{\mbox{can be used to capture relevant information about the system.}}}
}
\HLAStableID{m4.p042.b07}
\HLAClausePlacedBlock{90.003}{525.779}{432.077}{%
  \HLAClauseParagraph{\resizebox{432.046bp}{!}{\mbox{In this example, a subset of a complete object class hierarchy is shown as consisting of five object classes at}}\newline{}\resizebox{431.942bp}{!}{\mbox{the most general level. For this simulation, no class decomposition was necessary for the first three classes.}}\newline{}\resizebox{431.982bp}{!}{\mbox{For the fourth class, a single level of decomposition is shown resulting in five leaf classes. For the fifth class,}}\newline{}\resizebox{431.949bp}{!}{\mbox{several levels of decomposition are shown to illustrate a partial representation of the restaurant’s menu.}}\newline{}\resizebox{431.999bp}{!}{\mbox{Some of the deeper levels in this hierarchy could have been modeled as attributes (e.g.,\space{}\textit{ClamChowder}\space{}could}}\newline{}\resizebox{432.077bp}{!}{\mbox{have been a leaf class, with an attribute of\space{}\textit{Type}\space{}to represent the enumerated values of\space{}\textit{Manhattan}\space{}or}}\newline{}\resizebox{431.974bp}{!}{\mbox{\textit{NewEngland}). However, the modeler in this example opted to represent the most specific food types as}}\newline{}\resizebox{75.737bp}{!}{\mbox{individual classes.}}}
}
\HLAStableID{m4.p042.b08}
\HLAClausePlacedBlock{90.000}{636.777}{432.055}{%
  \HLAClauseParagraph{\resizebox{432.006bp}{!}{\mbox{In this example, most nonleaf classes are designated as\space{}\textit{Subscribe}\space{}only, whereas the leaf classes are}}\newline{}\resizebox{432.007bp}{!}{\mbox{designated as both\space{}\textit{Publish}\space{}and\space{}\textit{Subscribe}. One exception to this is the\space{}\textit{Employee}\space{}class, which contains}}\newline{}\resizebox{431.970bp}{!}{\mbox{several attributes that are only published or subscribed to at the subclass level. Another exception is the}}\newline{}\resizebox{432.052bp}{!}{\mbox{\textit{ClamChowder}\space{}class, which provides an example of a nonleaf class that can be registered (i.e., has attributes}}\newline{}\resizebox{431.994bp}{!}{\mbox{that can be published for that class). Finally,\space{}\textit{Manhattan}\space{}and\space{}\textit{NewEngland}\space{}provide examples of publishable}}\newline{}\resizebox{217.100bp}{!}{\mbox{leaf classes that do not contain subscribable attributes.}}}
}
\end{HLAClauseSemanticPage}

