\HLAClausePlacedBlock{90.000}{646.805}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.996bp}{!}{\mbox{An interaction is defined as an explicit action taken by a federate that may have some effect or impact on}}\newline{}\resizebox{431.998bp}{!}{\mbox{another federate within a federation execution. Interactions shall be specified in the interaction class}}\newline{}\resizebox{431.936bp}{!}{\mbox{structure table of HLA object models in terms of their class-subclass relationships, in much the same way}}\newline{}\resizebox{431.988bp}{!}{\mbox{that objects are described in the object class structure table. The hierarchical structure of interactions}}\newline{}\resizebox{431.976bp}{!}{\mbox{supported by this table is composed of relations of generalization (or specialization) between different types}}\newline{}\resizebox{431.983bp}{!}{\mbox{of interactions. For example, an engagement interaction might be specialized by air-to-ground engagements,}}}
}
