\HLAClausePlacedBlock{90.000}{69.786}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.929bp}{!}{\mbox{ship-to-air engagements, and others. This engagement interaction, then, would be said to generalize its more}}\newline{}\resizebox{59.682bp}{!}{\mbox{specific types.}}}
}
\HLAStableID{m4.p044.b02}
\HLAClausePlacedBlock{90.000}{103.805}{432.017}{%
  \HLAClauseParagraph{\resizebox{432.017bp}{!}{\mbox{An interaction hierarchy in an HLA FOM or FOM module is primarily designed to support inheritance. In}}\newline{}\resizebox{432.003bp}{!}{\mbox{SOMs and SOM modules, an interaction hierarchy reflects how the federate supports publication and}}\newline{}\resizebox{431.966bp}{!}{\mbox{subscription of interaction classes. The interaction class “HLAinteractionRoot” shall be a superclass of all}}\newline{}\resizebox{432.002bp}{!}{\mbox{other interaction classes in a FOM or SOM. The HLA object model shall support only single inheritance; in}}\newline{}\resizebox{431.999bp}{!}{\mbox{this mechanism, each class has at most one immediate superclass. Conditions and circumstances}}\newline{}\resizebox{329.724bp}{!}{\mbox{surrounding the processing of interactions are described in IEEE Std 1516.1-2025.}}}
}
\HLAStableID{m4.p044.b03}
\HLAClausePlacedBlock{90.000}{185.764}{432.079}{%
  \HLAClauseParagraph{\resizebox{432.025bp}{!}{\mbox{Interactions are one of the principal determinants of interoperability among simulations. Interoperability}}\newline{}\resizebox{432.079bp}{!}{\mbox{ordinarily requires some consistency in the treatment of interactions afforded by the different federates in}}\newline{}\resizebox{432.066bp}{!}{\mbox{which they appear. In distributed war fighting, for example, some uniformity in treatment of engagement}}\newline{}\resizebox{432.003bp}{!}{\mbox{interactions is commonly required for a “fair fight” to occur between objects simulated by different}}\newline{}\resizebox{431.982bp}{!}{\mbox{federates. Thus, all interactions in a FOM shall be identified and treated (to the extent possible) in a}}\newline{}\resizebox{205.900bp}{!}{\mbox{consistent fashion by all federates in the federation.}}}
}
\HLAStableID{m4.p044.b04}
\HLAClausePlacedBlock{90.001}{267.783}{432.020}{%
  \HLAClauseParagraph{\resizebox{432.017bp}{!}{\mbox{In addition, the types of interactions involved in a simulation execution shall be made known to the RTI in}}\newline{}\resizebox{432.020bp}{!}{\mbox{order to support publication and subscription to their occurrences. Thus, the HLA object model shall}}\newline{}\resizebox{431.964bp}{!}{\mbox{document all of the interactions that may be sent during a federation execution so that the RTI can recognize}}\newline{}\resizebox{22.487bp}{!}{\mbox{them.}}}
}
\HLAStableID{m4.p044.b05}
\HLAClausePlacedBlock{90.001}{325.662}{84.959}{%
  \HLAMinorClauseHeading{4.3.2 Table format}
}
\HLAStableID{m4.p044.b06}
\HLAClausePlacedBlock{90.001}{347.761}{432.027}{%
  \HLAClauseParagraph{\resizebox{432.009bp}{!}{\mbox{The template that shall be used for recording HLA interactions for a federation or an individual federate is}}\newline{}\resizebox{432.016bp}{!}{\mbox{illustrated in Table 6. The basic format for this table follows the format specified earlier for the object class}}\newline{}\resizebox{431.931bp}{!}{\mbox{structure table. Thus, the root interaction class shall be specified in the left-most column and shall be named}}\newline{}\resizebox{431.998bp}{!}{\mbox{“HLAinteractionRoot.” Subsequent columns to the right shall contain interaction classes with increasing}}\newline{}\resizebox{431.976bp}{!}{\mbox{degrees of class specificity. Like the object class structure table, additional columns may be added to the}}\newline{}\resizebox{431.917bp}{!}{\mbox{table as needed to specify the full hierarchy. Although individual class names need not be unique, all}}\newline{}\resizebox{432.017bp}{!}{\mbox{interaction classes shall be uniquely identifiable in an HLA object model when concatenated (via dot}}\newline{}\resizebox{432.026bp}{!}{\mbox{notation) with the names of higher-level superclasses. Interaction class names shall adhere to HLA naming}}\newline{}\resizebox{95.198bp}{!}{\mbox{conventions (see 3.3.1).}}}
}
