  \HLAClauseDashItem{\resizebox{307.827bp}{!}{\mbox{\textit{S (Subscribe)}: The federate is capable of subscribing to the interaction class.}}}
}
\HLAStableID{m4.p045.b05}
\HLAClausePlacedBlock{100.019}{162.784}{421.981}{%
  \HLAClauseDashItem{\resizebox{400.018bp}{!}{\mbox{\textit{PS (PublishSubscribe)}: The federate is capable of publishing and subscribing to the interaction}}\newline{}\resizebox{21.937bp}{!}{\mbox{class.}}}
}
\HLAStableID{m4.p045.b06}
\HLAClausePlacedBlock{100.019}{189.784}{421.981}{%
  \HLAClauseDashItem{\resizebox{386.158bp}{!}{\mbox{\textit{N (Neither)}: The federate is incapable of either publishing or subscribing to the interaction class.}}}
}
\HLAStableID{m4.p045.b07}
\HLAClausePlacedBlock{89.998}{213.783}{432.024}{%
  \HLAClauseParagraph{\resizebox{431.971bp}{!}{\mbox{For a FOM or FOM module, the same entries for\space{}\textit{<p/s>}\space{}are valid. An interaction class is classified as}}\newline{}\resizebox{432.024bp}{!}{\mbox{\textit{Publish}\space{}or\space{}\textit{Subscribe}\space{}in the federation if at least one federate is capable of publishing or subscribing to the}}\newline{}\resizebox{21.937bp}{!}{\mbox{class.}}}
}
\HLAStableID{m4.p045.b08}
\HLAClausePlacedBlock{89.998}{261.783}{432.002}{%
  \HLAClauseParagraph{\resizebox{404.488bp}{!}{\mbox{Classes designated as\space{}\textit{Subscribe}\space{}or\space{}\textit{Neither}\space{}are never sent, but they can have subclasses that are sent.}}}
}
\HLAStableID{m4.p045.b09}
\HLAClausePlacedBlock{89.999}{285.643}{104.962}{%
  \HLAMinorClauseHeading{4.3.3 Inclusion criteria}
}
\HLAStableID{m4.p045.b10}
\HLAClausePlacedBlock{89.999}{309.782}{432.121}{%
  \HLAClauseParagraph{\resizebox{432.000bp}{!}{\mbox{A type of interaction shall be included in a FOM or FOM module whenever it can take place “across” a}}\newline{}\resizebox{432.121bp}{!}{\mbox{federation, i.e., when it is published by one federate and subscribed to by another. Common examples of}}\newline{}\resizebox{432.067bp}{!}{\mbox{such interactions in warfighting simulations include a variety of engagement interactions between platforms}}\newline{}\resizebox{432.001bp}{!}{\mbox{that may be simulated by different federates. In order to document the types of interactions that federation}}\newline{}\resizebox{355.563bp}{!}{\mbox{members may need to accommodate, a FOM shall include all cross-federate interactions.}}}
}
\HLAStableID{m4.p045.b11}
\HLAClausePlacedBlock{89.998}{381.781}{432.068}{%
  \HLAClauseParagraph{\resizebox{432.065bp}{!}{\mbox{When interactions are expected to occur within an individual federate, they need not appear in a FOM or}}\newline{}\resizebox{432.068bp}{!}{\mbox{FOM module. For example, in an engineering simulation, the interactions involved in the internal dynamics}}\newline{}\resizebox{432.058bp}{!}{\mbox{of a vehicle engine should not be part of a FOM if only one federate in the federation interacts directly with}}\newline{}\resizebox{90.791bp}{!}{\mbox{the engine component.}}}
}
\HLAStableID{m4.p045.b12}
\HLAClausePlacedBlock{89.997}{441.780}{432.006}{%
  \HLAClauseParagraph{\resizebox{432.004bp}{!}{\mbox{Because HLA SOMs and SOM modules are intended to be developed independently of any particular}}\newline{}\resizebox{432.006bp}{!}{\mbox{federation application, the relevance of any currently supported interaction class to future federations will}}\newline{}\resizebox{431.944bp}{!}{\mbox{generally be unknown. Thus, a simulation that supports either publishing or subscribing for an interaction}}\newline{}\resizebox{432.003bp}{!}{\mbox{class should document that support in its SOM and/or relevant SOM modules if it might be of interest to}}\newline{}\resizebox{75.698bp}{!}{\mbox{future federations.}}}
}
\HLAStableID{m4.p045.b13}
\HLAClausePlacedBlock{89.997}{513.639}{66.063}{%
  \HLAMinorClauseHeading{4.3.4 Example}
}
\HLAStableID{m4.p045.b14}
\HLAClausePlacedBlock{89.996}{537.778}{432.061}{%
  \HLAClauseParagraph{\resizebox{432.037bp}{!}{\mbox{A representation of some illustrative interactions, based on the restaurant example introduced in 4.2.4, is}}\newline{}\resizebox{431.988bp}{!}{\mbox{given in Table 7. Here, the operations of the restaurant are described according to a set of interactions}}\newline{}\resizebox{432.042bp}{!}{\mbox{between customers and the employees of the restaurant. At the highest level, the restaurant federate can}}\newline{}\resizebox{431.933bp}{!}{\mbox{publish generic customer-employee transactions. This would, for instance, allow federates that simulate}}\newline{}\resizebox{432.018bp}{!}{\mbox{management operations across the restaurant chain to subscribe to and monitor general activity levels for}}\newline{}\resizebox{431.965bp}{!}{\mbox{individual restaurants. This single high level interaction class is then decomposed into the basic types of}}\newline{}\resizebox{432.049bp}{!}{\mbox{customer-employee interactions that occur in the restaurant. Although all classes at this level can be}}\newline{}\resizebox{431.965bp}{!}{\mbox{published by the federate,\space{}\textit{OrderTaken},\space{}\textit{FoodServed}, and\space{}\textit{CustomerPays}\space{}are all further decomposed into}}\newline{}\resizebox{432.007bp}{!}{\mbox{more specialized classes that can also be published by the restaurant federate depending on the needs of the}}\newline{}\resizebox{432.037bp}{!}{\mbox{federation. In addition, this federate also shows the ability to subscribe to (\textit{S}\space{}designation) interactions of}}\newline{}\resizebox{432.061bp}{!}{\mbox{classes\space{}\textit{CustomerSeated}\space{}and\space{}\textit{CustomerLeaves}, possibly to monitor customer arrival activity in other}}\newline{}\resizebox{427.771bp}{!}{\mbox{restaurants within the chain, and to monitor the rate at which other restaurants can service their customers.}}}
}
\end{HLAClauseSemanticPage}

