\HLAClausePlacedBlock{90.000}{284.765}{432.031}{%
  \HLAClauseParagraph{\resizebox{431.982bp}{!}{\mbox{Each class of simulation domain objects may support directed interactions. For a given, named object class,}}\newline{}\resizebox{431.937bp}{!}{\mbox{several FOM/SOM modules may specify directed interactions. Both federates and federations shall}}\newline{}\resizebox{432.031bp}{!}{\mbox{document all such directed interactions in the directed interaction table of their SOM, FOM, and relevant}}\newline{}\resizebox{432.023bp}{!}{\mbox{SOM modules and FOM modules. The object class "HLAobjectRoot", like any other object class, may have}}\newline{}\resizebox{139.148bp}{!}{\mbox{directed interactions assigned to it.}}}
}
