\HLAClausePlacedBlock{90.001}{380.764}{432.040}{%
  \HLAClauseParagraph{\resizebox{432.024bp}{!}{\mbox{The directed interaction table of a FOM or FOM module shall describe all directed interactions represented}}\newline{}\resizebox{431.983bp}{!}{\mbox{in a federation. The directed interaction table of a SOM or SOM module shall describe all directed}}\newline{}\resizebox{432.040bp}{!}{\mbox{interactions that can be sent or received by the federate. The template that shall be used for the directed}}\newline{}\resizebox{159.552bp}{!}{\mbox{interaction table is provided by Table 8.}}}
}
\HLAStableID{m4.p046.b06}
\HLAClausePlacedBlock{223.802}{428.624}{164.385}{%
