}
\HLAStableID{m4.p046.b07}
\HLAClausePlacedBlock{90.001}{516.782}{432.073}{%
  \HLAClauseParagraph{\resizebox{432.034bp}{!}{\mbox{The first column (Object) shall contain names from the object class structure table for object classes that are}}\newline{}\resizebox{431.992bp}{!}{\mbox{associated with directed interactions. Object class names shall include the parentage (superclasses) of the}}\newline{}\resizebox{432.073bp}{!}{\mbox{class to the depth necessary to uniquely identify the class in this table and may include the full parentage of}}\newline{}\resizebox{431.958bp}{!}{\mbox{the class. In general, to reduce redundancy, directed interactions should be specified for classes at the}}\newline{}\resizebox{203.732bp}{!}{\mbox{highest point in the hierarchy to which they apply.}}}
}
\HLAStableID{m4.p046.b08}
\HLAClausePlacedBlock{90.001}{588.781}{432.008}{%
  \HLAClauseParagraph{\resizebox{432.008bp}{!}{\mbox{The second column (Directed Interaction) shall list the directed interactions supported by the specified}}\newline{}\resizebox{431.969bp}{!}{\mbox{object class. Interaction class names shall include the parentage (superclasses) of the class to the depth}}\newline{}\resizebox{396.981bp}{!}{\mbox{necessary to uniquely identify the class in this table and may include the full parentage of the class.}}}
}
