\HLAClausePlacedBlock{89.999}{93.785}{432.102}{%
  \HLAClauseParagraph{\resizebox{431.976bp}{!}{\mbox{The attribute table of a FOM or FOM module shall describe all object attributes represented in a federation.}}\newline{}\resizebox{432.101bp}{!}{\mbox{The attribute table of a SOM or SOM module shall describe all class attributes that are published or}}\newline{}\resizebox{430.500bp}{!}{\mbox{subscribed to by the federate. The template that shall be used for the attribute table is provided by Table 10.}}}
}
\HLAStableID{m4.p048.b03}
\HLAClausePlacedBlock{89.998}{427.805}{432.136}{%
  \HLAClauseParagraph{\resizebox{432.034bp}{!}{\mbox{The first column (Object) shall contain names from the object class structure table for object classes that are}}\newline{}\resizebox{432.015bp}{!}{\mbox{associated with attributes. Object class names shall include the parentage (superclasses) of the class to the}}\newline{}\resizebox{431.967bp}{!}{\mbox{depth necessary to uniquely identify the class in this table and may include the full parentage of the class. In}}\newline{}\resizebox{432.054bp}{!}{\mbox{general, to reduce redundancy, attributes should be specified for classes at the highest point in the hierarchy}}\newline{}\resizebox{431.983bp}{!}{\mbox{to which they apply. For example, if all air vehicles have an attribute of\space{}\textit{MinimumTurnRadiusAt}}}\newline{}\resizebox{432.135bp}{!}{\mbox{\textit{MaximumSpeed}, some redundancy can be avoided if this attribute is specified just once for the entire class of}}\newline{}\resizebox{432.078bp}{!}{\mbox{\textit{AirVehicle}. Given that all object classes inherit the attribute types of their superclasses, the subclasses of}}\newline{}\resizebox{419.158bp}{!}{\mbox{\textit{AirVehicle}, such as\space{}\textit{FixedWing}\space{}and\space{}\textit{RotaryWing,}\space{}also have this attribute with its specified characteristics.}}}
}
\HLAStableID{m4.p048.b04}
\HLAClausePlacedBlock{89.999}{535.803}{432.041}{%
  \HLAClauseParagraph{\resizebox{432.001bp}{!}{\mbox{The second column (Attribute) shall list the attributes of the specified object class. Attribute names shall}}\newline{}\resizebox{432.041bp}{!}{\mbox{adhere to HLA naming conventions (see 3.3.1). The names assigned to attributes of any particular object}}\newline{}\resizebox{431.984bp}{!}{\mbox{class shall not duplicate (overload) the names of attributes of this class or any higher-level superclass. There}}\newline{}\resizebox{431.996bp}{!}{\mbox{may be many attributes for a single object class; however, all attribute names for a given class shall be}}\newline{}\resizebox{374.981bp}{!}{\mbox{unique. If no attributes are specified for an object class, “NA” shall be entered in this column.}}}
}
\HLAStableID{m4.p048.b05}
\HLAClausePlacedBlock{90.000}{607.802}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.971bp}{!}{\mbox{The third column (Data Type) shall identify the data type of the attribute. This data type shall be chosen}}\newline{}\resizebox{431.984bp}{!}{\mbox{from the name of any simple, enumerated, reference, array, fixed record, or variant record data type}}\newline{}\resizebox{431.974bp}{!}{\mbox{described in subclauses of 4.14. The predefined data type HLAtoken (see 4.14.6) can be used to indicate that}}\newline{}\resizebox{251.614bp}{!}{\mbox{the attribute never contains a value and is used only as a token.}}}
}
\HLAStableID{m4.p048.b06}
\HLAClausePlacedBlock{90.000}{667.801}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.998bp}{!}{\mbox{Although an attribute’s data type can be specified “NA,” that attribute shall have valid (non-“NA”)}}\newline{}\resizebox{431.968bp}{!}{\mbox{transportation and order types specified. When a data type of “NA” is used, the update type, update}}\newline{}\resizebox{223.972bp}{!}{\mbox{condition, and available dimensions shall also be “NA.”}}}
}
