\HLAStableID{m4.page.049}
\HLAStableID{m4.p049.b01}
\HLAClausePlacedBlock{89.999}{69.786}{432.030}{%
  \HLAClauseParagraph{\resizebox{432.029bp}{!}{\mbox{The fourth column (Update type) shall record the policy for updating an instance of the class attribute. The}}\newline{}\resizebox{222.611bp}{!}{\mbox{unique designations for this column shall be as follows:}}}
}
\HLAStableID{m4.p049.b02}
\HLAClausePlacedBlock{100.019}{99.785}{421.981}{%
  \HLAClauseDashItem{\resizebox{400.012bp}{!}{\mbox{\textit{Static}: The value of the attribute is static; the owner of the attribute (federate or RTI) updates it upon}}\newline{}\resizebox{129.883bp}{!}{\mbox{registration and when requested.}}}
}
\HLAStableID{m4.p049.b03}
\HLAClausePlacedBlock{100.019}{126.785}{421.981}{%
  \HLAClauseDashItem{\resizebox{398.609bp}{!}{\mbox{\textit{Periodic}: The owner of the attribute (federate or RTI) updates the attribute at regular time intervals\textit{.}}}}
}
\HLAStableID{m4.p049.b04}
\HLAClausePlacedBlock{100.018}{141.784}{421.982}{%
  \HLAClauseDashItem{\resizebox{400.014bp}{!}{\mbox{\textit{Conditional}: The owner of the attribute (federate or RTI) updates the attribute when unique}}\newline{}\resizebox{73.349bp}{!}{\mbox{conditions dictate.}}}
}
\HLAStableID{m4.p049.b05}
\HLAClausePlacedBlock{100.019}{168.784}{421.981}{%
  \HLAClauseDashItem{\resizebox{230.454bp}{!}{\mbox{\textit{NA}: The federate never provides a value for this attribute.}}}
}
\HLAStableID{m4.p049.b06}
\HLAClausePlacedBlock{89.997}{192.784}{432.042}{%
  \HLAClauseParagraph{\resizebox{431.979bp}{!}{\mbox{The fifth column (Update condition) shall expand and explain the policies for updating an instance of the}}\newline{}\resizebox{431.867bp}{!}{\mbox{class attribute. When the update type is\space{}\textit{periodic}, a rate of the number of updates per time unit shall be}}\newline{}\resizebox{431.993bp}{!}{\mbox{specified in the Update Condition column. Attributes with a\space{}\textit{conditional}\space{}update type shall have the}}\newline{}\resizebox{431.890bp}{!}{\mbox{conditions for update specified in the “Update condition” column. The “Update condition” column may also}}\newline{}\resizebox{432.040bp}{!}{\mbox{be used to specify initial conditions for instance attribute updates. If a federate is capable of varying the rate}}\newline{}\resizebox{431.926bp}{!}{\mbox{and circumstances of the update of an instance object attribute, this information shall also be recorded in this}}\newline{}\resizebox{431.991bp}{!}{\mbox{column or through the OMT notes feature. If the update type is\space{}\textit{Static}\space{}or\space{}\textit{NA}, “NA” shall be entered in this}}\newline{}\resizebox{32.482bp}{!}{\mbox{column.}}}
}
\HLAStableID{m4.p049.b07}
\HLAClausePlacedBlock{89.997}{300.782}{432.003}{%
  \HLAClauseParagraph{\resizebox{431.979bp}{!}{\mbox{The sixth column (Value Required) shall indicate whether a value is required for instances of this object}}\newline{}\resizebox{281.812bp}{!}{\mbox{class. The entry for this column shall take one of the following values:}}}
}
\HLAStableID{m4.p049.b08}
\HLAClausePlacedBlock{89.997}{336.781}{432.003}{%
  \HLAClauseParagraph{\resizebox{119.024bp}{!}{\mbox{In a FOM or a FOM module:}}}
}
\HLAStableID{m4.p049.b09}
\HLAClausePlacedBlock{100.017}{351.781}{421.983}{%
  \HLAClauseDashItem{\resizebox{400.005bp}{!}{\mbox{True: Any federate that registers an instance of this class shall either publish and provide a value for}}\newline{}\resizebox{371.376bp}{!}{\mbox{this attribute or allow another federate to take ownership of the attribute and provide a value.}}}
}
\HLAStableID{m4.p049.b10}
\HLAClausePlacedBlock{100.017}{378.781}{422.030}{%
  \HLAClauseDashItem{\resizebox{400.070bp}{!}{\mbox{False: Any federate that registers an instance of this class may choose whether to publish and}}\newline{}\resizebox{400.064bp}{!}{\mbox{provide a value for this attribute or not, or whether to allow another federate to take ownership of the}}\newline{}\resizebox{142.966bp}{!}{\mbox{attribute and provide a value or not.}}}
}
\HLAStableID{m4.p049.b11}
\HLAClausePlacedBlock{89.997}{426.780}{432.003}{%
  \HLAClauseParagraph{\resizebox{112.159bp}{!}{\mbox{In a SOM or SOM module:}}}
}
\HLAStableID{m4.p049.b12}
\HLAClausePlacedBlock{100.017}{441.780}{422.041}{%
  \HLAClauseDashItem{\resizebox{399.967bp}{!}{\mbox{True: In case the federate registers an instance of this class, the federate shall either publish this}}\newline{}\resizebox{400.081bp}{!}{\mbox{attribute and provide a value or allow another federate to take ownership of the attribute and provide}}\newline{}\resizebox{399.962bp}{!}{\mbox{a value. In case the federate subscribes to this attribute, this specifies that a value is expected from}}\newline{}\resizebox{174.317bp}{!}{\mbox{the attribute owner of an instance attribute.}}}
}
\HLAStableID{m4.p049.b13}
\HLAClausePlacedBlock{100.016}{492.779}{422.037}{%
  \HLAClauseDashItem{\resizebox{400.018bp}{!}{\mbox{False: In case the federate registers an instance of this class, the federate may choose whether to}}\newline{}\resizebox{399.944bp}{!}{\mbox{publish this attribute and provide a value or not, or whether to allow another federate to take}}\newline{}\resizebox{400.017bp}{!}{\mbox{ownership of the attribute and provide a value or not. In case the federate subscribes to this attribute,}}\newline{}\resizebox{400.078bp}{!}{\mbox{this specifies that a value is not necessarily expected from the attribute owner of an instance}}\newline{}\resizebox{38.316bp}{!}{\mbox{attribute.}}}
}
\HLAStableID{m4.p049.b14}
\HLAClausePlacedBlock{89.996}{564.778}{432.034}{%
  \HLAClauseParagraph{\resizebox{432.006bp}{!}{\mbox{In case this attribute is neither published or subscribed in a FOM, FOM module, SOM or SOM module, this}}\newline{}\resizebox{432.034bp}{!}{\mbox{column shall be set to False. To provide a value, in this context, means providing a value initially, on}}\newline{}\resizebox{251.678bp}{!}{\mbox{change, periodically or on request, or any combination thereof.}}}
}
\HLAStableID{m4.p049.b15}
\HLAClausePlacedBlock{89.996}{612.777}{432.004}{%
  \HLAClauseParagraph{\resizebox{431.996bp}{!}{\mbox{The seventh column (D/A) shall indicate whether ownership of an instance of the class attribute can be}}\newline{}\resizebox{86.015bp}{!}{\mbox{divested or acquired.}}\newline{}\resizebox{431.918bp}{!}{\mbox{In a FOM or FOM module, the ownership of an instance attribute may be designated as divest, acquire, both}}\newline{}\resizebox{296.414bp}{!}{\mbox{or neither. Descriptions of the designations for this column are as follows:}}}
}
\HLAStableID{m4.p049.b16}
\HLAClausePlacedBlock{100.016}{668.816}{422.017}{%
  \HLAClauseDashItem{\resizebox{400.058bp}{!}{\mbox{\textit{D (Divest)}: Some federate in the federation is capable of publishing the class attribute and can divest}}\newline{}\resizebox{360.032bp}{!}{\mbox{ownership of an instance of this attribute using the HLA ownership management services.}}}
}
\HLAStableID{m4.p049.b17}
\HLAClausePlacedBlock{100.016}{695.815}{422.051}{%
  \HLAClauseDashItem{\resizebox{400.092bp}{!}{\mbox{\textit{A (Acquire)}: Some federate in the federation is capable of publishing the class attribute and can}}\newline{}\resizebox{197.733bp}{!}{\mbox{acquire ownership of an instance of this attribute.}}}
}
\end{HLAClauseSemanticPage}

% M4 semantic reconstruction of physical page 50 / printed page 49.
\begin{HLAClauseSemanticPage}{49}
\HLAStableID{m4.page.050}
\HLAStableID{m4.p050.b01}
\HLAClausePlacedBlock{100.020}{69.786}{421.980}{%
  \HLAClauseDashItem{\resizebox{400.012bp}{!}{\mbox{\textit{N (NoTransfer)}: Ownership of an instance of this class attribute is not transferable in this federation.}}}
}
\HLAStableID{m4.p050.b02}
\HLAClausePlacedBlock{100.019}{84.785}{421.997}{%
  \HLAClauseDashItem{\resizebox{400.038bp}{!}{\mbox{\textit{DA (DivestAcquire)}: Some federate in the federation is capable of divesting ownership of instances}}\newline{}\resizebox{399.947bp}{!}{\mbox{of this class attribute and another federate is capable of acquiring ownership of instances of this}}\newline{}\resizebox{344.723bp}{!}{\mbox{class attribute. The\space{}\textit{HLAprivilegeToDeleteObject}\space{}attribute shall have a value of “DA”.}}}
}
\HLAStableID{m4.p050.b03}
\HLAClausePlacedBlock{89.998}{132.785}{432.002}{%
  \HLAClauseParagraph{\resizebox{431.925bp}{!}{\mbox{In a SOM or SOM module, the federate may be able to divest ownership of an instance attribute, acquire}}\newline{}\resizebox{431.947bp}{!}{\mbox{ownership, both, or neither. Moreover, the corresponding class attribute shall be published for the federate to}}\newline{}\resizebox{368.672bp}{!}{\mbox{divest or acquire ownership. Descriptions of the designations for this column are as follows:}}}
}
\HLAStableID{m4.p050.b04}
\HLAClausePlacedBlock{100.018}{171.784}{422.134}{%
  \HLAClauseDashItem{\resizebox{400.174bp}{!}{\mbox{\textit{D (Divest)}: The federate is capable of publishing the class attribute and can divest ownership of an}}\newline{}\resizebox{293.130bp}{!}{\mbox{instance of this attribute using the HLA ownership management\space{}services.}}}
}
\HLAStableID{m4.p050.b05}
\HLAClausePlacedBlock{100.018}{198.784}{421.982}{%
  \HLAClauseDashItem{\resizebox{400.013bp}{!}{\mbox{\textit{A (Acquire)}: The federate is capable of publishing the class attribute and can acquire ownership of}}\newline{}\resizebox{110.795bp}{!}{\mbox{an instance of this attribute.}}}
}
\HLAStableID{m4.p050.b06}
\HLAClausePlacedBlock{100.018}{225.783}{422.062}{%
  \HLAClauseDashItem{\resizebox{400.102bp}{!}{\mbox{\textit{N (NoTransfer)}: The federate is neither capable of divesting ownership of instances of this class}}\newline{}\resizebox{249.639bp}{!}{\mbox{attribute nor acquiring ownership of instances of this attribute.}}}
}
\HLAStableID{m4.p050.b07}
\HLAClausePlacedBlock{100.018}{252.783}{422.068}{%
  \HLAClauseDashItem{\resizebox{400.021bp}{!}{\mbox{\textit{DA (DivestAcquire)}: The federate is capable of both divesting ownership of instances of this class}}\newline{}\makebox[400.108bp][l]{attribute\hfill{}and\hfill{}acquiring\hfill{}ownership\hfill{}of\hfill{}instances\hfill{}of\hfill{}this\hfill{}class\hfill{}attribute.\hfill{}The}\newline{}\resizebox{266.456bp}{!}{\mbox{\textit{HLAprivilegeToDeleteObject}\space{}attribute shall have a value of “DA”.}}}
}
\HLAStableID{m4.p050.b08}
\HLAClausePlacedBlock{89.997}{296.762}{432.003}{%
  \HLAClauseParagraph{\resizebox{432.002bp}{!}{\mbox{The eighth column (P/S) shall identify the capabilities of a federate or federation with respect to class}}\newline{}\resizebox{148.525bp}{!}{\mbox{attribute publishing and subscribing.}}}
}
\HLAStableID{m4.p050.b09}
\HLAClausePlacedBlock{89.997}{328.801}{432.003}{%
  \HLAClauseParagraph{\resizebox{365.912bp}{!}{\mbox{In a SOM or SOM module, the entry for this column shall take one of the following values:}}}
}
\HLAStableID{m4.p050.b10}
\HLAClausePlacedBlock{100.017}{348.781}{422.017}{%
  \HLAClauseDashItem{\resizebox{400.001bp}{!}{\mbox{\textit{P (Publish)}: The federate is capable of publishing this class attribute, either in the context of the}}\newline{}\resizebox{400.057bp}{!}{\mbox{class where it is declared or in at least one subclass of that class (i.e., capable of invoking}}\newline{}\resizebox{340.964bp}{!}{\mbox{appropriate HLA publishing services with the class attribute as a supplied argument).}}}
}
\HLAStableID{m4.p050.b11}
\HLAClausePlacedBlock{100.016}{387.781}{421.998}{%
  \HLAClauseDashItem{\resizebox{400.038bp}{!}{\mbox{\textit{S (Subscribe)}: The federate is capable of subscribing to this class attribute, either in the context of}}\newline{}\resizebox{400.016bp}{!}{\mbox{the class where it is declared or in at least one subclass of that class (i.e., capable of invoking HLA}}\newline{}\resizebox{321.724bp}{!}{\mbox{appropriate subscribing services with the class attribute as a supplied argument).}}}
}
\HLAStableID{m4.p050.b12}
\HLAClausePlacedBlock{100.015}{426.780}{422.120}{%
  \HLAClauseDashItem{\makebox[399.991bp][l]{\textit{PS (PublishSubscribe)}:\hfill{}The federate is capable of both publishing and subscribing to this class}\newline{}\resizebox{400.161bp}{!}{\mbox{attribute. The\space{}\textit{HLAprivilegeToDeleteObject}\space{}attribute shall have a value of “PS” for both SOMs and}}\newline{}\resizebox{28.043bp}{!}{\mbox{FOMs.}}}
}
\HLAStableID{m4.p050.b13}
\HLAClausePlacedBlock{100.016}{465.779}{421.984}{%
  \HLAClauseDashItem{\resizebox{319.268bp}{!}{\mbox{\textit{N (Neither)}:\space{}The federate neither publishes nor subscribes to this class attribute.}}}
}
\HLAStableID{m4.p050.b14}
\HLAClausePlacedBlock{89.995}{485.819}{432.005}{%
  \HLAClauseParagraph{\resizebox{271.230bp}{!}{\mbox{In a FOM or FOM module, the same basic designations shall apply.}}}
}
\HLAStableID{m4.p050.b15}
\HLAClausePlacedBlock{89.995}{509.819}{432.092}{%
  \HLAClauseParagraph{\resizebox{432.092bp}{!}{\mbox{The ninth column (Available dimensions) shall record the association of the object class with a set of}}\newline{}\resizebox{431.944bp}{!}{\mbox{dimensions if a federate or federation is using data distribution management (DDM) services for attributes}}\newline{}\resizebox{431.982bp}{!}{\mbox{of this object class. The column shall contain a comma-separated list of dimension names corresponding to}}\newline{}\resizebox{432.017bp}{!}{\mbox{rows in the dimension table described in 4.7. This indicates that all attributes of this class, including}}\newline{}\resizebox{432.035bp}{!}{\mbox{inherited attributes, are subject to filtering through regions containing a subset of these dimensions. The}}\newline{}\resizebox{431.917bp}{!}{\mbox{available dimensions of an object class will be the the dimensions specified in this column, in union with all}}\newline{}\resizebox{432.015bp}{!}{\mbox{inherited dimensions. For SOMs and FOMs of federates and federations, respectively, that are not using}}\newline{}\resizebox{431.945bp}{!}{\mbox{DDM services or for object classes that are not associated with dimensions, “NA” shall be entered in this}}\newline{}\resizebox{32.482bp}{!}{\mbox{column.}}}
}
\HLAStableID{m4.p050.b16}
\HLAClausePlacedBlock{89.995}{625.797}{432.005}{%
  \HLAClauseParagraph{\resizebox{431.998bp}{!}{\mbox{The tenth column (Transportation) shall specify the type of transportation to be used with this attribute.}}\newline{}\resizebox{431.073bp}{!}{\mbox{These values shall be chosen from the name of any row in the transportation type table as described in 4.11.}}}
}
\HLAStableID{m4.p050.b17}
\HLAClausePlacedBlock{90.000}{657.785}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.992bp}{!}{\mbox{The eleventh column (Order) shall specify the order of delivery to be used with instances of this class}}\newline{}\resizebox{252.266bp}{!}{\mbox{attribute. Valid values for entries in this column are as follows:}}}
}
\HLAStableID{m4.p050.b18}
\HLAClausePlacedBlock{100.020}{689.825}{422.034}{%
  \HLAClauseDashItem{\resizebox{400.074bp}{!}{\mbox{\textit{Receive}: Instances of the class attribute are delivered to a receiving federate in an undetermined}}\newline{}\resizebox{23.630bp}{!}{\mbox{order.}}}
}
