\HLAClausePlacedBlock{90.000}{181.804}{432.010}{%
  \HLAClauseParagraph{\resizebox{431.999bp}{!}{\mbox{All instance attributes whose values can be exchanged or ownership can be transferred during the course of}}\newline{}\resizebox{431.949bp}{!}{\mbox{an HLA federation execution shall be documented in the attribute table of a FOM and relevant FOM}}\newline{}\resizebox{432.010bp}{!}{\mbox{modules. All class attributes that can be either published or subscribed to by an individual federate shall be}}\newline{}\resizebox{293.217bp}{!}{\mbox{documented in the attribute table of its SOM and relevant SOM modules.}}}
}
