\HLAStableID{m4.p052.b01}
\HLAClausePlacedBlock{90.000}{69.786}{432.028}{%
  \HLAClauseParagraph{\resizebox{431.986bp}{!}{\mbox{The\space{}\textit{Server}\space{}subclass of\space{}\textit{Employee}\space{}is shown with three attributes. These are in addition to the four inherited}}\newline{}\resizebox{432.028bp}{!}{\mbox{attributes from its superclass. Each of the first two attributes,\space{}\textit{Efficiency}\space{}and\space{}\textit{Cheerfulness}, is intended to}}\newline{}\resizebox{432.008bp}{!}{\mbox{represent a performance measure that is assigned to the employee at performance reviews. The third}}\newline{}\resizebox{431.954bp}{!}{\mbox{attribute is intended to represent the state of the employee (the task he/she is performing) at any point in time}}\newline{}\resizebox{114.648bp}{!}{\mbox{during restaurant operations.}}}
}
\HLAStableID{m4.p052.b02}
\HLAClausePlacedBlock{90.000}{139.804}{432.056}{%
  \HLAClauseParagraph{\resizebox{432.027bp}{!}{\mbox{The\space{}\textit{Drink}\space{}and\space{}\textit{Soda}\space{}classes are each shown with a single attribute. The NumberCups attribute has been}}\newline{}\resizebox{432.014bp}{!}{\mbox{associated with the dimensions of the Drink class and thus the BarQuantity dimension, and the Flavor}}\newline{}\resizebox{432.040bp}{!}{\mbox{attribute of the Soda class has been associated with the dimensions of the Soda class and thus the SodaFlavor}}\newline{}\resizebox{431.974bp}{!}{\mbox{dimension as well as the BarQuantity dimension, inherited from the superclass. The Light subclass, with no}}\newline{}\resizebox{432.056bp}{!}{\mbox{attributes, adds the Sweetener dimension. These dimensions are shown in the dimension table example in}}}
}
\HLAStableID{m4.p052.b03}
\HLAClausePlacedBlock{90.000}{194.764}{432.000}{%
  \HLAClauseParagraph{\resizebox{22.460bp}{!}{\mbox{4.6.4.}}}
}
\HLAStableID{m4.p052.b04}
\HLAClausePlacedBlock{90.000}{217.804}{432.014}{%
  \HLAClauseParagraph{\resizebox{431.981bp}{!}{\mbox{The HLAprivilegeToDeleteObject attribute of class HLAobjectRoot is a different kind of attribute than the}}\newline{}\resizebox{432.005bp}{!}{\mbox{others in the table. This attribute has a data type of “HLAtoken,” meaning that an instance of this attribute}}\newline{}\resizebox{432.014bp}{!}{\mbox{does not have a value to be updated. Instead, it is a token attribute which conveys the information of which}}\newline{}\resizebox{432.008bp}{!}{\mbox{federate, if any, owns the attribute at any time. In this case, HLAprivilegeToDeleteObject is a token attribute}}\newline{}\resizebox{429.276bp}{!}{\mbox{known by the RTI and used to determine whether or not a federate is permitted to delete an object instance.}}}
}
\HLAStableID{m4.p052.b05}
\HLAClausePlacedBlock{90.000}{282.783}{432.000}{%
  \HLAClauseParagraph{\resizebox{393.843bp}{!}{\mbox{Two examples of notes have also been included in Table 11; this feature is fully explained in 4.15.}}}
}
\HLAStableID{m4.p052.b06}
\HLAClausePlacedBlock{90.000}{305.363}{100.665}{%
  \HLASubclauseHeading{4.6 Parameter table}
}
\HLAStableID{m4.p052.b07}
\HLAClausePlacedBlock{90.000}{330.646}{124.955}{%
  \HLAMinorClauseHeading{4.6.1 Purpose/background}
}
\HLAStableID{m4.p052.b08}
\HLAClausePlacedBlock{90.000}{353.765}{432.043}{%
  \HLAClauseParagraph{\resizebox{431.895bp}{!}{\mbox{Most interaction classes are characterized according to a list of one or more interaction parameters. For a}}\newline{}\resizebox{431.997bp}{!}{\mbox{given, named interaction class, several FOM/SOM modules may provide parameters and dimensions.}}\newline{}\resizebox{431.924bp}{!}{\mbox{Interaction parameters are used to associate relevant and useful information with classes of interactions.}}\newline{}\resizebox{432.043bp}{!}{\mbox{Examples of interaction parameters include object class names, object instance attribute values, strings, and}}\newline{}\resizebox{432.005bp}{!}{\mbox{numerical constants. Although some circumstances may require that a subset of the associated parameters be}}\newline{}\resizebox{431.946bp}{!}{\mbox{sent with an interaction, other circumstances require that the full set of parameters be sent. However, for}}\newline{}\resizebox{431.987bp}{!}{\mbox{every interaction class identified in the interaction class structure table, the full set of parameters associated}}\newline{}\resizebox{431.970bp}{!}{\mbox{with that interaction class shall be described in the parameter table. The interaction class}}\newline{}\resizebox{431.965bp}{!}{\mbox{“HLAinteractionRoot” shall be a superclass of all other interaction classes in a FOM or FOM module and in}}\newline{}\resizebox{359.227bp}{!}{\mbox{a SOM or SOM module; parameters may be assigned to it like any other interaction class.}}}
}
\HLAStableID{m4.p052.b09}
\HLAClausePlacedBlock{90.000}{475.804}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.948bp}{!}{\mbox{Unlike class attributes, interaction parameters may not be subscribed to on an individual basis. Thus,}}\newline{}\resizebox{431.969bp}{!}{\mbox{dimension, transportation, and delivery order information is specified at the interaction class level rather}}\newline{}\resizebox{111.012bp}{!}{\mbox{than at the parameter level.}}}
}
\HLAStableID{m4.p052.b10}
\HLAClausePlacedBlock{90.000}{520.803}{432.016}{%
  \HLAClauseParagraph{\resizebox{431.979bp}{!}{\mbox{Interaction parameters may be associated with an interaction class at any level of an interaction class}}\newline{}\resizebox{431.980bp}{!}{\mbox{hierarchy. An interaction class inherits the parameters defined for its superclasses. In fact, the mechanisms}}\newline{}\resizebox{432.016bp}{!}{\mbox{and rules for inheritance of interaction parameters are identical to those of attributes. Thus, the specific}}\newline{}\resizebox{432.015bp}{!}{\mbox{placement of parameters throughout an interaction class hierarchy for a given federation is driven by the}}\newline{}\resizebox{308.972bp}{!}{\mbox{same needs that drive the placement of attributes in an object class hierarchy.}}}
}
\HLAStableID{m4.p052.b11}
\HLAClausePlacedBlock{90.000}{587.684}{84.959}{%
  \HLAMinorClauseHeading{4.6.2 Table format}
}
\HLAStableID{m4.p052.b12}
\HLAClausePlacedBlock{90.000}{611.823}{432.075}{%
  \HLAClauseParagraph{\resizebox{432.070bp}{!}{\mbox{The parameter table of an HLA object model is designed to provide descriptive information about all}}\newline{}\resizebox{432.075bp}{!}{\mbox{parameters of all interactions represented in a federation. The template that shall be used for the parameter}}\newline{}\resizebox{117.183bp}{!}{\mbox{table is provided in Table 12.}}}
}
\HLAStableID{m4.p052.b13}
\HLAClausePlacedBlock{90.000}{655.802}{432.090}{%
  \HLAClauseParagraph{\resizebox{432.042bp}{!}{\mbox{The first column (Interaction) shall contain names of interaction classes from the interaction class structure}}\newline{}\resizebox{432.089bp}{!}{\mbox{table. Interaction class names shall include the parentage (superclasses) of the class to the depth necessary to}}\newline{}\resizebox{431.985bp}{!}{\mbox{uniquely identify the class in this table and may include the full parentage of the class. In general, to reduce}}\newline{}\resizebox{432.062bp}{!}{\mbox{redundancy, parameters should be specified for classes at the highest point in the hierarchy in which they}}\newline{}\resizebox{431.947bp}{!}{\mbox{represent useful information, although this is not required. For example, if all weapon firings include a}}}
}
\end{HLAClauseSemanticPage}

