\HLAClausePlacedBlock{90.000}{69.786}{432.039}{%
  \HLAClauseParagraph{\resizebox{432.019bp}{!}{\mbox{and documented as interaction parameters in the parameter table. For individual federates, SOM developers}}\newline{}\resizebox{431.996bp}{!}{\mbox{should associate with their publishable interaction classes whatever information they feel could be needed}}\newline{}\resizebox{432.039bp}{!}{\mbox{by the subscribers to their interaction classes. In addition, for interaction classes to which the federate can}}\newline{}\resizebox{431.947bp}{!}{\mbox{subscribe, SOM developers should determine what types of information need to be included with those}}\newline{}\resizebox{254.532bp}{!}{\mbox{interactions so that the federate can calculate associated effects.}}}
}
