\HLAClausePlacedBlock{90.000}{464.765}{432.058}{%
  \HLAClauseParagraph{\resizebox{432.037bp}{!}{\mbox{Federations use declaration management (DM) services to enable the flow of instance attribute and}}\newline{}\resizebox{431.873bp}{!}{\mbox{interaction data between federates and to limit the delivery of some data on the basis of object class,}}\newline{}\resizebox{432.042bp}{!}{\mbox{interaction class, and attribute name. This reduction of data may be insufficient to meet the needs of}}\newline{}\resizebox{431.971bp}{!}{\mbox{federations with large numbers of federates, large numbers of objects or interactions in classes, or large}}\newline{}\resizebox{432.042bp}{!}{\mbox{numbers of instance attribute updates per object. Such federations can use DDM services to further reduce}}\newline{}\resizebox{432.041bp}{!}{\mbox{the volume of data delivered to federates. When DDM services are used by a federation, a common}}\newline{}\resizebox{432.058bp}{!}{\mbox{framework for specifying the data distribution model for the federation is essential for the following reasons:}}}
}
\HLAStableID{m4.p054.b07}
\HLAClausePlacedBlock{100.020}{554.824}{421.988}{%
  \HLAClauseDashItem{\resizebox{400.029bp}{!}{\mbox{It provides a commonly understood mechanism for specifying the exchange of public data and}}\newline{}\resizebox{208.486bp}{!}{\mbox{DDM coordination among members of a federation.}}}
}
\HLAStableID{m4.p054.b08}
\HLAClausePlacedBlock{100.020}{581.823}{421.980}{%
  \HLAClauseDashItem{\resizebox{399.922bp}{!}{\mbox{It facilitates the design and application of common tool sets for specification of federation DDM}}\newline{}\resizebox{25.233bp}{!}{\mbox{needs.}}}
}
\HLAStableID{m4.p054.b09}
\HLAClausePlacedBlock{90.000}{617.823}{432.089}{%
  \HLAClauseParagraph{\resizebox{432.040bp}{!}{\mbox{Dimensions are the most fundamental DDM concept. Each attribute or interaction with which DDM}}\newline{}\resizebox{432.025bp}{!}{\mbox{services are used shall have a set of available dimensions, as indicated in the attribute table or parameter}}\newline{}\resizebox{432.000bp}{!}{\mbox{table, respectively. Each set of available dimensions is a subset of all dimensions that are defined in the}}\newline{}\resizebox{431.953bp}{!}{\mbox{dimension table, and defines a multidimensional coordinate system through which federates either express}}\newline{}\resizebox{431.969bp}{!}{\mbox{an interest in receiving data or declare their intention to send data. These intentions are specified by creating}}\newline{}\resizebox{432.010bp}{!}{\mbox{regions within the coordinate system that indicate particular areas of interest. The regions associated with an}}\newline{}\resizebox{432.089bp}{!}{\mbox{instance attribute or interaction shall contain only dimensions that are a subset of the attribute’s or}}}
}
