\HLAClausePlacedBlock{89.999}{69.786}{432.001}{%
  \HLAClauseParagraph{\resizebox{431.977bp}{!}{\mbox{interaction’s available dimensions, but need not contain all of the available dimensions. These regions are}}\newline{}\resizebox{175.458bp}{!}{\mbox{then used in one of the two following ways:}}}
}
\HLAStableID{m4.p055.b02}
\HLAClausePlacedBlock{100.020}{96.785}{422.008}{%
  \HLAClauseDashItem{\resizebox{400.049bp}{!}{\mbox{\textit{Subscription regions}: Sets of ranges that narrow the scope of interest of the subscribing federate in}}\newline{}\resizebox{154.743bp}{!}{\mbox{object class attributes and interactions.}}}
}
\HLAStableID{m4.p055.b03}
\HLAClausePlacedBlock{100.020}{123.785}{421.992}{%
  \HLAClauseDashItem{\resizebox{400.033bp}{!}{\mbox{\textit{Update regions}: Sets of ranges that advertise a publishing federate’s ability to match subscription}}\newline{}\resizebox{35.785bp}{!}{\mbox{interests.}}}
}
\HLAStableID{m4.p055.b04}
\HLAClausePlacedBlock{90.000}{159.784}{432.049}{%
  \HLAClauseParagraph{\resizebox{431.994bp}{!}{\mbox{During development of an HLA federation that uses DDM, it is critical that all federation members achieve}}\newline{}\resizebox{431.980bp}{!}{\mbox{a common understanding of DDM dimensions and their semantics, and that they agree to a common set of}}\newline{}\resizebox{432.019bp}{!}{\mbox{dimension specifications. These agreements are necessary for federates to filter instance attribute updates}}\newline{}\resizebox{432.049bp}{!}{\mbox{and interactions in a correct and consistent manner. This shall include the names of dimensions, the}}\newline{}\resizebox{431.969bp}{!}{\mbox{association of attributes and interactions with dimensions, the federate view of each dimension, and the}}\newline{}\resizebox{432.024bp}{!}{\mbox{default ranges the RTI should supply for available dimensions of attributes and interactions when a federate}}\newline{}\resizebox{188.744bp}{!}{\mbox{does not specify ranges at region creation time.}}}
}
\HLAStableID{m4.p055.b05}
\HLAClausePlacedBlock{90.000}{255.783}{432.050}{%
  \HLAClauseParagraph{\resizebox{432.004bp}{!}{\mbox{The federate view of each dimension is different from the RTI view of each dimension. The federate view}}\newline{}\resizebox{432.004bp}{!}{\mbox{gives each dimension user-defined semantics and an associated data type in which values are expressed. The}}\newline{}\resizebox{432.047bp}{!}{\mbox{federate shall provide a normalization function for each dimension, that maps values from the federate view}}\newline{}\resizebox{431.980bp}{!}{\mbox{of a dimension to values in the RTI view of a dimension. Note that the federate view of the inputs to and}}\newline{}\resizebox{432.005bp}{!}{\mbox{normalization function for a dimension may vary between federates in a federation, particularly in the case}}\newline{}\resizebox{431.969bp}{!}{\mbox{where the input data types are not specified in the FOM data type tables. If the input data types are specified}}\newline{}\resizebox{432.050bp}{!}{\mbox{in the FOM data type tables, the normalization function may represent the federate view for all federates in}}\newline{}\resizebox{146.855bp}{!}{\mbox{the federation, i.e. a federation view.}}}
}
\HLAStableID{m4.p055.b06}
\HLAClausePlacedBlock{90.000}{363.781}{432.086}{%
  \HLAClauseParagraph{\resizebox{432.086bp}{!}{\mbox{The RTI view of a dimension is an interval of nonnegative integers. The lower bound is fixed for all}}\newline{}\resizebox{432.022bp}{!}{\mbox{dimensions, but the upper bound varies by dimension as indicated in the dimension table. The resolution of}}\newline{}\resizebox{431.955bp}{!}{\mbox{the RTI view of the dimension does not have to be the same as the resolution of the federate view of the}}\newline{}\resizebox{67.182bp}{!}{\mbox{same dimension.}}}
}
\HLAStableID{m4.p055.b07}
\HLAClausePlacedBlock{89.998}{423.780}{432.054}{%
  \HLAClauseParagraph{\resizebox{432.004bp}{!}{\mbox{The dimensions form the basis by which update and subscription regions are specified by the federates to the}}\newline{}\resizebox{432.052bp}{!}{\mbox{RTI. By having this agreement about the meaning of dimensions enforced at the federate level, the RTI can}}\newline{}\resizebox{431.957bp}{!}{\mbox{calculate the overlaps of update and subscription regions efficiently without having to understand the}}\newline{}\resizebox{432.007bp}{!}{\mbox{semantics of the dimensions. The dimension table shall record all of the elements necessary to specify this}}\newline{}\resizebox{126.847bp}{!}{\mbox{agreement in a standard format.}}}
}
\HLAStableID{m4.p055.b08}
