\begin{HLAClauseSemanticPage}{55}
\HLAStableID{m4.page.056}
\HLAStableID{m4.p056.b01}
\HLAClausePlacedBlock{90.000}{69.786}{432.062}{%
  \HLAClauseParagraph{\resizebox{432.029bp}{!}{\mbox{The first column (Name) shall specify the name of the dimension. Dimension names shall adhere to HLA}}\newline{}\resizebox{432.022bp}{!}{\mbox{naming conventions (see 3.3.1). The names of dimensions in this column shall be unique. Each dimension}}\newline{}\resizebox{432.062bp}{!}{\mbox{represents a specific characteristic that may be used for filtering. For example, a dimension named}}\newline{}\resizebox{314.839bp}{!}{\mbox{\textit{AltitudeLimits}\space{}might indicate the desire to filter information based on altitude.}}}
}
\HLAStableID{m4.p056.b02}
\HLAClausePlacedBlock{90.000}{127.805}{432.046}{%
  \HLAClauseParagraph{\resizebox{432.046bp}{!}{\mbox{The second column (Input data type) shall identify one or more comma-separated data types for the federate}}\newline{}\resizebox{432.027bp}{!}{\mbox{view of the dimension. Each data type shall be chosen from the name of a data type, as described in 4.14, if}}\newline{}\resizebox{431.981bp}{!}{\mbox{a suitable data type exists. If such a data type does not exist, an unambiguous textual description shall be}}\newline{}\resizebox{322.907bp}{!}{\mbox{provided in the third column and “NA” shall be entered into the second column.}}}
}
\HLAStableID{m4.p056.b03}
\HLAClausePlacedBlock{90.000}{181.804}{432.143}{%
  \HLAClauseParagraph{\resizebox{432.143bp}{!}{\mbox{The third column (Input data type description) shall be used to provide amplifying information on the input}}\newline{}\resizebox{431.840bp}{!}{\mbox{data type.  If no amplifying information is necessary, e,g, when the Input data type is in the FOM, a value of}}\newline{}\resizebox{97.130bp}{!}{\mbox{“NA” shall be provided.}}}
}
\HLAStableID{m4.p056.b04}
\HLAClausePlacedBlock{90.000}{226.804}{432.090}{%
  \HLAClauseParagraph{\resizebox{432.090bp}{!}{\mbox{The fourth column (Dimension upper bound) shall specify the upper bound for the dimension that meets the}}\newline{}\resizebox{431.966bp}{!}{\mbox{federation’s requirement for dimension subrange resolution. The value for this column shall be a positive}}\newline{}\resizebox{431.977bp}{!}{\mbox{integer. This value limits the resolution the RTI provides to meet the federation’s filtering requirements. It is}}\newline{}\resizebox{432.083bp}{!}{\mbox{also the maximum value a federate may use when communicating a range in this dimension to the RTI. For}}\newline{}\resizebox{431.991bp}{!}{\mbox{example, if a dimension represents radio frequencies in the range 88.1 MHz to 107.3 MHz in increments of}}\newline{}\resizebox{431.965bp}{!}{\mbox{.2, a dimension upper bound of 97 is sufficient where 88.1 is mapped to 0 and 107.3 is mapped to 96 in the}}\newline{}\resizebox{431.971bp}{!}{\mbox{RTI view. RTI-defined dimensions have RTI implementation-specific upper bounds that are furnished by}}\newline{}\resizebox{320.613bp}{!}{\mbox{the RTI. These dimensions shall not have an upper bound specified in this table.}}}
}
\HLAStableID{m4.p056.b05}
\HLAClausePlacedBlock{89.999}{332.763}{432.089}{%
  {\HLATimes\fontsize{9.960bp}{10.980bp}\selectfont%
    \resizebox{431.930bp}{!}{\mbox{The fifth column (Normalization function) shall specify the map from a subscription/update region’s}}\newline{}\resizebox{431.980bp}{!}{\mbox{bounding coordinates to nonnegative integer subranges in the range [0, dimension upper bound). Because}}\newline{}\resizebox{432.013bp}{!}{\mbox{regions communicated with an RTI are expressed by bounding coordinates expressed in values from an}}\newline{}\resizebox{432.057bp}{!}{\mbox{RTI’s view of dimensions, normalization functions shall be used by federates to construct regions. For each}}\newline{}\resizebox{431.969bp}{!}{\mbox{dimension in a region, that dimension’s normalization function shall be used to map the dimension bounds}}\newline{}\resizebox{431.863bp}{!}{\mbox{as expressed in the federate view of the dimension to subranges of [0, dimension upper bound). To ensure}}\newline{}\resizebox{431.989bp}{!}{\mbox{that the federation exhibits correct semantics, federation participants should agree on the normalization}}\newline{}\resizebox{432.066bp}{!}{\mbox{functions that they intend to use for each dimension. This agreement shall include the specification of the}}\newline{}\resizebox{431.987bp}{!}{\mbox{normalization function and all values that are to be used by the function. If an attribute or parameter is used}}\newline{}\resizebox{432.036bp}{!}{\mbox{in the normalization function, its class hierarchy shall be specified in dot notation to the extent necessary to}}\newline{}\resizebox{431.953bp}{!}{\mbox{identify the attribute or parameter uniquely. The normalization function shall specify whether it uses a}}\newline{}\resizebox{432.089bp}{!}{\mbox{subset of the entire range or a subset of the data type that is the basis of the dimension type. Example}}\newline{}\resizebox{185.073bp}{!}{\mbox{normalization functions are listed in Annex B.}}\par}
}
\HLAStableID{m4.p056.b06}
\HLAClausePlacedBlock{89.999}{485.821}{432.001}{%
  \HLAClauseParagraph{\resizebox{431.983bp}{!}{\mbox{The sixth column (Output data semantics) shall describe the federation view of the output of the}}\newline{}\resizebox{419.468bp}{!}{\mbox{normalization function. “NA” shall be entered in this column when semantic information is unnecessary.}}}
}
\HLAStableID{m4.p056.b07}
\HLAClausePlacedBlock{89.999}{517.800}{432.099}{%
  {\HLATimes\fontsize{9.960bp}{10.980bp}\selectfont%
    \resizebox{432.028bp}{!}{\mbox{The seventh column (Value when unspecified) shall specify a default range for the dimension that the RTI is}}\newline{}\resizebox{432.035bp}{!}{\mbox{to use in overlap calculations if the dimension is an available dimension of an attribute or interaction and has}}\newline{}\resizebox{432.021bp}{!}{\mbox{been left unspecified when a federate creates a region that is subsequently used (either for update or for}}\newline{}\resizebox{432.098bp}{!}{\mbox{subscription) with the attribute or interaction. The default range is specified as a nonnegative integer}}\newline{}\resizebox{431.948bp}{!}{\mbox{subrange of [0, dimension upper bound). Ranges shall be specified either by two values separated by two}}\newline{}\resizebox{431.962bp}{!}{\mbox{periods or by a single value. All ranges are closed on the lower bound (indicated by a left bracket), and open}}\newline{}\resizebox{431.948bp}{!}{\mbox{on the upper bound (indicated by a right parenthesis). The use of a single value shall specify a “point” range}}\newline{}\resizebox{431.975bp}{!}{\mbox{with the specified point as the lower bound and specified point plus one (1) for the upper bound, so that no}}\newline{}\resizebox{431.872bp}{!}{\mbox{other valid value lies between these points. An entry of “Excluded” indicates that the dimension shall not be}}\newline{}\resizebox{360.230bp}{!}{\mbox{used in overlap calculations unless a specific range is provided in the region specification.}}\par}
}
\HLAStableID{m4.p056.b08}
\HLAClausePlacedBlock{89.999}{639.639}{104.963}{%
  \HLAMinorClauseHeading{4.7.3 Inclusion criteria}
}
\HLAStableID{m4.p056.b09}
\HLAClausePlacedBlock{89.999}{663.778}{432.021}{%
  \HLAClauseParagraph{\resizebox{431.952bp}{!}{\mbox{Federations that require more data reduction than the class-based filtering provided by DM services should}}\newline{}\resizebox{432.021bp}{!}{\mbox{use the dimension table to document federation-wide agreements on the semantics and use of DDM}}\newline{}\resizebox{431.980bp}{!}{\mbox{dimensions. The type and normalization function information is guidance to federates on the consistent use}}\newline{}\resizebox{431.997bp}{!}{\mbox{of dimensions to maintain correct DDM semantics across the federation. Similarly, federates that normally}}}
}
\end{HLAClauseSemanticPage}

