\HLAClausePlacedBlock{89.999}{124.806}{432.096}{%
  \HLAClauseParagraph{\resizebox{432.076bp}{!}{\mbox{Table 15 illustrates an example of the use of the dimension table. The first dimension, SodaFlavor, is an}}\newline{}\resizebox{431.956bp}{!}{\mbox{enumerated dimension, and its linearEnumerated normalization function (see Annex B) would map Cola,}}\newline{}\resizebox{432.095bp}{!}{\mbox{Orange, RootBeer, and Cream, represented by [101 .. 105), to [0 .. 4).  The second dimension, Sweetener, is}}\newline{}\resizebox{431.952bp}{!}{\mbox{also an enumerated dimension. The third dimension, WaiterServerId, is an integer-based dimension and}}\newline{}\resizebox{431.994bp}{!}{\mbox{would be mapped at uniform intervals across the ranges [0 .. 20). The fourth dimension, Gluten, illustrates}}\newline{}\resizebox{431.966bp}{!}{\mbox{normalizing multiple input values to a dimension identifying the suitability of a menu item for individuals}}\newline{}\resizebox{233.365bp}{!}{\mbox{with gluten intolerance, Celiac disease, or a wheat allergy.}}}
}
\HLAStableID{m4.p057.b04}
\HLAClausePlacedBlock{89.998}{218.764}{432.032}{%
  \HLAClauseParagraph{\resizebox{432.023bp}{!}{\mbox{The first, third, and fourth dimensions have a normalization function specified in the table because all}}\newline{}\resizebox{432.026bp}{!}{\mbox{federates use the same FOM data to calculate the range on those dimensions. The first and third dimensions}}\newline{}\resizebox{432.032bp}{!}{\mbox{do not provide any input data description, “NA,” because their input data are single FOM values. Clear input}}\newline{}\resizebox{423.794bp}{!}{\mbox{data descriptions are particularly important for dimensions whose input data types are not from the FOM.}}}
}
