\HLAStableID{m4.p059.b02}
\HLAClausePlacedBlock{90.000}{197.765}{432.057}{%
  \HLAClauseParagraph{\resizebox{432.019bp}{!}{\mbox{The second column (Data type) shall identify the data type of the time value. This data type shall be chosen}}\newline{}\resizebox{431.969bp}{!}{\mbox{from the name of any simple, enumerated, array, fixed record, or variant record data type described in 4.14.}}\newline{}\resizebox{432.057bp}{!}{\mbox{“NA” shall be entered in this column when timestamp or lookahead information is inappropriate to the}}\newline{}\resizebox{88.505bp}{!}{\mbox{federate or federation.}}}
