\HLAStableID{m4.p059.b05}
\HLAClausePlacedBlock{90.000}{311.763}{432.053}{%
  \HLAClauseParagraph{\resizebox{431.998bp}{!}{\mbox{All federations shall document their use of logical time and logical time interval via the time representation}}\newline{}\resizebox{431.994bp}{!}{\mbox{table in a FOM and relevant FOM modules. All federates shall document their representation of logical time}}\newline{}\resizebox{432.053bp}{!}{\mbox{via the time representation table in a SOM and relevant SOM modules to the extent that it is used in the}}\newline{}\resizebox{432.022bp}{!}{\mbox{federate. For federates that support lookahead, the representation of logical time interval shall be}}\newline{}\resizebox{338.099bp}{!}{\mbox{documented via the time representation table in a SOM and relevant SOM modules.}}}
