  \HLAClauseParagraph{\resizebox{431.984bp}{!}{\mbox{All federations that make use of user-supplied tags shall document the appropriate representations of these}}\newline{}\resizebox{432.051bp}{!}{\mbox{tags in the user-supplied tag table in a FOM and relevant FOM modules. All federates that can make use of}}\newline{}\resizebox{432.039bp}{!}{\mbox{user-supplied tags shall document their tag representations via the user-supplied tag table in a SOM and}}\newline{}\resizebox{95.215bp}{!}{\mbox{relevant SOM modules.}}}
