\HLAClausePlacedBlock{90.000}{69.786}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.990bp}{!}{\mbox{The second column (Tag data type) shall identify the data type of the user-supplied tag for those}}\newline{}\resizebox{431.946bp}{!}{\mbox{synchronization points that the federate or federation designate as providing a user-supplied tag. If used, this}}\newline{}\resizebox{431.997bp}{!}{\mbox{data type shall be chosen from the name of any simple, enumerated, reference, array, fixed record, or variant}}\newline{}\resizebox{431.994bp}{!}{\mbox{record data type described in 4.14. If no user-supplied tag is provided, a value of “NA” should be used for}}\newline{}\resizebox{68.244bp}{!}{\mbox{the tag data type.}}}
}
\HLAStableID{m4.p062.b02}
\HLAClausePlacedBlock{90.000}{139.804}{432.015}{%
  \HLAClauseParagraph{\resizebox{432.015bp}{!}{\mbox{The third column (Capability) shall indicate the level of interaction that a federate is capable of honoring.}}\newline{}\resizebox{431.861bp}{!}{\mbox{For FOMs and FOM modules, this column does not apply and shall contain “NA.” For SOMs and SOM}}\newline{}\resizebox{211.274bp}{!}{\mbox{modules, valid values for this column are as follows:}}}
}
\HLAStableID{m4.p062.b03}
\HLAClausePlacedBlock{100.020}{185.764}{421.980}{%
