\HLAClausePlacedBlock{90.000}{118.805}{432.068}{%
  \HLAClauseParagraph{\resizebox{431.973bp}{!}{\mbox{The HLA RTI provides a mechanism for reducing the update rate in a federation. The update rate may be}}\newline{}\resizebox{431.947bp}{!}{\mbox{reduced by the RTI for attribute updates using best effort transportation. For attribute updates using reliable}}\newline{}\resizebox{432.068bp}{!}{\mbox{or best effort transportation, the RTI also provides signaling that enables owning federates to adjust their}}\newline{}\resizebox{432.016bp}{!}{\mbox{update rates. The update rate table provides a means for aligning specific names with maximum update}}\newline{}\resizebox{307.466bp}{!}{\mbox{rates. The use of update rates is described in detail in IEEE Std 1516.1-2025.}}}
}
\HLAStableID{m4.p064.b04}
