}
\HLAStableID{m4.p064.b07}
\HLAClausePlacedBlock{90.000}{374.763}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.959bp}{!}{\mbox{The second column (Maximum update rate) shall specify the associated maximum update rate in Hz using a}}\newline{}\resizebox{136.854bp}{!}{\mbox{decimal number greater than zero.}}}
}
