\HLAStableID{m4.p066.b01}
\HLAClausePlacedBlock{90.000}{69.786}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.996bp}{!}{\mbox{The first column (Switch) presents the name of the switch whose setting shall be provided in this table. The}}\newline{}\resizebox{174.303bp}{!}{\mbox{definitions of these switches are as follows:}}}
}
\HLAStableID{m4.p066.b02}
\HLAClausePlacedBlock{100.020}{103.805}{421.990}{%
  \HLAClauseDashItem{\resizebox{399.985bp}{!}{\mbox{\textit{Auto Provide}: Whether the RTI should automatically solicit updates from instance attribute owners}}\newline{}\resizebox{400.009bp}{!}{\mbox{when an object is discovered. The value for a particular federation execution can be changed during}}\newline{}\makebox[400.030bp][l]{the\hfill{}execution,\hfill{}using\hfill{}the\hfill{}MOM\hfill{}interaction}\newline{}\resizebox{323.318bp}{!}{\mbox{HLAinteractionRoot.HLAmanager.HLAfederation.HLAadjust.HLAsetSwitches.}}}
}
\HLAStableID{m4.p066.b03}
\HLAClausePlacedBlock{100.020}{154.804}{422.037}{%
  \HLAClauseDashItem{\resizebox{400.032bp}{!}{\mbox{\textit{Convey Region Designator Sets}: Whether the RTI should provide the optional\space{}\textit{Sent Region Set}}}\newline{}\resizebox{399.991bp}{!}{\mbox{argument with invocations of\space{}\textit{Reflect Attribute Values}\space{}and\space{}\textit{Receive Interaction}. The value of this}}\newline{}\resizebox{400.076bp}{!}{\mbox{switch is used as the initial value for each joining federate.  The value for each joined federate can be}}\newline{}\makebox[399.978bp][l]{changed\hfill{}during\hfill{}the\hfill{}federation\hfill{}execution\hfill{}using\hfill{}the\hfill{}MOM\hfill{}interaction}\newline{}\makebox[399.903bp][l]{HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches\hfill{}or\hfill{}through\hfill{}the}\newline{}\resizebox{259.592bp}{!}{\mbox{invocation of\space{}\textit{Set Convey Region Designator Sets Switch}\space{}service.}}}
}
\HLAStableID{m4.p066.b04}
\HLAClausePlacedBlock{100.021}{229.803}{422.048}{%
  \HLAClauseDashItem{\resizebox{400.038bp}{!}{\mbox{\textit{Attribute Scope Advisory}: Whether the RTI should advise federates when attributes of an object}}\newline{}\resizebox{400.088bp}{!}{\mbox{instance come into or go out of scope. The value of this switch is used as the initial value for each}}\newline{}\resizebox{400.056bp}{!}{\mbox{joining federate. The value for each joined federate can be changed during the federation execution}}\newline{}\makebox[400.047bp][l]{using\hfill{}the\hfill{}MOM\hfill{}interaction}\newline{}\makebox[399.902bp][l]{HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches\hfill{}or\hfill{}through\hfill{}the}\newline{}\resizebox{251.859bp}{!}{\mbox{invocation of the Set Attribute Scope Advisory Switch service.}}}
}
\HLAStableID{m4.p066.b05}
\HLAClausePlacedBlock{100.021}{304.802}{421.990}{%
  \HLAClauseDashItem{\resizebox{400.025bp}{!}{\mbox{\textit{Attribute Relevance Advisory}: Whether the RTI should advise federates about whether they should}}\newline{}\resizebox{400.026bp}{!}{\mbox{provide attribute value updates for the value of an attribute of an object instance; the RTI bases this}}\newline{}\resizebox{400.031bp}{!}{\mbox{advisory on whether the value of the instance attribute is required by other federates. The value of}}\newline{}\resizebox{399.982bp}{!}{\mbox{this switch is used as the initial value for each joining federate. The value for each joined federate}}\newline{}\makebox[399.970bp][l]{can\hfill{}be\hfill{}changed\hfill{}during\hfill{}the\hfill{}federation\hfill{}execution\hfill{}using\hfill{}the\hfill{}MOM\hfill{}interaction}\newline{}\makebox[399.902bp][l]{HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches\hfill{}or\hfill{}through\hfill{}the}\newline{}\resizebox{269.072bp}{!}{\mbox{invocation of the Set Attribute Relevance Advisory Switch service.}}}
}
\HLAStableID{m4.p066.b06}
\HLAClausePlacedBlock{100.020}{391.801}{422.017}{%
  \HLAClauseDashItem{\resizebox{400.045bp}{!}{\mbox{\textit{Object Class Relevance Advisory}: Whether the RTI should advise federates about whether they}}\newline{}\resizebox{400.004bp}{!}{\mbox{should register instances of an object class; the RTI bases this advisory on whether other federates}}\newline{}\resizebox{400.057bp}{!}{\mbox{have expressed an interest in attribute(s) of the object class. The value for each joined federate can}}\newline{}\makebox[400.022bp][l]{be\hfill{}changed\hfill{}during\hfill{}the\hfill{}federation\hfill{}execution\hfill{}using\hfill{}the\hfill{}MOM\hfill{}interaction}\newline{}\makebox[399.902bp][l]{HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches\hfill{}or\hfill{}through\hfill{}the}\newline{}\resizebox{286.252bp}{!}{\mbox{invocation of the Set Object Class Relevance Advisory Switch service.}}}
}
\HLAStableID{m4.p066.b07}
\HLAClausePlacedBlock{100.020}{466.799}{422.034}{%
  \HLAClauseDashItem{\resizebox{399.986bp}{!}{\mbox{\textit{Interaction Relevance Advisory}: Whether the RTI should advise federates about whether they}}\newline{}\resizebox{400.008bp}{!}{\mbox{should send interactions of an interaction class; the RTI bases this advisory on whether other}}\newline{}\resizebox{400.075bp}{!}{\mbox{federates have expressed an interest in the interaction class. The value of this switch is used as the}}\newline{}\resizebox{399.981bp}{!}{\mbox{initial value for each joining federate. The value for each joined federate can be changed during the}}\newline{}\makebox[400.013bp][l]{federation\hfill{}execution\hfill{}using\hfill{}the\hfill{}MOM\hfill{}interaction}\newline{}\makebox[399.902bp][l]{HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches\hfill{}or\hfill{}through\hfill{}the}\newline{}\resizebox{278.686bp}{!}{\mbox{invocation of the Set Interaction Relevance Advisory Switch service.}}}
}
\HLAStableID{m4.p066.b08}
\HLAClausePlacedBlock{100.019}{553.798}{421.981}{%
  \HLAClauseDashItem{\resizebox{399.998bp}{!}{\mbox{\textit{Service Reporting}: Whether the RTI should report service invocations using MOM. The value of}}\newline{}\resizebox{399.982bp}{!}{\mbox{this switch is used as the initial value for each joining federate. The value for each joined federate}}\newline{}\makebox[399.970bp][l]{can\hfill{}be\hfill{}changed\hfill{}during\hfill{}the\hfill{}federation\hfill{}execution\hfill{}using\hfill{}the\hfill{}MOM\hfill{}interaction}\newline{}\makebox[399.903bp][l]{HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches\hfill{}or\hfill{}through\hfill{}the}\newline{}\resizebox{221.556bp}{!}{\mbox{invocation of the Set Service Reporting Switch service.}}}
}
\HLAStableID{m4.p066.b09}
\HLAClausePlacedBlock{100.019}{616.797}{421.981}{%
  \HLAClauseDashItem{\resizebox{399.968bp}{!}{\mbox{\textit{Exception Reporting}: Whether the RTI should report exceptions using MOM. The value of this}}\newline{}\resizebox{400.022bp}{!}{\mbox{switch is used as the initial value for each joining federate. The value for each joined federate can be}}\newline{}\makebox[399.978bp][l]{changed\hfill{}during\hfill{}the\hfill{}federation\hfill{}execution\hfill{}using\hfill{}the\hfill{}MOM\hfill{}interaction}\newline{}\makebox[399.903bp][l]{HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches\hfill{}or\hfill{}through\hfill{}the}\newline{}\resizebox{216.825bp}{!}{\mbox{invocation of the Exception Reporting Switch service.}}}
}
\HLAStableID{m4.p066.b10}
\HLAClausePlacedBlock{100.019}{679.796}{422.027}{%
  \HLAClauseDashItem{\resizebox{400.067bp}{!}{\mbox{\textit{Delay Subscription Evaluation}: Whether the RTI should filter messages as soon as possible to}}\newline{}\resizebox{399.966bp}{!}{\mbox{reflect the current known federate subscriptions, if disabled, or if enabled, defer subscription}}}
}
\end{HLAClauseSemanticPage}

% M4 semantic reconstruction of physical page 67 / printed page 66.
\begin{HLAClauseSemanticPage}{66}
\HLAStableID{m4.page.067}
\HLAStableID{m4.p067.b01}
\HLAClausePlacedBlock{121.980}{69.786}{400.020}{%
  \HLAClauseParagraph{\resizebox{399.952bp}{!}{\mbox{evaluation until only just before delivery to the federate. The value of this switch is used for the}}\newline{}\resizebox{283.945bp}{!}{\mbox{entire federation. It cannot be changed during the federation execution.}}}
}
\HLAStableID{m4.p067.b02}
\HLAClausePlacedBlock{100.020}{96.785}{421.996}{%
  \HLAClauseDashItem{\resizebox{400.035bp}{!}{\mbox{\textit{Non-Regulated Grant}: Whether the RTI should grant time advances to constrained joined federates}}\newline{}\resizebox{399.963bp}{!}{\mbox{when there are no regulating joined federates. The value of this switch is used for the entire}}\newline{}\resizebox{258.659bp}{!}{\mbox{federation. It cannot be changed during the federation execution.}}}
}
\HLAStableID{m4.p067.b03}
\HLAClausePlacedBlock{100.020}{135.785}{422.093}{%
  \HLAClauseDashItem{\resizebox{399.968bp}{!}{\mbox{\textit{Automatic Resign Action}: What resign action the RTI shall perform when it invokes the}}\newline{}\resizebox{400.071bp}{!}{\mbox{\textit{Resign Federation Execution}\space{}service on behalf of a federate that was lost due to a fault. The}}\newline{}\resizebox{399.989bp}{!}{\mbox{value shall be one of the following: UnconditionallyDivestAttributes, DeleteObjects,}}\newline{}\resizebox{400.028bp}{!}{\mbox{CancelPendingOwnershipAcquisitions, DeleteObjectsThenDivest, CancelThenDeleteThenDivest,}}\newline{}\resizebox{400.133bp}{!}{\mbox{NoAction. The value for each joined federate can be changed during the federation execution using}}\newline{}\resizebox{400.107bp}{!}{\mbox{the MOM interaction HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches}}\newline{}\resizebox{320.374bp}{!}{\mbox{or through the invocation of the Set Automatic Resign Directive Switch service.}}}
}
\HLAStableID{m4.p067.b04}
\HLAClausePlacedBlock{100.020}{222.783}{422.031}{%
  \HLAClauseDashItem{\resizebox{399.916bp}{!}{\mbox{\textit{Send Service Reports To File}: Whether MOM service reports are recorded in a file instead of sent to}}\newline{}\resizebox{399.981bp}{!}{\mbox{subscribed federates. The value of this switch is used as the initial value for each joining federate.}}\newline{}\resizebox{400.028bp}{!}{\mbox{The value for each joined federate can be changed during the federation execution using the MOM}}\newline{}\makebox[400.070bp][l]{interaction\hfill{}HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetSwitches\hfill{}or}\newline{}\resizebox{315.098bp}{!}{\mbox{through the invocation of the Set Send Service Reports To File Switch service.}}}
}
\HLAStableID{m4.p067.b05}
\HLAClausePlacedBlock{100.021}{285.782}{421.979}{%
  \HLAClauseDashItem{\resizebox{400.002bp}{!}{\mbox{\textit{Advisories Use Known Class:}\space{}Whether the RTI shall calculate attribute relevance advisories based}}\newline{}\resizebox{399.966bp}{!}{\mbox{on the known class of discovered instances or on subscription data only. The value of this switch is}}\newline{}\resizebox{333.634bp}{!}{\mbox{used for the entire federation. It cannot be changed during the federation execution.}}}
}
\HLAStableID{m4.p067.b06}
\HLAClausePlacedBlock{100.022}{324.782}{422.029}{%
  \HLAClauseDashItem{\resizebox{400.069bp}{!}{\mbox{\textit{Allow Relaxed DDM}: Whether an RTI implementation of DDM can use relaxed region overlap}}\newline{}\resizebox{400.026bp}{!}{\mbox{criteria that may relax the filtering of updates and interactions a federate may receive. The specified}}\newline{}\resizebox{400.058bp}{!}{\mbox{criteria for region overlaps rely strictly on comparing region range values. If this switch is enabled,}}\newline{}\resizebox{399.988bp}{!}{\mbox{the RTI may inject additional criteria for determining region overlaps such that the set of overlapped}}\newline{}\resizebox{399.993bp}{!}{\mbox{regions is a superset of the overlapped regions using the specified criteria. The value of this switch is}}\newline{}\resizebox{333.634bp}{!}{\mbox{used for the entire federation. It cannot be changed during the federation execution.}}}
}
\HLAStableID{m4.p067.b07}
\HLAClausePlacedBlock{90.002}{406.800}{431.998}{%
  \HLAClauseParagraph{\resizebox{431.920bp}{!}{\mbox{The second column (Setting) shall specify the setting for the switch. For SOMs and SOM modules, these}}\newline{}\resizebox{431.902bp}{!}{\mbox{entries are optional; “NA” shall be entered for all rows where no value is appropriate. For FOMs and FOM}}\newline{}\resizebox{431.955bp}{!}{\mbox{modules, entries shall be provided for all rows; valid values (with the exception of\space{}\textit{Automatic Resign Action,}}}\newline{}\resizebox{224.562bp}{!}{\mbox{whose valid values are described above)\space{}are as follows:}}}
}
\HLAStableID{m4.p067.b08}
\HLAClausePlacedBlock{100.022}{464.760}{421.978}{%
  \HLAClauseDashItem{\resizebox{358.420bp}{!}{\mbox{\textit{Enabled}: The switch is enabled, and the RTI should perform the action when appropriate.}}}
}
\HLAStableID{m4.p067.b09}
\HLAClausePlacedBlock{100.022}{479.759}{421.978}{%
  \HLAClauseDashItem{\resizebox{309.009bp}{!}{\mbox{\textit{Disabled}: The switch is disabled, and the RTI should not perform the action.}}}
}
\HLAStableID{m4.p067.b10}
\HLAClausePlacedBlock{90.001}{501.639}{110.534}{%
  \HLAMinorClauseHeading{4.13.3 Inclusion criteria}
}
\HLAStableID{m4.p067.b11}
\HLAClausePlacedBlock{90.001}{523.798}{432.026}{%
  \HLAClauseParagraph{\resizebox{432.015bp}{!}{\mbox{The switch settings specified in this table shall be included in all FOMs and relevant FOM modules to}}\newline{}\resizebox{432.026bp}{!}{\mbox{document agreements among federation developers as to the initial values of the switches at the beginning of}}\newline{}\resizebox{431.973bp}{!}{\mbox{federation execution. The switch settings may optionally be provided in SOMs and SOM modules to}}\newline{}\resizebox{246.828bp}{!}{\mbox{indicate switch settings that are desired by federate designers.}}}
}
\HLAStableID{m4.p067.b12}
\HLAClausePlacedBlock{90.001}{577.798}{431.999}{%
  \HLAClauseParagraph{\resizebox{431.987bp}{!}{\mbox{If a specific switch setting is not included in the FOM, or if the switch settings table is not included, the}}\newline{}\resizebox{431.954bp}{!}{\mbox{default value for all switches shall be “Disabled” with the exception of the\space{}\textit{Automatic Resign Action}\space{}switch,}}\newline{}\resizebox{223.973bp}{!}{\mbox{whose default shall be “CancelThenDeleteThenDivest”.}}}
}
\HLAStableID{m4.p067.b13}
\HLAClausePlacedBlock{90.001}{620.677}{71.645}{%
  \HLAMinorClauseHeading{4.13.4 Example}
}
\HLAStableID{m4.p067.b14}
\HLAClausePlacedBlock{90.001}{642.777}{432.007}{%
  \HLAClauseParagraph{\resizebox{431.997bp}{!}{\mbox{Table 28 shows an example of the switches table for the Restaurant federate. The Interaction, Object Class}}\newline{}\resizebox{431.980bp}{!}{\mbox{and Attribute Advisory switches are enabled to allow the RTI to indicate whether a federate should send}}\newline{}\resizebox{432.007bp}{!}{\mbox{interactions, register objects, and update attribute instance values based on the subscriptions of the other}}\newline{}\resizebox{431.995bp}{!}{\mbox{federates. The Auto Provide switch is enabled so that existing federates are prompted to update values for}}\newline{}\resizebox{431.963bp}{!}{\mbox{their owned attribute instances for objects instances that have been discovered by newly subscribed or late}}}
}
\end{HLAClauseSemanticPage}

