}
\HLAStableID{m4.p068.b04}
\HLAClausePlacedBlock{90.000}{243.065}{432.119}{%
  \HLAClauseParagraph{\resizebox{431.996bp}{!}{\mbox{Several of the OMT tables (attribute table, parameter table, dimension table, time representation table,}}\newline{}\resizebox{432.040bp}{!}{\mbox{user-supplied tag table, and synchronization table) provide columns for data type specifications. This}}\newline{}\resizebox{432.071bp}{!}{\mbox{subclause describes additional tables that shall be used to specify the characteristics of these data types. A}}\newline{}\resizebox{432.007bp}{!}{\mbox{data type used in these tables shall be specified in a row of one of the following tables: simple data type}}\newline{}\resizebox{432.007bp}{!}{\mbox{table, enumerated data type table, reference data type table, fixed record data type table, array data type}}\newline{}\resizebox{431.898bp}{!}{\mbox{table, or variant record data type table. As described in 4.14.3 through 4.14.8, members of these data type}}\newline{}\resizebox{432.119bp}{!}{\mbox{tables may contain members of other data type tables in order to create arbitrarily complex data types. In}}\newline{}\resizebox{431.948bp}{!}{\mbox{addition, the name of any data type or data representation shall be unique among all data types and data}}\newline{}\resizebox{62.982bp}{!}{\mbox{representations.}}}
}
\HLAStableID{m4.p068.b05}
\HLAClausePlacedBlock{90.000}{351.944}{110.533}{%
  \HLAMinorClauseHeading{4.14.2 Inclusion criteria}
}
\HLAStableID{m4.p068.b06}
\HLAClausePlacedBlock{90.000}{374.043}{432.013}{%
  \HLAClauseParagraph{\resizebox{431.983bp}{!}{\mbox{All federations shall describe and document the data types that are referenced in any OMT table that requires}}\newline{}\resizebox{431.993bp}{!}{\mbox{the specification of data types (attribute table, parameter table, dimension table, time representation table,}}\newline{}\resizebox{432.013bp}{!}{\mbox{user-supplied tag table, and synchronization table) in their FOM and relevant FOM modules. They shall also}}\newline{}\resizebox{431.938bp}{!}{\mbox{describe and document data types referenced in other data type tables. Similarly, federates shall document}}\newline{}\resizebox{331.154bp}{!}{\mbox{the data types referenced in these tables in their SOM and relevant SOM modules.}}}
}
\HLAStableID{m4.p068.b07}
\HLAClausePlacedBlock{90.000}{438.943}{178.838}{%
  \HLAMinorClauseHeading{4.14.3 Basic data representation table}
}
\HLAStableID{m4.p068.b08}
\HLAClausePlacedBlock{89.997}{461.241}{432.098}{%
  {\HLATimes\fontsize{9.000bp}{9.000bp}\selectfont\raggedright
    \resizebox{432.012bp}{!}{\mbox{Basic data representation is the underpinning of all OMT data types. A set of widely-used basic data representations}}\newline{}
    \resizebox{432.078bp}{!}{\mbox{have been pre-defined for use as the basis for the OMT data types and this list may be expanded. These basic data}}\newline{}
    \resizebox{431.977bp}{!}{\mbox{representations cannot be directly used as a named data type in any OMT data type table, but rather are the basis upon}}\newline{}
    \resizebox{432.042bp}{!}{\mbox{which named data types are built. Table 29 illustrates the format that shall be used for the basic representation of data.}}\newline{}
    \makebox[432.053bp][l]{The table includes a predefined set of data representations (\textit{HLAinteger16BE,}\hfill{}\space{}\textit{HLAinteger32BE, HLAinteger64BE,}}\newline{}
    \resizebox{432.068bp}{!}{\mbox{\textit{HLAunsignedInteger16BE, HLAunsignedInteger32BE, HLAunsignedInteger64BE, HLAfloat32BE, HLAfloat64BE,}}}\newline{}
    \makebox[432.055bp][l]{\textit{HLAoctetPairBE,}\hfill{}\textit{HLAinteger16LE,}\hfill{}\textit{HLAinteger32LE,}\hfill{}\textit{HLAinteger64LE,}\hfill{}\textit{HLAunsignedInteger8,}}\newline{}
    \resizebox{432.046bp}{!}{\mbox{\textit{HLAunsignedInteger16LE, HLAunsignedInteger32LE, HLAunsignedInteger64LE, HLAfloat32LE, HLAfloat64LE,}}}\newline{}
    \resizebox{432.097bp}{!}{\mbox{\textit{HLAoctetPairLE, HLAoctet}) that shall be present in all FOMs, SOMs, and MIMs; other entries may be added after these}}\newline{}
    \resizebox{432.011bp}{!}{\mbox{entries. Although these entries shall be present, there is no requirement that federates or federations use or support all of}}\newline{}
    \resizebox{79.617bp}{!}{\mbox{these representations..}}\par}
}
\HLAStableID{m4.p068.b09}
\HLAClausePlacedBlock{90.000}{572.046}{432.016}{%
  \HLAClauseParagraph{\resizebox{432.016bp}{!}{\mbox{The first column (Name) shall identify the name of the basic data representation. Basic data representation}}\newline{}\resizebox{239.529bp}{!}{\mbox{names shall adhere to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p068.b10}
\HLAClausePlacedBlock{90.000}{606.065}{432.080}{%
  \HLAClauseParagraph{\resizebox{432.080bp}{!}{\mbox{The second column (Size in bits) shall define the size of the data representation in terms of the number of}}\newline{}\resizebox{432.028bp}{!}{\mbox{bits contained in the data representation. Entries in this column shall be consistent with the associated}}\newline{}\resizebox{89.861bp}{!}{\mbox{encoding descriptions.}}}
}
\HLAStableID{m4.p068.b11}
\HLAClausePlacedBlock{90.000}{649.084}{432.000}{%
  \HLAClauseParagraph{\resizebox{394.701bp}{!}{\mbox{The third column (Interpretation) shall describe how the data representation should be interpreted.}}}
}
