\HLAClausePlacedBlock{90.000}{69.786}{432.000}{%
  \HLAClauseParagraph{\resizebox{432.000bp}{!}{\mbox{all FOMs, SOMs, and MIMs; additional entries may be added after them. Although these required data types}}\newline{}\resizebox{307.935bp}{!}{\mbox{shall be present, no requirement exists that federates or federations use them.}}}
}
\HLAStableID{m4.p071.b02}
\HLAClausePlacedBlock{90.000}{372.786}{432.060}{%
  \HLAClauseParagraph{\resizebox{432.060bp}{!}{\mbox{The first column (Name) shall identify the name of the simple data type. Simple data type names shall}}\newline{}\resizebox{190.098bp}{!}{\mbox{adhere to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p071.b03}
\HLAClausePlacedBlock{90.000}{406.805}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.966bp}{!}{\mbox{The second column (Representation) shall identify the basic data representation of this data type. It shall be}}\newline{}\resizebox{222.901bp}{!}{\mbox{the name of a row in the basic data representation table.}}}
}
\HLAStableID{m4.p071.b04}
\HLAClausePlacedBlock{90.000}{440.765}{432.017}{%
  \HLAClauseParagraph{\resizebox{432.017bp}{!}{\mbox{The third column (Units) shall identify the units of measure (e.g., m, km, kg) for the data type whenever}}\newline{}\resizebox{431.911bp}{!}{\mbox{such units exist. Any units entered in this column also specify the units of the entries in the Resolution and}}\newline{}\resizebox{396.428bp}{!}{\mbox{Accuracy columns that follow it. “NA” shall be entered in this column for data types without units.}}}
}
\HLAStableID{m4.p071.b05}
\HLAClausePlacedBlock{90.000}{486.784}{432.063}{%
  \HLAClauseParagraph{\resizebox{431.929bp}{!}{\mbox{The fourth column (Resolution) shall describe the precision of measure for the data type. In general, this}}\newline{}\resizebox{432.011bp}{!}{\mbox{entry specifies the smallest resolvable increment between different values that can be effectively}}\newline{}\resizebox{431.962bp}{!}{\mbox{discriminated. In some situations, such as when values are stored in floating point data types, the resolution}}\newline{}\resizebox{431.962bp}{!}{\mbox{might vary with the magnitude of the value. Hence, in cases like this, a better sense of the resolution may be}}\newline{}\resizebox{432.063bp}{!}{\mbox{conveyed by the data type. “NA” shall be entered in this column for data types for which resolution}}\newline{}\resizebox{110.524bp}{!}{\mbox{information does not apply.}}}
}
\HLAStableID{m4.p071.b06}
\HLAClausePlacedBlock{90.000}{570.783}{432.058}{%
  \HLAClauseParagraph{\resizebox{431.976bp}{!}{\mbox{The fifth column (Accuracy) shall describe maximum deviation of the value from its intended value in the}}\newline{}\resizebox{432.016bp}{!}{\mbox{federate or federation. This is ordinarily expressed as a dimensioned value, but it may also be\space{}\textit{perfect}\space{}for}}\newline{}\resizebox{432.058bp}{!}{\mbox{discrete values. “NA” shall be entered in this column for data types for which accuracy information does not}}\newline{}\resizebox{24.686bp}{!}{\mbox{apply.}}}
}
\HLAStableID{m4.p071.b07}
\HLAClausePlacedBlock{90.000}{630.782}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.998bp}{!}{\mbox{The sixth column (Semantics) shall describe the meaning and use of the data type. “NA” shall be entered in}}\newline{}\resizebox{225.699bp}{!}{\mbox{this column when semantics information is unnecessary.}}}
}
\HLAStableID{m4.p071.b08}
\HLAClausePlacedBlock{90.000}{667.021}{432.026}{%
  \HLAClauseParagraph{\resizebox{431.932bp}{!}{\mbox{An example of the use of the simple data type table is provided in Table 32. These data types are used in}}\newline{}\resizebox{432.026bp}{!}{\mbox{examples elsewhere in this document. The examples in this table are aimed at a big-endian platform; for a}}\newline{}\resizebox{432.004bp}{!}{\mbox{little-endian platform substitute BE with LE. Note that\space{}\textit{DrinkCount}\space{}is used for attributes and for dimension}}\newline{}\resizebox{280.631bp}{!}{\mbox{definition, and\space{}\textit{EmployeeId}\space{}is used for dimension and array definition.}}}
}
