\HLAClausePlacedBlock{90.000}{392.866}{161.016}{%
  \HLAMinorClauseHeading{4.14.5 Enumerated data type table}
}
\HLAStableID{m4.p072.b02}
\HLAClausePlacedBlock{90.000}{417.005}{432.024}{%
  \HLAClauseParagraph{\resizebox{432.024bp}{!}{\mbox{The enumerated data type table shall be used to describe data elements that can take on a finite discrete set of}}\newline{}\resizebox{432.016bp}{!}{\mbox{possible values. For a given, named enumerated data type, several FOM/SOM modules may provide}}\newline{}\resizebox{431.882bp}{!}{\mbox{enumerators and values. Table 33 illustrates the format that shall be used for the enumerated data type table.}}\newline{}\resizebox{431.920bp}{!}{\mbox{The table includes a single predefined data type (\textit{HLAboolean}) that shall be present in all FOMs, SOMs, and}}\newline{}\resizebox{431.985bp}{!}{\mbox{MIMs; additional entries may be added after it. Although this required data type shall be present, no}}\newline{}\resizebox{205.638bp}{!}{\mbox{requirement exists that federates or federations use.}}}
}
\HLAStableID{m4.p072.b03}
\HLAClausePlacedBlock{90.000}{493.024}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.964bp}{!}{\mbox{The first column (Name) shall identify the name of the enumerated data type. Enumerated data type names}}\newline{}\resizebox{211.558bp}{!}{\mbox{shall adhere to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p072.b04}
\HLAClausePlacedBlock{90.000}{670.024}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.940bp}{!}{\mbox{The second column (Representation) shall identify the basic data representation that forms the basis of this}}\newline{}\resizebox{422.769bp}{!}{\mbox{data type. It shall be the name of a row in the basic data representation table that specifies discrete values.}}}
}
\HLAStableID{m4.p072.b05}
