\HLAClausePlacedBlock{90.000}{69.646}{129.351}{%
  \HLAMinorClauseHeading{4.14.6 Array data type table}
}
\HLAStableID{m4.p074.b02}
\HLAClausePlacedBlock{90.000}{93.785}{432.058}{%
  \HLAClauseParagraph{\resizebox{431.958bp}{!}{\mbox{The array data type table shall describe indexed homogenous collections of data types; these constructs are}}\newline{}\resizebox{432.003bp}{!}{\mbox{also known as arrays or sequences. Table 35 illustrates the format that shall be used for the array data type}}\newline{}\resizebox{431.935bp}{!}{\mbox{table. The table includes four predefined array data types (\textit{HLAASCIIstring, HLAunicodeString,}}}\newline{}\resizebox{431.941bp}{!}{\mbox{\textit{HLAopaqueData, HLAtoken}) that shall be present in all FOMs, SOMs, and MIMs; additional entries may be}}\newline{}\resizebox{432.058bp}{!}{\mbox{added after them. Although these required data types shall be present, no requirement exists that federates or}}\newline{}\resizebox{90.226bp}{!}{\mbox{federations use them.}}}
}
\HLAStableID{m4.p074.b03}
\HLAClausePlacedBlock{90.000}{336.784}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.950bp}{!}{\mbox{The first column (Name) shall identify the name of the array data type. Array data type names shall adhere}}\newline{}\resizebox{160.983bp}{!}{\mbox{to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p074.b04}
\HLAClausePlacedBlock{90.000}{370.804}{432.024}{%
  \HLAClauseParagraph{\resizebox{431.987bp}{!}{\mbox{The second column (Element Type) shall identify the data type of an element of this data type. Values in this}}\newline{}\resizebox{432.024bp}{!}{\mbox{column shall be names from other data type tables (simple data type table, enumerated data type table,}}\newline{}\resizebox{432.013bp}{!}{\mbox{reference data type table, fixed record data type table, array data type table, or variant record data type}}\newline{}\resizebox{432.020bp}{!}{\mbox{table). Note that higher dimensional arrays may be specified by using array data types in the element type}}\newline{}\resizebox{82.176bp}{!}{\mbox{column of this table.}}}
}
\HLAStableID{m4.p074.b05}
\HLAClausePlacedBlock{90.000}{435.783}{432.028}{%
  \HLAClauseParagraph{\resizebox{431.964bp}{!}{\mbox{The third column (Cardinality) shall contain the number of elements that are contained in the array data}}\newline{}\resizebox{432.028bp}{!}{\mbox{type. Multidimensional arrays can be specified via a comma-separated list of values, each representing one}}\newline{}\resizebox{432.000bp}{!}{\mbox{dimension. If the number of elements in the array varies during the use of the data type, a range of values}}\newline{}\resizebox{432.013bp}{!}{\mbox{may be provided; if used, this range shall take the form of upper and lower bound values, separated by two}}\newline{}\resizebox{431.998bp}{!}{\mbox{periods and surrounded by brackets. Alternatively, the keyword “Dynamic” may be entered into this column}}\newline{}\resizebox{98.458bp}{!}{\mbox{for these types of arrays.}}}
}
\HLAStableID{m4.p074.b06}
\HLAClausePlacedBlock{89.999}{511.801}{432.042}{%
  \HLAClauseParagraph{\resizebox{432.002bp}{!}{\mbox{The fourth column (Encoding) shall describe, in detail, the encoding of the array data type (e.g., the}}\newline{}\resizebox{432.041bp}{!}{\mbox{sequence of elements and the order of elements in multi-dimensional arrays) as delivered to and received}}\newline{}\resizebox{432.034bp}{!}{\mbox{from the RTI. Encoding of elements in an array is determined by the data type specified in the Element type}}\newline{}\resizebox{432.007bp}{!}{\mbox{column. Encoding of the array is determined by the encoding specified in the Encoding column. Array data}}\newline{}\resizebox{432.018bp}{!}{\mbox{should be interpreted first through the array encoding scheme, and then through the encoding scheme of the}}\newline{}\resizebox{82.681bp}{!}{\mbox{element’s data type.}}}
}
\HLAStableID{m4.p074.b07}
\HLAClausePlacedBlock{90.000}{587.820}{432.032}{%
  \HLAClauseParagraph{\resizebox{431.960bp}{!}{\mbox{For one-dimensional array data types that use one of the two predefined array encodings, the appropriate}}\newline{}\resizebox{431.908bp}{!}{\mbox{keyword “HLAfixedArray” or “HLAvariableArray” shall be entered in the Encoding column. The}}\newline{}\resizebox{432.032bp}{!}{\mbox{“HLAfixedArray” encoding is intended for arrays with fixed cardinality and consists of the encoding of each}}\newline{}\resizebox{431.943bp}{!}{\mbox{element in sequence. The “HLAvariableArray” encoding is intended for arrays with variable (including}}\newline{}\resizebox{431.971bp}{!}{\mbox{dynamic) cardinality, and consists of the number of elements encoded as an\space{}\textit{HLAinteger32BE}, followed by}}\newline{}\resizebox{423.152bp}{!}{\mbox{the encoding of each element in sequence. Full details of these predefined encodings are given in 4.14.10.}}}
}
\HLAStableID{m4.p074.b08}
\HLAClausePlacedBlock{90.000}{663.779}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.974bp}{!}{\mbox{The fifth column (Semantics) shall describe the meaning and use of this data type. “NA” shall be entered in}}\newline{}\resizebox{225.699bp}{!}{\mbox{this column when semantics information is unnecessary.}}}
}
\HLAStableID{m4.p074.b09}
\HLAClausePlacedBlock{90.000}{695.818}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.916bp}{!}{\mbox{An example of the use of the array data type table is provided in Table 36.\space{}\textit{Employees}\space{}is a fixed-length array}}\newline{}\resizebox{431.985bp}{!}{\mbox{type that holds the employee identifiers of everyone currently working; It uses the standard\space{}\textit{HLAfixedArray}}}}
}
