\HLAClausePlacedBlock{90.000}{69.786}{432.026}{%
  \HLAClauseParagraph{\resizebox{432.020bp}{!}{\mbox{encoding.\space{}\textit{AddressBook}\space{}is an array type that can be used to hold a collection of addresses; because it is}}\newline{}\resizebox{431.919bp}{!}{\mbox{encoded as a sparse array, addresses can be updated selectively without sending every element of the array.}}\newline{}\resizebox{432.025bp}{!}{\mbox{Because one may want to update addresses selectively without sending every element of the array, a special}}\newline{}\resizebox{150.647bp}{!}{\mbox{encoding is defined for this data type.}}}
}
\HLAStableID{m4.p075.b02}
\HLAClausePlacedBlock{90.001}{444.646}{163.229}{%
