}
\HLAStableID{m4.p075.b03}
\HLAClausePlacedBlock{90.001}{468.785}{432.080}{%
  \HLAClauseParagraph{\resizebox{431.947bp}{!}{\mbox{The fixed record data type table shall be used to describe heterogeneous collections of types; these}}\newline{}\resizebox{432.017bp}{!}{\mbox{constructs are also known as records or structures. Each entry in the fixed record data type table may contain}}\newline{}\resizebox{431.928bp}{!}{\mbox{fields that are of other types, such as simple data types, fixed records, arrays, enumerations, or variant}}\newline{}\resizebox{432.080bp}{!}{\mbox{records. This allows users to build “structures of data structures” according to the needs of their federate or}}\newline{}\resizebox{383.472bp}{!}{\mbox{federation. Table 37 illustrates the format that shall be used for the fixed record data type table.}}}
}
\HLAStableID{m4.p075.b04}
\HLAClausePlacedBlock{90.002}{686.825}{431.998}{%
  \HLAClauseParagraph{\resizebox{431.919bp}{!}{\mbox{The first column (Record name) shall identify the name of the fixed record data type. Record names shall}}\newline{}\resizebox{190.098bp}{!}{\mbox{adhere to HLA naming conventions (see 3.3.1).}}}
}
