\HLAClausePlacedBlock{90.000}{69.786}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.872bp}{!}{\mbox{The second column (Field name) shall identify the name of a field in the fixed record data type. Field names}}\newline{}\resizebox{211.558bp}{!}{\mbox{shall adhere to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p076.b02}
\HLAClausePlacedBlock{90.000}{105.785}{432.072}{%
  \HLAClauseParagraph{\resizebox{432.072bp}{!}{\mbox{The third column (Field type) shall identify the data type of the field. Values in this column shall be names}}\newline{}\resizebox{432.008bp}{!}{\mbox{from other data type tables (simple data type table, enumerated data type table, reference data type table,}}\newline{}\resizebox{333.864bp}{!}{\mbox{fixed record data type table, array data type table, or variant record data type table).}}}
}
\HLAStableID{m4.p076.b03}
\HLAClausePlacedBlock{90.000}{153.784}{432.019}{%
  \HLAClauseParagraph{\resizebox{432.019bp}{!}{\mbox{The fourth column (Field semantics) shall describe the meaning and use of this field. “NA” shall be entered}}\newline{}\resizebox{236.040bp}{!}{\mbox{in this column when semantics information is unnecessary.}}}
}
\HLAStableID{m4.p076.b04}
\HLAClausePlacedBlock{90.000}{189.784}{432.071}{%
  \HLAClauseParagraph{\resizebox{432.014bp}{!}{\mbox{The fifth column (Encoding) shall describe, in detail, the encoding of the fixed record data type (i.e., the}}\newline{}\resizebox{432.017bp}{!}{\mbox{organization of fields) as delivered to and received from the RTI. Encoding of fields in a fixed record is}}\newline{}\resizebox{432.071bp}{!}{\mbox{determined by the data type specified in the Field Type column. Encoding of the fixed record is determined}}\newline{}\resizebox{432.012bp}{!}{\mbox{by the encoding specified in the Encoding column. Record data should be interpreted first through the record}}\newline{}\resizebox{325.521bp}{!}{\mbox{encoding scheme, and then through the encoding scheme of the field’s data type.}}}
}
\HLAStableID{m4.p076.b05}
\HLAClausePlacedBlock{90.000}{261.783}{432.029}{%
  \HLAClauseParagraph{\resizebox{431.907bp}{!}{\mbox{For fixed record data types that use the predefined fixed record encoding, the keyword “HLAfixedRecord”}}\newline{}\resizebox{432.029bp}{!}{\mbox{shall be entered in the Encoding column (see 4.14.10). The “HLAfixedRecord” encoding consists of the}}\newline{}\resizebox{432.012bp}{!}{\mbox{encoding of each field in sequence, in the order in which they are declared. Full details of this predefined}}\newline{}\resizebox{121.215bp}{!}{\mbox{encoding are given in 4.14.10.}}}
}
\HLAStableID{m4.p076.b06}
\HLAClausePlacedBlock{90.000}{321.782}{432.063}{%
  \HLAClauseParagraph{\resizebox{432.063bp}{!}{\mbox{The sixth column (Semantics) shall describe the meaning and use of this data type. “NA” shall be entered in}}\newline{}\resizebox{225.699bp}{!}{\mbox{this column when semantics information is unnecessary.}}}
}
\HLAStableID{m4.p076.b07}
\HLAClausePlacedBlock{90.000}{357.781}{432.041}{%
  \HLAClauseParagraph{\resizebox{432.013bp}{!}{\mbox{An example of the use of the fixed record data type table is provided in Table 38. These data types are}}\newline{}\resizebox{431.983bp}{!}{\mbox{used in examples elsewhere in this document.\space{}\textit{ServiceStat}\space{}combines three\space{}\textit{HLAboolean}\space{}values into one}}\newline{}\resizebox{432.041bp}{!}{\mbox{record.\space{}\textit{AddressType}\space{}creates a record of components of a mailing address. Both data types use the standard}}\newline{}\resizebox{111.252bp}{!}{\mbox{\textit{HLAfixedRecord}\space{}encoding.}}}
}
\HLAStableID{m4.p076.b08}
\HLAClausePlacedBlock{90.000}{631.661}{171.060}{%
  \HLAMinorClauseHeading{4.14.8 Variant record data type table}
}
\HLAStableID{m4.p076.b09}
\HLAClausePlacedBlock{90.000}{655.800}{432.032}{%
  \HLAClauseParagraph{\resizebox{432.008bp}{!}{\mbox{The variant record data type table shall describe discriminated unions of types; these constructs are also}}\newline{}\resizebox{431.972bp}{!}{\mbox{known as variant or choice records. There are two types of standardized encodings for this data type, one}}\newline{}\resizebox{432.032bp}{!}{\mbox{extendable encoding and one non-extendable encoding. The extendable encoding allows for the addition of}}\newline{}\resizebox{431.983bp}{!}{\mbox{new alternatives where different FOM/SOM modules may provide different alternatives. The non-}}\newline{}\resizebox{432.025bp}{!}{\mbox{extendable encoding does not allow this, and all FOM/SOM modules shall provide the same}}}
}
\HLAStableID{m4.p076.b10}
\HLAClausePlacedBlock{193.259}{451.660}{225.512}{%
  \HLATableCaption{Table 38—Fixed record data type table example}
}
