\HLAClausePlacedBlock{90.000}{69.786}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.937bp}{!}{\mbox{alternatives. The two encodings are further described in 4.14.10. Table 39 illustrates the format that shall be}}\newline{}\resizebox{168.726bp}{!}{\mbox{used for the variant record data type table.}}}
}
\HLAStableID{m4.p077.b02}
\HLAClausePlacedBlock{90.000}{327.785}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.972bp}{!}{\mbox{The first column (Record name) shall identify the name of the variant record data type. Record names shall}}\newline{}\resizebox{190.098bp}{!}{\mbox{adhere to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p077.b03}
\HLAClausePlacedBlock{90.000}{363.785}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.959bp}{!}{\mbox{The second column (Discriminant name) shall identify the name of the discriminant. Discriminant names}}\newline{}\resizebox{211.558bp}{!}{\mbox{shall adhere to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p077.b04}
\HLAClausePlacedBlock{90.000}{399.784}{432.004}{%
  \HLAClauseParagraph{\resizebox{432.004bp}{!}{\mbox{The third column (Discriminant type) shall identify the data type of the discriminant. Values in this column}}\newline{}\resizebox{207.925bp}{!}{\mbox{shall be names from the enumerated data type table.}}}
}
\HLAStableID{m4.p077.b05}
\HLAClausePlacedBlock{89.999}{435.784}{432.080}{%
  \HLAClauseParagraph{\resizebox{431.992bp}{!}{\mbox{The fourth column (Discriminant enumerator) shall be a set of enumerators that determines the alternative.}}\newline{}\resizebox{431.995bp}{!}{\mbox{The enumerators shall be from the enumerated data type specified in the Discriminant type column. The set}}\newline{}\resizebox{431.955bp}{!}{\mbox{shall consist of one or more individual enumerators or enumerator ranges separated by commas. An}}\newline{}\resizebox{432.005bp}{!}{\mbox{enumerator range shall be specified by two enumerators, separated by two periods, and enclosed in square}}\newline{}\resizebox{432.001bp}{!}{\mbox{brackets. The enumerator range shall denote all enumerators in the enumerated data type whose definition in}}\newline{}\resizebox{432.044bp}{!}{\mbox{the enumerated data type table occurs in between the specified enumerators (including the specified}}\newline{}\resizebox{432.034bp}{!}{\mbox{enumerators themselves). When the non-extendable encoding HLAvariantRecord is used, the special}}\newline{}\resizebox{432.049bp}{!}{\mbox{symbol “HLAother” may be used, in addition to enumerators. It shall denote all enumerators in the}}\newline{}\resizebox{432.077bp}{!}{\mbox{enumerated data type that are not explicitly included in any of the other Enumerator entries for the}}\newline{}\resizebox{407.231bp}{!}{\mbox{associated record name. The symbol “HLAother” shall only occur at most once for each record name.}}}
}
\HLAStableID{m4.p077.b06}
\HLAClausePlacedBlock{90.002}{567.782}{432.036}{%
  \HLAClauseParagraph{\resizebox{432.036bp}{!}{\mbox{The fifth column (Alternative name) shall define the identifier or name for the alternative. Alternative names}}\newline{}\resizebox{228.626bp}{!}{\mbox{shall adhere to the HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p077.b07}
\HLAClausePlacedBlock{90.002}{603.781}{432.007}{%
  \HLAClauseParagraph{\resizebox{431.979bp}{!}{\mbox{The sixth column (Alternative type) shall identify the data type of the field. Values in this column shall be}}\newline{}\resizebox{432.007bp}{!}{\mbox{names from other data type tables (simple data type table, enumerated data type table, reference data type}}\newline{}\resizebox{360.762bp}{!}{\mbox{table, fixed record data type table, array data type table, or variant record data type table).}}}
}
\HLAStableID{m4.p077.b08}
\HLAClausePlacedBlock{90.002}{651.780}{432.041}{%
  \HLAClauseParagraph{\resizebox{432.041bp}{!}{\mbox{The seventh column (Alternative semantics) describe the meaning and use of this alternative. “NA” shall be}}\newline{}\resizebox{267.907bp}{!}{\mbox{entered in this column when semantics information is unnecessary.}}}
}
\HLAStableID{m4.p077.b09}
\HLAClausePlacedBlock{90.002}{687.780}{432.029}{%
  \HLAClauseParagraph{\resizebox{431.954bp}{!}{\mbox{The eighth column (Encoding) shall describe, in detail, the encoding of the variant record data type (e.g., the}}\newline{}\resizebox{432.029bp}{!}{\mbox{location of the discriminant) as delivered to and received from the RTI. Encoding of fields in a variant}}}
}
