\HLAClausePlacedBlock{90.000}{69.786}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.997bp}{!}{\mbox{record is determined by the data type specified in the Alternative type column. Encoding of the variant}}\newline{}\resizebox{431.967bp}{!}{\mbox{record is determined by the encoding specified in the Encoding column. Record data should be interpreted}}\newline{}\resizebox{418.041bp}{!}{\mbox{first through the record encoding scheme and then through the encoding scheme of the field’s data type.}}}
}
\HLAStableID{m4.p078.b02}
\HLAClausePlacedBlock{89.999}{117.785}{432.086}{%
  \HLAClauseParagraph{\resizebox{432.085bp}{!}{\mbox{For variant record data types that use the predefined, extendable variant record encoding, the keyword}}\newline{}\resizebox{431.919bp}{!}{\mbox{“HLAextendableVariantRecord” shall be entered in the Encoding column (see 4.14.10). For backwards}}\newline{}\resizebox{431.959bp}{!}{\mbox{compatibility, the non-extendable “HLAvariantRecord” encoding may also be used. Details of these}}\newline{}\resizebox{170.474bp}{!}{\mbox{predefined encodings are given in 4.14.10.}}}
}
\HLAStableID{m4.p078.b03}
\HLAClausePlacedBlock{89.999}{177.784}{432.001}{%
  \HLAClauseParagraph{\resizebox{431.910bp}{!}{\mbox{The ninth column (Semantics) shall describe the meaning and use of this variant record data type. “NA”}}\newline{}\resizebox{301.208bp}{!}{\mbox{shall be entered in this column when semantics information is unnecessary.}}}
}
\HLAStableID{m4.p078.b04}
\HLAClausePlacedBlock{90.000}{210.981}{432.216}{%
  \HLAClauseParagraph{\resizebox{432.216bp}{!}{\mbox{Two examples of the variant record table are provided in Table 40. In the first example, the assessed value of a server is}}\newline{}\resizebox{432.113bp}{!}{\mbox{specified using the ServerValue variant record data type. The discriminant is based on the level of experience of the}}\newline{}\resizebox{432.098bp}{!}{\mbox{employee. For trainees, the alternative CoursePassed is represented as an HLAboolean indicating whether the employee}}\newline{}\resizebox{431.994bp}{!}{\mbox{passed training. For temporary staff, the alternative provides the name of the temp agency, that can be contacted to}}\newline{}\resizebox{432.094bp}{!}{\mbox{obtain additional information. For all other types of employees, indicated using the HLAother keyword, the alternative}}\newline{}\resizebox{184.976bp}{!}{\mbox{Rating supports a more expanded scale (e.g., 1-10).}}}
}
\HLAStableID{m4.p078.b05}
\HLAClausePlacedBlock{90.000}{559.806}{432.060}{%
  \HLAClauseParagraph{\resizebox{431.983bp}{!}{\mbox{The discriminant Experience itself is represented using the enumerated data type ExperienceLevel, defined}}\newline{}\resizebox{432.060bp}{!}{\mbox{in Table 34. The ServerValue variant record data type uses the HLAvariantRecord encoding. Variant records}}\newline{}\resizebox{432.035bp}{!}{\mbox{using this encoding cannot be safely extended using additional FOM modules, since existing federates may}}\newline{}\resizebox{231.681bp}{!}{\mbox{not be able to correctly decode newly introduced variants.}}}
}
\HLAStableID{m4.p078.b06}
\HLAClausePlacedBlock{89.999}{619.805}{432.037}{%
  \HLAClauseParagraph{\resizebox{431.991bp}{!}{\mbox{The second example specifies data for the garnish used for different types of drinks. The discriminant is}}\newline{}\resizebox{431.937bp}{!}{\mbox{based on the type of drink using the DrinkType enumerated data type specified in Table 34. For a Margarita,}}\newline{}\resizebox{432.010bp}{!}{\mbox{the presence of a salt rim is specified using an HLAboolean. For a Dry Martini, the number of olives is}}\newline{}\resizebox{431.991bp}{!}{\mbox{specified using a FruitCount integer. The DrinkGarnish variant record data type uses the}}\newline{}\resizebox{431.955bp}{!}{\mbox{HLAextendableVariantRecord encoding, and can safely be extended using additional FOM modules,}}\newline{}\resizebox{431.914bp}{!}{\mbox{without impacting existing federates. HLAother is not a permissible alternative for this encoding, since the}}\newline{}\resizebox{432.037bp}{!}{\mbox{interpretation of the variant record data type would change in case new enumerators were added using}}\newline{}\resizebox{102.991bp}{!}{\mbox{additional FOM modules.}}}
}
