\HLAStableID{m4.p079.b02}
\HLAClausePlacedBlock{90.000}{91.805}{432.065}{%
  \HLAClauseParagraph{\resizebox{432.065bp}{!}{\mbox{The reference data type table shall be used to describe simple references to an object instance. Table 41}}\newline{}\resizebox{288.652bp}{!}{\mbox{illustrates the format that shall be used for the reference data type table.}}}
}
\HLAStableID{m4.p079.b03}
\HLAClausePlacedBlock{90.001}{127.805}{432.128}{%
  \HLAClauseParagraph{\resizebox{432.128bp}{!}{\mbox{The first column (Name) shall identify the name of the reference data type. Reference data type names shall}}\newline{}\resizebox{190.098bp}{!}{\mbox{adhere to HLA naming conventions (see 3.3.1).}}}
}
\HLAStableID{m4.p079.b04}
\HLAClausePlacedBlock{90.001}{163.804}{432.001}{%
  \HLAClauseParagraph{\resizebox{432.001bp}{!}{\mbox{The second column (Representation) shall identify the data representation of this data type. The}}\newline{}\resizebox{328.367bp}{!}{\mbox{representation shall be the same as the referenced attribute of the referenced class.}}}
}
\HLAStableID{m4.p079.b05}
\HLAClausePlacedBlock{90.001}{199.804}{431.999}{%
  \HLAClauseParagraph{\resizebox{399.353bp}{!}{\mbox{The third column (Referenced class) shall identify the object class of the referenced object instance.}}}
}
\HLAStableID{m4.p079.b06}
\HLAClausePlacedBlock{90.001}{223.803}{432.097}{%
  \HLAClauseParagraph{\resizebox{432.097bp}{!}{\mbox{The fourth column (Referenced attribute) shall identify the attribute of the referenced class that shall be used}}\newline{}\resizebox{432.078bp}{!}{\mbox{for identifying the referenced instance. The attribute name HLAobjectInstanceName shall be used to}}\newline{}\resizebox{432.026bp}{!}{\mbox{identify object instances by their name and the attribute name HLAobjectInstanceHandle shall be used to}}\newline{}\resizebox{162.083bp}{!}{\mbox{identify object instances by their handle.}}}
}
\HLAStableID{m4.p079.b07}
\HLAClausePlacedBlock{90.002}{283.802}{431.998}{%
  \HLAClauseParagraph{\resizebox{431.974bp}{!}{\mbox{The fifth column (Semantics) shall describe the meaning and use of this data type. “NA” shall be entered in}}\newline{}\resizebox{228.211bp}{!}{\mbox{this column when semantics information is unnecessary.}}}
}
\HLAStableID{m4.p079.b08}
\HLAClausePlacedBlock{90.002}{413.762}{432.032}{%
  \HLAClauseParagraph{\resizebox{432.032bp}{!}{\mbox{An example of the Reference data type table is provided in Table 42. The PersonReference data type can be}}\newline{}\resizebox{316.731bp}{!}{\mbox{used whenever an attribute is used to reference an instance of the Person class.}}}
}
\HLAStableID{m4.p079.b09}
