  \HLAClauseParagraph{\resizebox{432.026bp}{!}{\mbox{64-bit boundary. Determining the number of padding bytes needed after a component in a constructed type}}\newline{}\resizebox{171.276bp}{!}{\mbox{depends on up to three factors, as follows:}}}
