}
\HLAStableID{m4.p080.b05}
\HLAClausePlacedBlock{89.999}{150.784}{432.042}{%
  \HLAClauseParagraph{\resizebox{431.969bp}{!}{\mbox{The octet boundary value for simple data types and enumerated data types is derived from the type’s entry in}}\newline{}\resizebox{431.958bp}{!}{\mbox{the basic data representation table. The octet boundary value is defined as the smallest value 2\HLATextSup{\textit{n}}, where\space{}\textit{n}\space{}is a}}\newline{}\resizebox{432.041bp}{!}{\mbox{non-negative integer, for which (8\space{}×\space{}2\HLATextSup{\textit{n}}) is greater than or equal to the size of the data type in bits. Octet}}\newline{}\resizebox{335.630bp}{!}{\mbox{boundary values of the predefined basic data representations are shown in Table 43.}}}
}
\HLAStableID{m4.p080.b06}
\HLAClausePlacedBlock{89.998}{425.766}{432.037}{%
  \HLAClauseParagraph{\resizebox{431.989bp}{!}{\mbox{The octet boundary value for a constructed data type is the maximum octet boundary value of all}}\newline{}\resizebox{432.004bp}{!}{\mbox{components within that constructed data type. For example, a fixed record containing an\space{}\textit{HLAboolean}\space{}field}}\newline{}\resizebox{432.036bp}{!}{\mbox{(based on\space{}\textit{HLAinteger32BE),}\space{}a field based on\space{}\textit{HLAoctet}\space{}and a field based on\space{}\textit{HLAfloat64BE}, has an octet}}\newline{}\resizebox{432.035bp}{!}{\mbox{boundary value of 8. Any constructed data type that contains this fixed record has an octet boundary value of}}\newline{}\resizebox{377.338bp}{!}{\mbox{at least 8, and it may be larger depending on the octet boundary value of its other components.}}}
}
\HLAStableID{m4.p080.b07}
\HLAClausePlacedBlock{89.998}{497.825}{432.068}{%
  \HLAClauseParagraph{\resizebox{432.027bp}{!}{\mbox{The following subclauses describe each of the four predefined constructed data type encodings, including}}\newline{}\resizebox{432.047bp}{!}{\mbox{the number of padding bytes to be added after the components of each constructed data type. If these}}\newline{}\resizebox{432.067bp}{!}{\mbox{predefined encodings are used with any data type whose size in bits is not an integer multiple of 8, padding}}\newline{}\resizebox{431.984bp}{!}{\mbox{\textit{bits}\space{}shall be added to the data type to increase its size in bits to the next integer multiple of 8. Padding bits}}\newline{}\resizebox{188.082bp}{!}{\mbox{and bytes are always represented by 0s (zeros).}}}
}
\HLAStableID{m4.p080.b08}
\HLAClausePlacedBlock{89.999}{569.685}{432.001}{%
  \HLAClauseParagraph{\resizebox{122.727bp}{!}{\mbox{\textbf{4.14.10.1 HLAfixedRecord}}}}
