\HLAClausePlacedBlock{89.999}{593.824}{432.001}{%
  \HLAClauseParagraph{\resizebox{431.989bp}{!}{\mbox{The HLAfixedRecord encoding shall consist of the encoding of each component in sequence, in the order in}}\newline{}\resizebox{391.634bp}{!}{\mbox{which they are declared. The first component in a fixed record shall start at offset 0 of the record.}}}
}
\HLAStableID{m4.p080.b10}
\HLAClausePlacedBlock{89.997}{629.823}{432.088}{%
  \HLAClauseParagraph{\resizebox{432.087bp}{!}{\mbox{Zero or more padding bytes shall be added to each component, except the last, to ensure that the next}}\newline{}\resizebox{431.981bp}{!}{\mbox{component in the record is properly aligned. The number of padding bytes after such a component\space{}\textit{i}\space{}of a}}\newline{}\resizebox{388.341bp}{!}{\mbox{fixed record with this encoding is the smallest nonnegative value of P\HLATextSub{\textit{i}}\space{}that satisfies Equation (1):}}}
}
