  \HLAClauseParagraph{\resizebox{431.975bp}{!}{\mbox{For example, consider a variant record with a discriminant based on the\space{}\textit{HLAoctet}\space{}representation, one}}\newline{}\resizebox{431.947bp}{!}{\mbox{alternative consisting of a field based on the\space{}\textit{HLAinteger32BE}\space{}representation, and a second alternative}}\newline{}\resizebox{431.991bp}{!}{\mbox{consisting of a fixed record containing two fields, both based on the\space{}\textit{HLAoctet}\space{}representation. The encoding}}\newline{}\resizebox{99.095bp}{!}{\mbox{calculation is as follows:}}}
