\HLAStableID{m4.p082.b10}
\HLAClausePlacedBlock{90.002}{537.782}{432.060}{%
  \HLAClauseParagraph{\resizebox{432.027bp}{!}{\mbox{The HLAextendableVariantRecord encoding shall consist of the discriminant followed by an}}\newline{}\resizebox{432.060bp}{!}{\mbox{encoded\_length element containing the length of the encoded alternative in bytes encoded as an}}\newline{}\resizebox{432.019bp}{!}{\mbox{HLAinteger32BE, followed by the alternative associated with the value of the discriminant. The}}\newline{}\resizebox{432.030bp}{!}{\mbox{discriminant shall be placed at offset 0 of the record. The octet boundary of the alternatives in an}}\newline{}\resizebox{432.048bp}{!}{\mbox{HLAextendableVariantRecord is predefined as the value 8. This value shall be used in the calculation of the}}\newline{}\resizebox{431.968bp}{!}{\mbox{octet boundary of the HLAextendableVariantRecord. HLAextendableVariantRecord cannot be used with}}\newline{}\resizebox{202.844bp}{!}{\mbox{alternatives with an octet boundary greater than 8.}}}
}
\HLAStableID{m4.p082.b11}
\HLAClausePlacedBlock{90.002}{633.781}{432.021}{%
  \HLAClauseParagraph{\resizebox{431.951bp}{!}{\mbox{Padding bytes shall be added (if required) after the discriminant to ensure that the encoded\_length element is}}\newline{}\resizebox{432.021bp}{!}{\mbox{properly aligned. The number of padding bytes after such a discriminant of a variant record with this}}\newline{}\resizebox{297.812bp}{!}{\mbox{encoding is the smallest nonnegative value of P that satisfies Equation (3):}}}
}
