\HLAStableID{m4.p083.b03}
\HLAClausePlacedBlock{89.999}{111.785}{432.020}{%
  \HLAClauseParagraph{\resizebox{432.019bp}{!}{\mbox{Following the discriminant and associated padding (if required), shall be the encoded\_length element. The}}\newline{}\resizebox{431.991bp}{!}{\mbox{encoded\_length element shall be encoded as an HLAinteger32BE and contain the encoded size (in bytes) of}}\newline{}\resizebox{432.010bp}{!}{\mbox{the alternative that applies to the value contained in the discriminant. If no alternative applies to the value}}\newline{}\resizebox{431.984bp}{!}{\mbox{contained in the discriminant, the encoded\_length element shall have value 0. The encoded size shall not}}\newline{}\resizebox{245.446bp}{!}{\mbox{include any padding added after the encoded\_length element.}}}
}
\HLAStableID{m4.p083.b04}
\HLAClausePlacedBlock{90.000}{183.784}{432.049}{%
  \HLAClauseParagraph{\resizebox{431.989bp}{!}{\mbox{Padding bytes shall be added (if required) after the encoded\_length element to ensure that the alternative is}}\newline{}\resizebox{432.049bp}{!}{\mbox{properly aligned. The number of padding bytes after the encoded\_length element of a variant record with}}\newline{}\resizebox{314.810bp}{!}{\mbox{this encoding is the smallest nonnegative value of P that satisfies Equation (4):}}}
}
\HLAStableID{m4.p083.b05}
\HLAClausePlacedBlock{100.020}{231.783}{421.997}{%
  \HLAClauseParagraph{\makebox[421.997bp][l]{(\textit{Size}\space{}+\space{}\textit{P}) mod\space{}\textit{V}\space{}= 0\hfill{}(4)}}
}
\HLAStableID{m4.p083.b06}
\HLAClausePlacedBlock{90.001}{253.803}{431.999}{%
