}
\HLAStableID{m4.p083.b07}
\HLAClausePlacedBlock{100.021}{271.802}{421.979}{%
  \HLAClauseParagraph{\makebox[421.953bp][l]{\textit{Size}\hfill{}is the the size of the discriminant plus associated padding (if required) plus the size of the}\newline{}\hspace*{43.980bp}\resizebox{140.410bp}{!}{\mbox{\textit{encoded\_length}\space{}element (in bytes).}}}
}
\HLAStableID{m4.p083.b08}
\HLAClausePlacedBlock{99.122}{301.802}{422.878}{%
  \HLAClauseParagraph{\makebox[290.770bp][l]{\textit{V}\hfill{}is the the octet boundary value of the alternatives, which equals 8.}}
}
\HLAStableID{m4.p083.b09}
\HLAClausePlacedBlock{90.001}{325.802}{432.011}{%
  \HLAClauseParagraph{\resizebox{432.011bp}{!}{\mbox{Padding bytes shall not be added after the alternative. The size of the variant record shall include any added}}\newline{}\resizebox{58.300bp}{!}{\mbox{padding bytes.}}}
}
\HLAStableID{m4.p083.b10}
\HLAClausePlacedBlock{90.002}{361.801}{432.023}{%
  \HLAClauseParagraph{\resizebox{431.972bp}{!}{\mbox{For example, consider a variant record with a discriminant based on the HLAoctet representation, one}}\newline{}\resizebox{432.023bp}{!}{\mbox{alternative consisting of a field based on the HLAfloat32LE representation, and a second alternative}}\newline{}\resizebox{431.967bp}{!}{\mbox{consisting of a fixed record containing two fields, both based on the HLAoctet representation. The encoding}}\newline{}\resizebox{235.889bp}{!}{\mbox{calculation for padding after the discriminant is as follows:}}}
}
\HLAStableID{m4.p083.b11}
\HLAClausePlacedBlock{100.022}{421.800}{421.978}{%
  \HLAClauseParagraph{\resizebox{83.943bp}{!}{\mbox{(\textit{Size}\space{}+\space{}\textit{P}) mod\space{}\textit{V}\space{}= 0}}\newline{}\resizebox{71.762bp}{!}{\mbox{(1 +\space{}\textit{P}) mod 4 = 0}}\newline{}\resizebox{21.722bp}{!}{\mbox{\textit{P}\space{}= 3}}}
}
\HLAStableID{m4.p083.b12}
\HLAClausePlacedBlock{90.002}{469.799}{431.998}{%
  \HLAClauseParagraph{\resizebox{230.760bp}{!}{\mbox{Thus, 3 bytes of padding are added after the discriminant.}}}
}
\HLAStableID{m4.p083.b13}
\HLAClausePlacedBlock{90.002}{493.799}{431.998}{%
  \HLAClauseParagraph{\resizebox{431.968bp}{!}{\mbox{No padding bytes are required after\space{}\textit{encoded\_length}\space{}element since we are already at the required 8-byte}}\newline{}\resizebox{42.443bp}{!}{\mbox{alignment.}}}
}
