  \HLAClauseParagraph{\resizebox{432.022bp}{!}{\mbox{In case in which the discriminant contains a value that indicates that the fixed record alternative is used, a}}\newline{}\resizebox{231.458bp}{!}{\mbox{graphical representation of the variant record is a follows:}}}
