\HLAStableID{m4.p084.b02}
\HLAClausePlacedBlock{89.999}{187.806}{432.009}{%
  \HLAClauseParagraph{\resizebox{432.008bp}{!}{\mbox{The number of padding bytes after each element\space{}\textit{i}\space{}of an array, except the last element, with this encoding is}}\newline{}\resizebox{252.311bp}{!}{\mbox{the smallest nonnegative value of\space{}\textit{P}\HLATextSub{\textit{i}}\space{}that satisfies Equation (5):}}}
}
\HLAStableID{m4.p084.b03}
\HLAClausePlacedBlock{100.020}{223.805}{421.997}{%
  \HLAClauseParagraph{\makebox[421.997bp][l]{(\textit{Size}\HLATextSub{\textit{i}}\space{}+\space{}\textit{P}\HLATextSub{\textit{i}}) mod\space{}\textit{V}\space{}= 0\hfill{}(5)}}
}
\HLAStableID{m4.p084.b04}
\HLAClausePlacedBlock{90.001}{247.626}{431.999}{%
  \HLAClauseParagraph{\resizebox{24.400bp}{!}{\mbox{where}}\newline{}\hspace*{10.020bp}\makebox[229.505bp][l]{\textit{Size}\HLATextSub{\textit{i}}\hfill{}is the size of the\space{}\textit{i}th element of the array (in bytes)}\newline{}\hspace*{10.019bp}\makebox[214.956bp][l]{\textit{V}\hfill{}is the octet boundary value of the element type}}
}
\HLAStableID{m4.p084.b05}
\HLAClausePlacedBlock{89.999}{297.486}{432.001}{%
  \HLAClauseParagraph{\resizebox{431.974bp}{!}{\mbox{Padding bytes shall not be added after the last element of the array. The size of the fixed array shall include}}\newline{}\resizebox{101.550bp}{!}{\mbox{any added padding bytes.}}}
}
\HLAStableID{m4.p084.b06}
\HLAClausePlacedBlock{90.000}{333.485}{432.006}{%
  \HLAClauseParagraph{\resizebox{432.006bp}{!}{\mbox{For example, consider an array consisting of a fixed number of elements, each of which is a fixed record}}\newline{}\resizebox{431.967bp}{!}{\mbox{encoded using\space{}\textit{HLAfixedRecord}\space{}and consisting of a field based on the\space{}\textit{HLAinteger32BE}\space{}representation,}}\newline{}\resizebox{230.732bp}{!}{\mbox{followed by a field based on the\space{}\textit{HLAoctet}\space{}representation.}}}
}
\HLAStableID{m4.p084.b07}
\HLAClausePlacedBlock{90.000}{381.484}{432.056}{%
  \HLAClauseParagraph{\resizebox{432.056bp}{!}{\mbox{The size of each element in this array is the same, 5 bytes, as calculated following the rules for the}}\newline{}\resizebox{431.916bp}{!}{\mbox{\textit{HLAfixedRecord}\space{}encoding. The octet boundary value of each element in this array is 4 bytes, the maximum}}\newline{}\resizebox{431.974bp}{!}{\mbox{of the octet boundary values of the two fields of the record. The calculations for the padding after each}}\newline{}\resizebox{157.024bp}{!}{\mbox{element, except the last, are as follows:}}}
}
\HLAStableID{m4.p084.b08}
\HLAClausePlacedBlock{100.020}{441.483}{421.980}{%
  \HLAClauseParagraph{\resizebox{88.383bp}{!}{\mbox{(\textit{Size}\HLATextSub{\textit{i}}\space{}+\space{}\textit{P}\HLATextSub{\textit{i}}) mod\space{}\textit{V}\space{}= 0}}\newline{}\resizebox{73.981bp}{!}{\mbox{(5 +\space{}\textit{P}\HLATextSub{\textit{i}}) mod 4 = 0}}\newline{}\resizebox{23.942bp}{!}{\mbox{\textit{P}\HLATextSub{\textit{i}}\space{}= 3}}}
}
\HLAStableID{m4.p084.b09}
\HLAClausePlacedBlock{90.000}{495.006}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.985bp}{!}{\mbox{Thus, 3 bytes of padding are added after each element of the array, except for the last element. A graphical}}\newline{}\resizebox{315.063bp}{!}{\mbox{representation of such an array, containing exactly two elements, is as follows:}}}
}
\HLAStableID{m4.p084.b10}
