\HLAClausePlacedBlock{90.000}{69.786}{432.028}{%
  \HLAClauseParagraph{\resizebox{431.993bp}{!}{\mbox{Padding bytes, if required, shall be added after the number\_of\_elements component to ensure that the first}}\newline{}\resizebox{432.028bp}{!}{\mbox{element in the array is properly aligned. The number of padding bytes here is the smallest nonnegative value}}\newline{}\resizebox{124.345bp}{!}{\mbox{of\space{}\textit{P}\space{}that satisfies Equation (6).}}}
}
\HLAStableID{m4.p085.b02}
\HLAClausePlacedBlock{100.020}{117.785}{421.996}{%
  \HLAClauseParagraph{\makebox[421.996bp][l]{(4 +\space{}\textit{P}) mod\space{}\textit{V}\space{}= 0\hfill{}(6)}}
}
\HLAStableID{m4.p085.b03}
\HLAClausePlacedBlock{90.000}{139.804}{432.067}{%
  \HLAClauseParagraph{\resizebox{24.400bp}{!}{\mbox{where}}\newline{}\hspace*{10.020bp}\resizebox{422.047bp}{!}{\mbox{\textit{V}\space{}is the maximum of the octet boundary value of the element type, and the octet boundary value of}}\newline{}\hspace*{53.999bp}\resizebox{73.550bp}{!}{\mbox{HLAinteger32BE.}}}
}
\HLAStableID{m4.p085.b04}
\HLAClausePlacedBlock{89.999}{187.804}{432.068}{%
  \HLAClauseParagraph{\resizebox{432.068bp}{!}{\mbox{The number of padding bytes after each element of a variable array is calculated in the same way as for}}\newline{}\resizebox{340.883bp}{!}{\mbox{\textit{HLAfixedArray}. The size of the variable array shall include any added padding bytes.}}}
}
\HLAStableID{m4.p085.b05}
\HLAClausePlacedBlock{90.000}{223.803}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.965bp}{!}{\mbox{For example, consider an array consisting of a variable number of elements based on the\space{}\textit{HLAfloat64BE}}}\newline{}\resizebox{376.112bp}{!}{\mbox{representation. The padding calculation for the number\_of\_elements component is as follows:}}}
}
\HLAStableID{m4.p085.b06}
\HLAClausePlacedBlock{100.021}{259.803}{421.979}{%
  \HLAClauseParagraph{\resizebox{72.842bp}{!}{\mbox{(4 +\space{}\textit{P}) mod\space{}\textit{V}\space{}= 0}}\newline{}\resizebox{72.378bp}{!}{\mbox{V = max (8,4) = 8}}\newline{}\resizebox{71.762bp}{!}{\mbox{(4 +\space{}\textit{P}) mod 8 = 0}}\newline{}\resizebox{21.722bp}{!}{\mbox{\textit{P}\space{}= 4}}}
}
\HLAStableID{m4.p085.b07}
\HLAClausePlacedBlock{90.000}{317.762}{432.046}{%
  \HLAClauseParagraph{\resizebox{432.046bp}{!}{\mbox{Thus, 4 bytes of padding are added after the number of elements component. A graphical representation of}}\newline{}\resizebox{232.083bp}{!}{\mbox{such an array, containing only one element, is as follows:}}}
}
\HLAStableID{m4.p085.b08}
\HLAClausePlacedBlock{89.999}{426.782}{432.001}{%
  \HLAClauseParagraph{\resizebox{431.910bp}{!}{\mbox{As a second example, consider an array, called\space{}\textit{VarArray}, consisting of a variable number of elements based}}\newline{}\resizebox{431.997bp}{!}{\mbox{on a 24-bit representation. The calculation for padding after the number\_of\_elements component is as}}\newline{}\resizebox{32.759bp}{!}{\mbox{follows:}}}
}
\HLAStableID{m4.p085.b09}
\HLAClausePlacedBlock{100.019}{469.801}{421.981}{%
  \HLAClauseParagraph{\resizebox{72.842bp}{!}{\mbox{(4 +\space{}\textit{P}) mod\space{}\textit{V}\space{}= 0}}\newline{}\resizebox{72.378bp}{!}{\mbox{V = max (4,4) = 4}}\newline{}\resizebox{71.762bp}{!}{\mbox{(4 +\space{}\textit{P}) mod 4 = 0}}\newline{}\resizebox{21.722bp}{!}{\mbox{\textit{P}\space{}= 0}}}
}
\HLAStableID{m4.p085.b10}
\HLAClausePlacedBlock{89.998}{526.800}{432.023}{%
  \HLAClauseParagraph{\resizebox{432.023bp}{!}{\mbox{Thus, no padding is added after the number\_of\_elements component. The amount of padding after each}}\newline{}\resizebox{391.668bp}{!}{\mbox{element, except the last, is calculated as follows (using the formula for\space{}\textit{HLAfixedArray}\space{}encoding):}}}
}
