\HLAClausePlacedBlock{100.017}{558.780}{421.983}{%
  \HLAClauseParagraph{\resizebox{88.386bp}{!}{\mbox{(\textit{Size}\HLATextSub{\textit{i}}\space{}+\space{}\textit{P}\HLATextSub{\textit{i}}) mod\space{}\textit{V}\space{}= 0}}\newline{}\resizebox{72.378bp}{!}{\mbox{V = max (4,4) = 4}}\newline{}\resizebox{73.981bp}{!}{\mbox{(3 +\space{}\textit{P}\HLATextSub{\textit{i}}) mod 4 = 0}}\newline{}\resizebox{23.942bp}{!}{\mbox{\textit{P}\HLATextSub{\textit{i}}\space{}= 1}}}
