\HLAClausePlacedBlock{90.000}{502.325}{432.055}{%
  \HLAClauseParagraph{\resizebox{432.055bp}{!}{\mbox{Any entry within any of the OMT tables may be annotated with additional descriptive information outside of}}\newline{}\resizebox{432.015bp}{!}{\mbox{the immediate table structure. This feature permits users to associate explanatory information with}}\newline{}\resizebox{242.401bp}{!}{\mbox{individual table entries to facilitate effective use of the data.}}}
}
\HLAStableID{m4.p086.b09}
\HLAClausePlacedBlock{90.000}{548.285}{432.029}{%
  \HLAClauseParagraph{\resizebox{431.998bp}{!}{\mbox{The mechanism for attaching one or more notes to an OMT table entry shall be to include a notes pointer in}}\newline{}\resizebox{432.029bp}{!}{\mbox{the appropriate table cell. In the tabular OMT format, this notes pointer shall consist of a uniquely}}\newline{}\resizebox{432.025bp}{!}{\mbox{identifying note label (or a series of comma-separated labels) preceded by an asterisk and enclosed by}}\newline{}\resizebox{432.004bp}{!}{\mbox{brackets. The notes themselves shall be associated with the note label and included in this table. For table}}\newline{}\resizebox{432.017bp}{!}{\mbox{cells with more than one information entry (e.g., a class name and a publish/subscribe designation), each}}\newline{}\resizebox{431.964bp}{!}{\mbox{entry may receive a separate note. Also, a single note may be referenced numerous times in OMT tables and}}\newline{}\resizebox{247.929bp}{!}{\mbox{that a single OMT table entry may reference numerous notes.}}}
}
