\HLAStableID{m4.p087.t02.c008}
\HLATableCellText{154.380}{389.500}{368.125}{9.000}{10.980}{l}{%
  \resizebox{361.734bp}{!}{\mbox{Merit raises are not provided according to any regular time interval; they are provided on a supervi-}}\newline{}\resizebox{288.949bp}{!}{\mbox{sor’s recommendation based on evidence of exceptional effort and performance.}}
}
\HLAStableID{m4.p087.t02.c009}
\HLATableCellText{107.040}{410.500}{41.470}{9.000}{10.080}{l}{%
