}
\HLAStableID{m4.p087.t02.c010}
\HLATableCellText{154.381}{410.500}{368.124}{9.000}{10.980}{l}{%
  \resizebox{361.612bp}{!}{\mbox{Years of service are a factor in any merit raise. This value is only changed on the anniversary of the}}\newline{}\resizebox{59.860bp}{!}{\mbox{employee’s hire.}}
}
\HLAStableID{m4.p087.t02.c011}
\HLATableCellText{107.041}{431.500}{41.469}{9.000}{10.080}{l}{%
  \resizebox{24.265bp}{!}{\mbox{Note 5}}
}
\HLAStableID{m4.p087.t02.c012}
\HLATableCellText{154.381}{431.500}{368.124}{9.000}{10.980}{l}{%
  \resizebox{361.699bp}{!}{\mbox{Sometimes a dish can be modified to be gluten- or wheat-free, e.g. gluten-free pasta can be used for}}\newline{}\resizebox{361.717bp}{!}{\mbox{some pasta dishes, but dishes like ravioli and lasagna are usually pre-made with wheat pasta and can’t}}\newline{}\resizebox{45.373bp}{!}{\mbox{be modified.}}
}
\HLAStableID{m4.p087.t02.c013}
\HLATableCellText{107.042}{463.479}{41.468}{9.000}{10.080}{l}{%
  \resizebox{24.258bp}{!}{\mbox{Note 6}}
}
\HLAStableID{m4.p087.t02.c014}
\HLATableCellText{154.381}{463.479}{368.124}{9.000}{13.980}{l}{%
  \resizebox{115.295bp}{!}{\mbox{Gluten Normalization Function:}}\newline{}\resizebox{266.887bp}{!}{\mbox{1) No—Ingredients contain wheat and those ingredients can’t be modified}}\newline{}\resizebox{361.678bp}{!}{\mbox{2) Intolerant—Ingredients can be modified to remove wheat, rye, or barley (cross-contamination free}}\newline{}\resizebox{74.493bp}{!}{\mbox{environment is N/A)}}\newline{}\resizebox{361.750bp}{!}{\mbox{3) Celiac —Ingredients can be modified to remove wheat, rye, or barley; prepared in cross-contami-}}\newline{}\resizebox{86.309bp}{!}{\mbox{nation free environment}}\newline{}\resizebox{361.764bp}{!}{\mbox{4) Allergy—Ingredients can be modified to remove wheat; prepared in cross-contamination free en-}}\newline{}\resizebox{36.948bp}{!}{\mbox{vironment}}\newline{}\resizebox{361.734bp}{!}{\mbox{5) All—No ingredients contain wheat, rye, or barley; prepared in cross-contamination free environ-}}\newline{}\resizebox{17.924bp}{!}{\mbox{ment}}
}
\HLAStableID{m4.p087.t02.c015}
\HLATableCellText{105.660}{587.306}{42.850}{9.960}{11.155}{l}{%
  \resizebox{26.929bp}{!}{\mbox{Note 7}}
}
\HLAStableID{m4.p087.t02.c016}
\HLATableCellText{154.380}{587.501}{368.125}{9.000}{10.980}{l}{%
  \resizebox{361.687bp}{!}{\mbox{Gluten is found in three grains: wheat, barley, and rye. Gluten intolerant individuals will have varying}}\newline{}\resizebox{361.738bp}{!}{\mbox{degrees of negative, but not necessarily debilitating, reactions to these foods. Individuals with Celiac}}\newline{}\resizebox{361.749bp}{!}{\mbox{disease will have debilitating reactions to these foods and suffer long-term, potentially life-threatening}}\newline{}\resizebox{361.621bp}{!}{\mbox{effects. Those with wheat allergies may suffer immediate, life-threatening reactions, but may be able}}\newline{}\resizebox{361.704bp}{!}{\mbox{to eat barley and rye. Depending on levels of sensitivity, cross-contamination in the kitchen can be}}\newline{}\resizebox{296.223bp}{!}{\mbox{dangerous to the extent that separate food preparation areas and tools are required.}}
}
\end{HLAClauseSemanticPage}

