\HLAClausePlacedBlock{90.000}{218.280}{245.234}{%
  \HLAClauseHeading{\resizebox{245.234bp}{!}{\mbox{\textbf{7. FOM module/SOM module merging rules}}}}
}
\HLAStableID{m6.p101.b02}
\HLAClausePlacedBlock{90.000}{244.926}{432.019}{%
  \HLAClauseParagraph{\resizebox{432.019bp}{!}{\mbox{In the interest of reuse and efficiency, FOM modules and SOM modules may be combined to formulate}}\newline{}\resizebox{432.002bp}{!}{\mbox{FOMs and SOMs for federations and federates, respectively. In the case where such modules are to be}}\newline{}\resizebox{431.949bp}{!}{\mbox{merged in the creation of a FOM or SOM, the rules provided in this clause are intended to assist both the}}\newline{}\resizebox{360.330bp}{!}{\mbox{user and facilitate common tool functionality for the development of HLA object models.}}}
}
\HLAStableID{m6.p101.b03}
\HLAClausePlacedBlock{90.000}{304.925}{432.000}{%
  \HLAClauseParagraph{\resizebox{424.383bp}{!}{\mbox{The following rules shall apply when constructing FOMs or SOMs from FOM modules or SOM modules:}}}
}
\HLAStableID{m6.p101.b04}
\HLAClausePlacedBlock{100.020}{319.924}{424.080}{%
  \HLAClauseDashItem{\resizebox{400.019bp}{!}{\mbox{All descriptions of object classes, interaction classes, attributes, class directed interactions,}}\newline{}\resizebox{400.001bp}{!}{\mbox{parameters, dimensions, synchronization points, transportation types, update rates, data types, notes}}\newline{}\resizebox{163.294bp}{!}{\mbox{and FOM/SOM lexicon shall be merged.}}}
}
\HLAStableID{m6.p101.b05}
\HLAClausePlacedBlock{100.020}{358.924}{424.080}{%
  \HLAClauseDashItem{\resizebox{400.004bp}{!}{\mbox{During the merge process, the FOM/SOM shall contain the references column where the}}\newline{}\resizebox{400.041bp}{!}{\mbox{“Composed from” field shall contain references to contributing FOM/SOM modules. All object}}\newline{}\resizebox{399.966bp}{!}{\mbox{model identification table sub-elements shall be left blank to be filled-in by the FOM/SOM}}\newline{}\resizebox{137.398bp}{!}{\mbox{developer after the merge process.}}}
}
\HLAStableID{m6.p101.b06}
\HLAClausePlacedBlock{100.020}{409.923}{424.080}{%
  \HLAClauseDashItem{\resizebox{400.021bp}{!}{\mbox{The tables for time representation and user defined tags shall be provided in at least one FOM or}}\newline{}\resizebox{363.705bp}{!}{\mbox{SOM. The tables shall be identical to the corresponding tables in the FOM/SOM modules.}}}
}
\HLAStableID{m6.p101.b07}
\HLAClausePlacedBlock{100.020}{436.923}{424.080}{%
  \HLAClauseDashItem{\resizebox{400.045bp}{!}{\mbox{The resulting FOM/SOM shall contain a service usage table if at least one of the contributing}}\newline{}\resizebox{399.991bp}{!}{\mbox{modules includes such a table. The value in the Usage column for each specific service shall be}}\newline{}\resizebox{400.003bp}{!}{\mbox{“Yes” if at least one contributing module has the value “Yes” in the Usage column for the same}}\newline{}\resizebox{144.210bp}{!}{\mbox{service. Otherwise, it shall be “No.”}}}
}
\HLAStableID{m6.p101.b08}
\HLAClausePlacedBlock{100.021}{487.922}{424.079}{%
  \HLAClauseDashItem{\resizebox{400.057bp}{!}{\mbox{The FOM shall contain a MIM, containing predefined constructs as described in the standard. A}}\newline{}\resizebox{400.049bp}{!}{\mbox{MIM that is extended by the user may be specified; otherwise the MIM as defined in the HLA}}\newline{}\resizebox{227.576bp}{!}{\mbox{standard shall be used. A SOM may also contain a MIM.}}}
}
\HLAStableID{m6.p101.b09}
\HLAClausePlacedBlock{90.001}{535.921}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.967bp}{!}{\mbox{The principles used to combine FOM modules or SOM modules, described in Annex C, are intended to}}\newline{}\resizebox{432.000bp}{!}{\mbox{produce the results identified in Table 56. If the set of FOM modules or SOM modules, when combined, do}}\newline{}\resizebox{431.949bp}{!}{\mbox{not produce such results, then the FOM or SOM being assembled shall not be considered a compliant object}}\newline{}\resizebox{27.442bp}{!}{\mbox{model.}}}
}
