\HLAStableID{m6.p102.t01.c010}
\HLATableCellText{210.299}{237.999}{194.171}{9.000}{10.020}{l}{%
  \resizebox{187.102bp}{!}{\mbox{The resulting FOM or SOM shall contain the union}}\newline{}\resizebox{184.771bp}{!}{\mbox{of the object classes in all modules. If several mod-}}\newline{}\resizebox{180.334bp}{!}{\mbox{ules contain regular definitions of a named object}}\newline{}\resizebox{183.162bp}{!}{\mbox{class, all regular definitions shall be identical with}}\newline{}\resizebox{178.245bp}{!}{\mbox{respect to name, sharing and semantics. For each}}\newline{}\resizebox{188.434bp}{!}{\mbox{named object class, the resulting FOM or SOM shall}}\newline{}\resizebox{187.374bp}{!}{\mbox{contain the union of all attributes in all modules for}}\newline{}\resizebox{188.060bp}{!}{\mbox{that class. Each definition of a named attribute for a}}\newline{}\resizebox{187.575bp}{!}{\mbox{given object class shall be identical.. Attribute prop-}}\newline{}\resizebox{174.220bp}{!}{\mbox{erties shall be compared as described in a subse-}}\newline{}\resizebox{188.132bp}{!}{\mbox{quent table row. Scaffolding object class definitions}}\newline{}\resizebox{173.798bp}{!}{\mbox{shall not be taken into account. For each named}}\newline{}\resizebox{182.187bp}{!}{\mbox{object class, the resulting FOM or SOM shall also}}\newline{}\resizebox{181.946bp}{!}{\mbox{contain the union of all dimensions in all modules}}\newline{}\resizebox{48.245bp}{!}{\mbox{for that class.}}
}
