\HLATableCellText{210.286}{136.961}{194.184}{9.960}{12.000}{l}{%
  \resizebox{188.072bp}{!}{\mbox{The resulting FOM or SOM shall contain the union}}\newline{}\resizebox{188.088bp}{!}{\mbox{of the data types in all modules. If several modules}}\newline{}\resizebox{188.085bp}{!}{\mbox{contain definitions of a named data type, all}}\newline{}\resizebox{188.032bp}{!}{\mbox{definitions shall be identical with respect to all}}\newline{}\resizebox{141.157bp}{!}{\mbox{columns, with the following exception:}}\newline{}\hspace*{10.034bp}\makebox[177.956bp][l]{—\hfill{}For a named enumerated data type, the}\newline{}\hspace*{32.053bp}\resizebox{155.973bp}{!}{\mbox{representation and semantics columns}}\newline{}\hspace*{32.053bp}\resizebox{155.979bp}{!}{\mbox{shall be identical. For the enumerators}}\newline{}\hspace*{32.053bp}\resizebox{155.968bp}{!}{\mbox{of a named enumerated data type, the}}\newline{}\hspace*{32.053bp}\resizebox{155.984bp}{!}{\mbox{resulting FOM or SOM shall contain}}\newline{}\hspace*{32.053bp}\resizebox{155.940bp}{!}{\mbox{the union of all enumerators and their}}\newline{}\hspace*{32.053bp}\resizebox{155.974bp}{!}{\mbox{associated values in all modules. For}}\newline{}\hspace*{32.053bp}\makebox[156.024bp][l]{each\hfill{}enumerator,\hfill{}of\hfill{}a\hfill{}named}\newline{}\hspace*{32.053bp}\resizebox{156.070bp}{!}{\mbox{enumerated data type, the resulting}}\newline{}\hspace*{32.053bp}\resizebox{156.018bp}{!}{\mbox{FOM or SOM shall contain the union}}\newline{}\hspace*{32.053bp}\resizebox{156.017bp}{!}{\mbox{of all values associated with that}}\newline{}\hspace*{32.053bp}\resizebox{156.057bp}{!}{\mbox{enumerator in all modules. Each value}}\newline{}\hspace*{32.053bp}\resizebox{156.053bp}{!}{\mbox{of a named enumerated data type shall}}\newline{}\hspace*{32.053bp}\resizebox{126.293bp}{!}{\mbox{map to exactly one enumerator.}}\newline{}\hspace*{10.034bp}\makebox[178.001bp][l]{—\hfill{}For a named variant record data type}\newline{}\hspace*{32.053bp}\makebox[155.988bp][l]{that\hfill{}uses\hfill{}the}\newline{}\hspace*{32.053bp}\resizebox{122.625bp}{!}{\mbox{HLAextendableVariantRecord}}\newline{}\hspace*{32.053bp}\resizebox{155.993bp}{!}{\mbox{encoding, the discriminant name,}}\newline{}\hspace*{32.053bp}\makebox[156.026bp][l]{discriminant\hfill{}type,\hfill{}encoding\hfill{}and}\newline{}\hspace*{32.053bp}\resizebox{156.048bp}{!}{\mbox{semantics columns shall be identical.}}\newline{}\hspace*{32.053bp}\resizebox{156.045bp}{!}{\mbox{For the alternatives of a named variant}}\newline{}\hspace*{32.053bp}\resizebox{155.968bp}{!}{\mbox{record data type, the resulting FOM or}}\newline{}\hspace*{32.053bp}\resizebox{156.081bp}{!}{\mbox{SOM shall contain the union of all}}\newline{}\hspace*{32.053bp}\makebox[155.953bp][l]{named\hfill{}alternatives\hfill{}with\hfill{}their}\newline{}\hspace*{32.053bp}\resizebox{155.900bp}{!}{\mbox{associated discriminant enumerator}}\newline{}\hspace*{32.053bp}\resizebox{155.986bp}{!}{\mbox{sets, alternative types and alternative}}\newline{}\hspace*{32.053bp}\resizebox{156.035bp}{!}{\mbox{semantics in all modules. For a named}}\newline{}\hspace*{32.053bp}\resizebox{155.996bp}{!}{\mbox{alternative of a named variant record}}\newline{}\hspace*{32.053bp}\resizebox{156.012bp}{!}{\mbox{data type, the associated alternative}}\newline{}\hspace*{32.053bp}\resizebox{156.024bp}{!}{\mbox{types and semantics shall be identical.}}\newline{}\hspace*{32.053bp}\resizebox{155.978bp}{!}{\mbox{For each named alternative of a named}}\newline{}\hspace*{32.053bp}\resizebox{155.974bp}{!}{\mbox{variant record data type, the resulting}}\newline{}\hspace*{32.053bp}\resizebox{156.018bp}{!}{\mbox{FOM or SOM shall contain the union}}\newline{}\hspace*{32.053bp}\makebox[156.000bp][l]{of\hfill{}all\hfill{}associated\hfill{}discriminator}\newline{}\hspace*{32.053bp}\resizebox{156.038bp}{!}{\mbox{enumerator sets. Each discriminant}}\newline{}\hspace*{32.053bp}\resizebox{155.986bp}{!}{\mbox{enumerator, specified as a single}}\newline{}\hspace*{32.053bp}\resizebox{156.056bp}{!}{\mbox{enumerator or part of a range, shall}}\newline{}\hspace*{32.053bp}\resizebox{156.019bp}{!}{\mbox{map to exactly one alternative for a}}\newline{}\hspace*{32.053bp}\resizebox{126.280bp}{!}{\mbox{named variant record data type.}}
}
