\HLAClausePlacedBlock{89.999}{157.806}{432.086}{%
  \HLAClauseParagraph{\resizebox{432.072bp}{!}{\mbox{The OMT table specifications use a subset of Backus Naur Form (BNF) [B5] to specify the types of entries}}\newline{}\resizebox{432.085bp}{!}{\mbox{that belong in particular table cells. In BNF, the types of terms to be substituted in the table are enclosed in}}\newline{}\resizebox{431.969bp}{!}{\mbox{angle brackets (e.g.,\space{}\textit{<class>})\textit{.}\space{}Optional entries are enclosed in square brackets (e.g.,\space{}\textit{[<class> (<p/s>)]}).}}\newline{}\resizebox{432.050bp}{!}{\mbox{Any parentheses are terminal characters that should appear as shown. Thus, the basic entry in a cell of the}}\newline{}\resizebox{432.001bp}{!}{\mbox{object class structure table, designated by\space{}\textit{<class> (<p/s>),}\space{}indicates a class name followed by a\space{}\textit{Publish/}}}\newline{}\resizebox{125.196bp}{!}{\mbox{\textit{Subscribe}\space{}code in parentheses.}}}
}
