  \HLAClauseParagraph{\resizebox{431.835bp}{!}{\mbox{When developing a FOM (or SOM), the first FOM module (or SOM module) selected provides the basis for}}\newline{}\resizebox{431.998bp}{!}{\mbox{the desired object model. Therefore, all the elements of the first FOM module (or SOM module) shall be}}\newline{}\resizebox{432.034bp}{!}{\mbox{incorporated into the FOM under development. The method for merging subsequent FOM modules (or}}\newline{}\resizebox{432.128bp}{!}{\mbox{SOM modules) should be performed using a top-down approach beginning with the object classes and}}\newline{}\resizebox{432.039bp}{!}{\mbox{interaction classes beginning at their root nodes. This is to confirm that all candidate object classes (and their}}\newline{}\resizebox{431.934bp}{!}{\mbox{attributes), interaction classes (and their parameters) and associated data types, dimensions, transportation,}}\newline{}\resizebox{432.065bp}{!}{\mbox{and notes that may be referenced by an object class or interaction class are properly considered for}}\newline{}\resizebox{431.975bp}{!}{\mbox{integration and are properly aligned when merged within the FOM (or SOM). A top-down approach requires}}\newline{}\resizebox{374.676bp}{!}{\mbox{that nodes representing a FOM module be walked down from the root node to the leaf nodes.}}}
}
\HLAStableID{m6.p109.b06}
\HLAClausePlacedBlock{90.000}{349.803}{432.079}{%
  \HLAClauseParagraph{\resizebox{431.953bp}{!}{\mbox{Following the parsing of object classes, interaction classes and their associated attributes, parameters, data}}\newline{}\resizebox{432.017bp}{!}{\mbox{types, dimensions, transportations, and notes, additional items that shall be considered for merging include}}\newline{}\resizebox{432.079bp}{!}{\mbox{the parsing of any defined synchronizations, updateRates, and remaining notes, which need to be compared}}\newline{}\resizebox{221.210bp}{!}{\mbox{and considered for integration into the FOM (or SOM).}}}
}
\HLAStableID{m6.p109.b07}
\HLAClausePlacedBlock{90.000}{421.140}{127.939}{%
  \HLAAnnexSubclauseHeading{C.1 Merging metadata}
}
\HLAStableID{m6.p109.b08}
\HLAClausePlacedBlock{90.000}{447.786}{432.093}{%
  \HLAClauseParagraph{\resizebox{432.012bp}{!}{\mbox{Each FOM module (or SOM module) used in the merging process shall be referenced in the resulting}}\newline{}\resizebox{431.969bp}{!}{\mbox{FOM’s (or SOM’s) object model identification table.Such references allow it to be known what FOM}}\newline{}\resizebox{431.956bp}{!}{\mbox{modules (or SOM modules) have been used in the construction of a FOM (or SOM), allowing their metadata}}\newline{}\resizebox{432.030bp}{!}{\mbox{to be further explored.Thus, for each module used in the creation of the FOM (or SOM), the value of the}}\newline{}\resizebox{432.031bp}{!}{\mbox{Reference Type field shall be “Composed\_From,” and the value of the Reference Identification field shall}}\newline{}\resizebox{432.093bp}{!}{\mbox{contain the names of all FOM modules or SOM modules whose merger has resulted in the current object}}\newline{}\resizebox{29.965bp}{!}{\mbox{model.}}}
}
\HLAStableID{m6.p109.b09}
\HLAClausePlacedBlock{90.000}{543.784}{432.120}{%
  \HLAClauseParagraph{\resizebox{431.970bp}{!}{\mbox{With the exception of identifying such module references, all object model identification table sub-elements}}\newline{}\resizebox{431.955bp}{!}{\mbox{shall be left blank during the merge process. For all other object model identification table fields, it is the}}\newline{}\resizebox{432.025bp}{!}{\mbox{responsibility of the FOM/SOM developer to complete the required metadata elements. This information}}\newline{}\resizebox{432.119bp}{!}{\mbox{shall be completed at the conclusion of the merging process in order for the resulting FOM or SOM to be a}}\newline{}\resizebox{99.414bp}{!}{\mbox{compliant object model.}}}
}
\HLAStableID{m6.p109.b10}
\HLAClausePlacedBlock{90.000}{627.120}{115.294}{%
