\HLAClausePlacedBlock{90.000}{128.806}{335.986}{%
  {\HLAArial\fontsize{21.960bp}{22.979bp}\selectfont\raggedright \resizebox{193.112bp}{!}{\mbox{\textbf{IEEE Standard for}}}\newline{}\resizebox{335.986bp}{!}{\mbox{\textbf{Modeling and Simulation (M\&S)}}}\newline{}\resizebox{334.776bp}{!}{\mbox{\textbf{High Level Architecture (HLA)—}}}\newline{}\resizebox{316.455bp}{!}{\mbox{\textbf{Object Model Template (OMT)}}}\newline{}\resizebox{136.863bp}{!}{\mbox{\textbf{Specification}}}\par}
}
\HLAStableID{m3.p013.b02}
\HLAClausePlacedBlock{90.000}{291.120}{66.696}{%
  {\HLAArial\fontsize{12.000bp}{14.160bp}\selectfont\raggedright \resizebox{66.696bp}{!}{\mbox{\textbf{1. Overview}}}\par}
}
\HLAStableID{m3.p013.b03}
\HLAClausePlacedBlock{90.000}{323.423}{51.289}{%
  {\HLAArial\fontsize{10.980bp}{12.956bp}\selectfont\raggedright \resizebox{51.289bp}{!}{\mbox{\textbf{1.1 Scope}}}\par}
}
\HLAStableID{m3.p013.b04}
\HLAClausePlacedBlock{90.000}{348.786}{432.012}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.012bp}{!}{\mbox{This document defines the format and syntax for recording information in High Level Architecture (HLA)}}\newline{}\resizebox{431.981bp}{!}{\mbox{object models, to include objects, attributes, interactions, and parameters. It does not define the specific data}}\newline{}\resizebox{253.438bp}{!}{\mbox{(e.g., vehicles, unit types) that will appear in the object models.}}\par}
}
\HLAStableID{m3.p013.b05}
\HLAClausePlacedBlock{90.000}{402.383}{62.271}{%
  {\HLAArial\fontsize{10.980bp}{12.956bp}\selectfont\raggedright \resizebox{62.271bp}{!}{\mbox{\textbf{1.2 Purpose}}}\par}
}
\HLAStableID{m3.p013.b06}
\HLAClausePlacedBlock{90.000}{427.806}{432.080}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.997bp}{!}{\mbox{The HLA has been developed to provide a common architecture for distributed modeling and simulation.}}\newline{}\resizebox{431.963bp}{!}{\mbox{The HLA requires that federations (sets of federates) and individual federates (simulations, supporting}}\newline{}\resizebox{432.080bp}{!}{\mbox{utilities, or interfaces to live systems) be described by an object model that identifies the data exchanged at}}\newline{}\resizebox{410.127bp}{!}{\mbox{runtime to achieve federation objectives. This standard defines the documentation of the object model.}}\par}
}
\HLAStableID{m3.p013.b07}
\HLAClausePlacedBlock{90.000}{493.403}{82.433}{%
  {\HLAArial\fontsize{10.980bp}{12.956bp}\selectfont\raggedright \resizebox{82.433bp}{!}{\mbox{\textbf{1.3 Word Usage}}}\par}
}
\HLAStableID{m3.p013.b08}
\HLAClausePlacedBlock{90.000}{518.826}{431.969}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.969bp}{!}{\mbox{The word\space{}\textit{shall}\space{}indicates mandatory requirements strictly to be followed in order to conform to the standard}}\newline{}\resizebox{289.230bp}{!}{\mbox{and from which no deviation is permitted (shall equals is required to).\HLATextSup{6,7}}}\par}
}
\HLAStableID{m3.p013.b09}
\HLAClausePlacedBlock{90.000}{554.826}{432.004}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.989bp}{!}{\mbox{The word\space{}\textit{should}\space{}indicates that among several possibilities one is recommended as particularly suitable,}}\newline{}\resizebox{432.004bp}{!}{\mbox{without mentioning or excluding others; or that a certain course of action is preferred but not necessarily}}\newline{}\resizebox{185.489bp}{!}{\mbox{required (should equals is recommended that).}}\par}
}
\HLAStableID{m3.p013.b10}
\HLAClausePlacedBlock{90.000}{602.825}{431.953}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.953bp}{!}{\mbox{The word\space{}\textit{may}\space{}is used to indicate a course of action permissible within the limits of the standard (may equals}}\newline{}\resizebox{63.593bp}{!}{\mbox{is permitted to).}}\par}
}
\HLAStableID{m3.p013.b11}
\HLAClausePlacedBlock{90.000}{638.824}{431.974}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.974bp}{!}{\mbox{The word\space{}\textit{can}\space{}is used for statements of possibility and capability, whether material, physical, or causal (can}}\newline{}\resizebox{69.972bp}{!}{\mbox{equals is able to).}}\par}
}
\HLAStableID{m3.p013.b12}
\HLAClausePlacedBlock{89.999}{685.473}{432.040}{%
  {\HLATimes\fontsize{7.980bp}{10.020bp}\selectfont\raggedright \resizebox{432.039bp}{!}{\mbox{\HLATextSup{6}The use of the word\space{}\textit{must}\space{}is deprecated and cannot be used when stating mandatory requirements,\space{}\textit{must}\space{}is used only to describe}}\newline{}\resizebox{73.717bp}{!}{\mbox{unavoidable situations.}}\newline{}\resizebox{432.015bp}{!}{\mbox{\HLATextSup{7}The use of the word\space{}\textit{will}\space{}is deprecated and cannot be used when stating mandatory requirements,\space{}\textit{will}\space{}is only used in statements of fact.}}\par}
}
\end{HLASemanticPage}

% Faithful native semantic reconstruction of physical page 14 / printed page 13.
\begin{HLAClauseSemanticPage}{13}
\HLAStableID{m3.page.014}
\HLAStableID{m3.p014.b01}
\HLAClausePlacedBlock{90.000}{69.383}{82.432}{%
  {\HLAArial\fontsize{10.980bp}{12.956bp}\selectfont\raggedright \resizebox{82.432bp}{!}{\mbox{\textbf{1.4 Background}}}\par}
}
\HLAStableID{m3.p014.b02}
\HLAClausePlacedBlock{90.000}{94.666}{176.444}{%
  {\HLAArial\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{176.444bp}{!}{\mbox{\textbf{1.4.1 Object model template rationale}}}\par}
}
\HLAStableID{m3.p014.b03}
\HLAClausePlacedBlock{90.000}{118.805}{432.083}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.083bp}{!}{\mbox{A standardized structural framework, or template, for specifying HLA object models is an essential}}\newline{}\resizebox{198.363bp}{!}{\mbox{component of the HLA for the following reasons:}}\par}
}
\HLAStableID{m3.p014.b04}
\HLAClausePlacedBlock{100.020}{148.805}{421.876}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \makebox[421.876bp][l]{—\hfill{}\space{}It provides a commonly understood mechanism for specifying the exchange of data and general}\newline{}\hspace*{21.960bp}\resizebox{182.691bp}{!}{\mbox{coordination among members of a federation.}}\par}
}
\HLAStableID{m3.p014.b05}
\HLAClausePlacedBlock{100.020}{175.804}{421.973}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \makebox[421.973bp][l]{—\hfill{}\space{}It provides a common, standardized mechanism for describing the capabilities of potential}\newline{}\hspace*{21.960bp}\resizebox{82.174bp}{!}{\mbox{federation members.}}\par}
}
\HLAStableID{m3.p014.b06}
\HLAClausePlacedBlock{100.020}{202.804}{421.993}{%
  {\HLATimes\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \makebox[421.993bp][l]{—\hfill{}\space{}It facilitates the design and application of common tool sets for development of HLA object models.}\par}
}
\HLAStableID{m3.p014.b07}
\HLAClausePlacedBlock{90.000}{226.804}{432.123}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.008bp}{!}{\mbox{HLA object models may be used to describe an individual federation member (federate), creating an HLA}}\newline{}\resizebox{431.988bp}{!}{\mbox{simulation object model (SOM), or to describe a named set of multiple interacting federates (federation),}}\newline{}\resizebox{431.853bp}{!}{\mbox{creating a federation object model (FOM). HLA object models may also be used to define subsets of a FOM}}\newline{}\resizebox{431.977bp}{!}{\mbox{or SOM, which are identified as FOM modules and SOM modules respectively. In whichever case, the}}\newline{}\resizebox{431.994bp}{!}{\mbox{primary objective of the HLA object model template (OMT) is to facilitate interoperability among}}\newline{}\resizebox{432.123bp}{!}{\mbox{simulations and reuse of simulation components. All discussion of HLA object models in this document}}\newline{}\resizebox{380.069bp}{!}{\mbox{applies to FOMs, SOMs, FOM modules, and SOM modules, unless explicitly stated otherwise.}}\par}
}
\HLAStableID{m3.p014.b08}
\HLAClausePlacedBlock{90.000}{322.663}{148.837}{%
  {\HLAArial\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{148.837bp}{!}{\mbox{\textbf{1.4.2 Federation object models}}}\par}
}
\HLAStableID{m3.p014.b09}
\HLAClausePlacedBlock{89.999}{346.802}{432.098}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.994bp}{!}{\mbox{During development of an HLA federation, it is critical that all federation members achieve a common}}\newline{}\resizebox{431.934bp}{!}{\mbox{understanding as to the nature or character of all required communications among participating federates.}}\newline{}\resizebox{431.956bp}{!}{\mbox{The primary purpose of an HLA FOM is to provide a specification for data exchange among federates in a}}\newline{}\resizebox{432.097bp}{!}{\mbox{common, standardized format. The content of this data includes an enumeration of all object and interaction}}\newline{}\resizebox{431.974bp}{!}{\mbox{classes pertinent to the federation and a specification of the attributes or parameters that characterize these}}\newline{}\resizebox{432.007bp}{!}{\mbox{classes. Taken together, the individual components of an HLA FOM establish the “information model}}\newline{}\resizebox{375.006bp}{!}{\mbox{contract” that is necessary (but not sufficient) to achieve interoperability among the federates.}}\par}
}
\HLAStableID{m3.p014.b10}
\HLAClausePlacedBlock{89.999}{442.800}{431.969}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.969bp}{!}{\mbox{A FOM can be constructed as a single self-contained entity, or can be composed from multiple FOM}}\newline{}\resizebox{337.783bp}{!}{\mbox{modules.   In this first case, the FOM is said to consist of exactly one FOM module.}}\par}
}
\HLAStableID{m3.p014.b11}
\HLAClausePlacedBlock{89.999}{478.660}{146.050}{%
  {\HLAArial\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{146.050bp}{!}{\mbox{\textbf{1.4.3 Simulation object models}}}\par}
}
\HLAStableID{m3.p014.b12}
\HLAClausePlacedBlock{89.998}{502.799}{432.099}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.098bp}{!}{\mbox{A critical step in the formation of a federation is the process of determining the composition of individual}}\newline{}\resizebox{432.048bp}{!}{\mbox{federates to best meet the sponsor’s overall objectives. An HLA SOM is a specification of the types of}}\newline{}\resizebox{431.964bp}{!}{\mbox{information that an individual federate can provide to HLA federations and the information that an}}\newline{}\resizebox{432.016bp}{!}{\mbox{individual federate can receive from other federates in HLA federations. The standard format in which}}\newline{}\resizebox{428.790bp}{!}{\mbox{SOMs are expressed facilitates determination of the suitability of federates for participation in a federation.}}\par}
}
\HLAStableID{m3.p014.b13}
\HLAClausePlacedBlock{90.000}{574.798}{432.031}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.031bp}{!}{\mbox{The HLA OMT formats described in this document are generally applicable to either FOMs or SOMs, and}}\newline{}\resizebox{431.942bp}{!}{\mbox{also the FOM modules and SOM modules that can be used to formulate a FOM or SOM. Thus, SOMs and}}\newline{}\resizebox{431.945bp}{!}{\mbox{SOM modules are also characterized by their objects, attributes, interactions, and parameters. A SOM is}}\newline{}\resizebox{431.968bp}{!}{\mbox{specified using one or more SOM modules and one optional Management Object Model (MOM) and}}\newline{}\resizebox{431.913bp}{!}{\mbox{Initialization Module (MIM). The primary benefit from the common utilization of the OMT formats for}}\newline{}\resizebox{431.980bp}{!}{\mbox{FOMs, FOM modules, SOMs, and SOM modules is that it provides a common frame of reference for}}\newline{}\resizebox{431.956bp}{!}{\mbox{describing object models in the HLA community. In some cases, this commonality may even allow SOM}}\newline{}\resizebox{325.579bp}{!}{\mbox{modules to be integrated as piece parts in a FOM, facilitating FOM construction.}}\par}
}
\end{HLAClauseSemanticPage}

% Faithful native semantic reconstruction of physical page 15 / printed page 14.
\begin{HLAClauseSemanticPage}{14}
\HLAStableID{m3.page.015}
\HLAStableID{m3.p015.r01}
\HLAClauseRule{91.020}{693.000}{36.240}{0.480}
\HLAStableID{m3.p015.b01}
\HLAClausePlacedBlock{90.000}{69.646}{262.681}{%
  {\HLAArial\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{262.681bp}{!}{\mbox{\textbf{1.4.4 Relationship of HLA and object-oriented concepts}}}\par}
}
\HLAStableID{m3.p015.b02}
\HLAClausePlacedBlock{89.999}{93.785}{432.033}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.944bp}{!}{\mbox{Although the HLA OMT is the standardized documentation structure for HLA object models, FOMs, FOM}}\newline{}\resizebox{431.952bp}{!}{\mbox{modules, SOMs, and SOM modules do not completely correspond to common definitions of object models}}\newline{}\resizebox{431.984bp}{!}{\mbox{in object-oriented analysis and design (OOAD) techniques. In the OOAD literature, an object model is}}\newline{}\resizebox{431.997bp}{!}{\mbox{described as an abstraction of a system developed for the purpose of fully understanding the system. To}}\newline{}\resizebox{431.929bp}{!}{\mbox{achieve this understanding, most object-oriented (OO) techniques recommend defining several views of the}}\newline{}\resizebox{431.986bp}{!}{\mbox{system. For HLA object models, the intended scope of the system description is much narrower, focusing}}\newline{}\resizebox{431.960bp}{!}{\mbox{mainly on requirements and capabilities for federate information exchange. For SOMs and SOM modules,}}\newline{}\resizebox{431.980bp}{!}{\mbox{the intent is to describe the public interface of the federate in terms of an identified set of supported HLA}}\newline{}\resizebox{431.975bp}{!}{\mbox{object classes and interaction classes. A more complete description of how a federate is designed and}}\newline{}\resizebox{431.987bp}{!}{\mbox{functions internally (for example, a traditional OO object model) should be provided via documentation}}\newline{}\resizebox{432.033bp}{!}{\mbox{resources other than the SOM. For FOMs and FOM modules, the intent is to describe information exchange}}\newline{}\resizebox{175.081bp}{!}{\mbox{that happens during a federation execution.}}\par}
}
\HLAStableID{m3.p015.b03}
\HLAClausePlacedBlock{89.999}{249.783}{432.080}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.080bp}{!}{\mbox{Differences between HLA and OOAD principles and concepts also appear at the individual object level. In}}\newline{}\resizebox{431.978bp}{!}{\mbox{the OOAD literature, objects are defined as software encapsulations of data and operations (methods). In the}}\newline{}\resizebox{431.939bp}{!}{\mbox{HLA, objects are defined entirely by the identifying characteristics (attributes), values of which are}}\newline{}\resizebox{432.017bp}{!}{\mbox{exchanged between federates during a federation execution. Any OO-related behaviors and operations that}}\newline{}\resizebox{432.024bp}{!}{\mbox{affect the values of HLA object attributes are kept resident in the federates. Although HLA class structures}}\newline{}\resizebox{431.991bp}{!}{\mbox{are driven by subscription requirements and FOM growth concerns, class structures in OO systems are}}\newline{}\resizebox{240.972bp}{!}{\mbox{typically driven by efficiency and maintainability concerns.}}\par}
}
\HLAStableID{m3.p015.b04}
\HLAClausePlacedBlock{89.998}{345.781}{432.105}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.103bp}{!}{\mbox{As discussed above, HLA object classes are described by the attributes that are defined for them. These are,}}\newline{}\resizebox{432.045bp}{!}{\mbox{in OO parlance, data members of the class. These attributes, which are abstract properties of HLA object}}\newline{}\resizebox{432.032bp}{!}{\mbox{classes, are referred to as class attributes. HLA object instances are spawned via an HLA service using an}}\newline{}\resizebox{432.003bp}{!}{\mbox{HLA object class as a template. Each attribute contained by an HLA object instance is called an\space{}\textit{instance}}}\newline{}\resizebox{36.930bp}{!}{\mbox{\textit{attribute}.}}\par}
}
\HLAStableID{m3.p015.b05}
\HLAClausePlacedBlock{89.998}{417.780}{432.124}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.030bp}{!}{\mbox{OO objects interact via message passing, in which one OO object invokes an operation provided by another}}\newline{}\resizebox{432.124bp}{!}{\mbox{OO object. HLA objects do not directly interact. It is the federates that interact, via HLA services, by}}\newline{}\resizebox{431.972bp}{!}{\mbox{updating instance attribute values or sending interactions. Also, responsibility for updating the instance}}\newline{}\resizebox{431.906bp}{!}{\mbox{attributes associated with an HLA object instance can be distributed among different federates in a}}\newline{}\resizebox{431.976bp}{!}{\mbox{federation (effectively distributing responsibility for maintaining the HLA object instance’s state across the}}\newline{}\resizebox{432.013bp}{!}{\mbox{federation), whereas OO objects encapsulate state locally and associate update responsibilities with}}\newline{}\resizebox{386.098bp}{!}{\mbox{operations that are closely tied to the object’s implementation in an OO programming language.}}\par}
}
\HLAStableID{m3.p015.b06}
\HLAClausePlacedBlock{89.998}{513.779}{432.032}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.974bp}{!}{\mbox{Specialization of HLA object and interaction classes are discussed in terms of data tree structures. A data}}\newline{}\resizebox{431.988bp}{!}{\mbox{tree structure is defined as, “an abstract hierarchical structure consisting of nodes [classes] connected by}}\newline{}\resizebox{432.028bp}{!}{\mbox{branches, in which; each branch connects one node [class] to a directly subsidiary node; there is a unique}}\newline{}\resizebox{431.960bp}{!}{\mbox{node called the root [root class] which is not subsidiary to any other node; and every node [class] besides the}}\newline{}\resizebox{432.032bp}{!}{\mbox{root is directly subsidiary to exactly one other node [class]” (\textit{The IEEE Standards Dictionary Online}).\HLATextSup{8}}}\par}
}
\HLAStableID{m3.p015.b07}
\HLAClausePlacedBlock{90.000}{573.786}{329.616}{%
  {\HLATimes\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{329.616bp}{!}{\mbox{Furthermore, a node without any subsidiary node is called a leaf node [leaf class].}}\par}
}
\HLAStableID{m3.p015.b08}
\HLAClausePlacedBlock{89.999}{597.785}{432.046}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.045bp}{!}{\mbox{In addition to the stated semantic variations in shared terminology, other differences may also exist. Precise}}\newline{}\resizebox{217.822bp}{!}{\mbox{definitions of all HLA terms can be found in Clause 3.}}\par}
}
\HLAStableID{m3.p015.b09}
\HLAClausePlacedBlock{90.000}{696.453}{432.016}{%
  {\HLATimes\fontsize{7.980bp}{9.000bp}\selectfont\raggedright \resizebox{432.016bp}{!}{\mbox{\HLATextSup{8}\textit{IEEE Standards Dictionary Online}\space{}is available at\space{}\textcolor{HLAc0000FF}{\uline{http://dictionary.ieee.org/}}. An IEEE account is required for access to the dictionary,}}\newline{}\resizebox{215.384bp}{!}{\mbox{and one can be created at no charge on the dictionary sign-in page.}}\par}
}
\end{HLAClauseSemanticPage}

