}
\HLAStableID{m3.p017.b06}
\HLAClausePlacedBlock{100.019}{249.783}{421.987}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \makebox[421.986bp][l]{a)\hfill{}\space{}Pertaining to an object class: the dimensions associated with that object class in union with the set of}\newline{}\hspace*{21.960bp}\resizebox{239.385bp}{!}{\mbox{inherited dimensions in the federation object model (FOM).}}\newline{}\makebox[421.971bp][l]{b)\hfill{}\space{}Pertaining to an attribute: The available dimensions of an instance attribute are the available}\newline{}\hspace*{21.960bp}\resizebox{399.939bp}{!}{\mbox{dimensions of the known class. When registering, subscribing, unsubscribing, requesting updates}}\newline{}\hspace*{21.960bp}\resizebox{400.028bp}{!}{\mbox{with regions or getting available dimensions, the available dimensions are the available dimensions}}\newline{}\hspace*{21.960bp}\resizebox{213.417bp}{!}{\mbox{of the object class specified in the service invocation.}}\newline{}\makebox[421.919bp][l]{c)\hfill{}\space{}Pertaining to an interaction class: the dimensions associated with that interaction class in union with}\newline{}\hspace*{21.960bp}\resizebox{400.023bp}{!}{\mbox{the set of inherited dimensions the FOM. The available dimensions of a sent interaction are the}}\newline{}\hspace*{21.960bp}\resizebox{400.003bp}{!}{\mbox{available dimensions of the interaction class specified in the\space{}\textit{Send Interaction with Regions}\space{}service}}\newline{}\hspace*{21.960bp}\resizebox{47.197bp}{!}{\mbox{invocation.}}\par}
}
\HLAStableID{m3.p017.b07}
\HLAClausePlacedBlock{121.980}{373.985}{162.000}{%
  {\HLATimes\fontsize{9.000bp}{10.620bp}\selectfont\raggedright \resizebox{162.000bp}{!}{\mbox{NOTE—See 9.1 in IEEE Std 1516.1-2025.\HLATextSup{14}}}\par}
}
