\HLAClausePlacedBlock{90.000}{397.806}{431.972}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.972bp}{!}{\mbox{\textbf{available directed interactions:}\space{}The set of directed interaction classes of an object class in union with the}}\newline{}\resizebox{223.423bp}{!}{\mbox{set of inherited directed interactions of that object class.}}\par}
}
\HLAStableID{m3.p017.b09}
\HLAClausePlacedBlock{90.000}{433.805}{431.978}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.978bp}{!}{\mbox{\textbf{available parameters:}\space{}The set of declared parameters of an interaction class in union with the set of}}\newline{}\resizebox{182.451bp}{!}{\mbox{inherited parameters of that interaction class.}}\par}
