}
\HLAStableID{m3.p017.b11}
\HLAClausePlacedBlock{90.000}{501.784}{432.067}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.067bp}{!}{\mbox{\textbf{candidate discovery class:}\space{}The registered class of an object instance, if subscribed. If the registered class of}}\newline{}\resizebox{432.047bp}{!}{\mbox{an object instance is not subscribed, the closest superclass of the registered class of the object instance to}}\newline{}\resizebox{397.264bp}{!}{\mbox{which the joined federate is subscribed. Candidate discovery class pertains to object instances only.}}\par}
