  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.897bp}{!}{\mbox{\textbf{candidate received class:}\space{}The sent class of an interaction, if subscribed. If the sent class of an interaction is}}\newline{}\resizebox{432.003bp}{!}{\mbox{not subscribed, the closest superclass of the sent class of the interaction to which the joined federate is}}\newline{}\resizebox{363.011bp}{!}{\mbox{subscribed. Candidate received class pertains to interactions and directed interactions only.}}\par}
}
