\HLAClausePlacedBlock{90.000}{117.785}{431.950}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.950bp}{!}{\mbox{\textbf{class hierarchy:}\space{}A specification of a class-subclass or “is-a” relationship between classes in a given}}\newline{}\resizebox{32.491bp}{!}{\mbox{domain.}}\par}
}
\HLAStableID{m3.p018.b03}
\HLAClausePlacedBlock{89.999}{153.784}{432.011}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.010bp}{!}{\mbox{\textbf{coadunate:}\space{}To attach an object instance handle and an object instance name to an object instance. The}}\newline{}\resizebox{431.954bp}{!}{\mbox{object instance name can be provided specifically by the federate or implicitly by the runtime infrastructure}}\newline{}\resizebox{24.630bp}{!}{\mbox{(RTI).}}\par}
}
\HLAStableID{m3.p018.b04}
\HLAClausePlacedBlock{89.999}{201.784}{431.962}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.962bp}{!}{\mbox{\textbf{collection:}\space{}A group of elements in which an element may occur multiple times (this definition corresponds}}\newline{}\resizebox{147.371bp}{!}{\mbox{to the mathematical notion of a bag).}}\par}
}
\HLAStableID{m3.p018.b05}
\HLAClausePlacedBlock{89.999}{237.783}{432.092}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.092bp}{!}{\mbox{\textbf{collection of pairs:}\space{}A group of pairs in which multiple pairs may have the same first component and a given}}\newline{}\resizebox{122.452bp}{!}{\mbox{pair may occur multiple times.}}\par}
}
\HLAStableID{m3.p018.b06}
\HLAClausePlacedBlock{89.999}{273.782}{432.019}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.975bp}{!}{\mbox{\textbf{compliant object model:}\space{}A High Level Architecture (HLA) federation object model (FOM) or simulation}}\newline{}\resizebox{432.019bp}{!}{\mbox{object model (SOM) that fully conforms with all of the rules and constraints specified in object model}}\newline{}\resizebox{68.195bp}{!}{\mbox{template (OMT).}}\par}
}
\HLAStableID{m3.p018.b07}
\HLAClausePlacedBlock{89.999}{319.802}{432.001}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.888bp}{!}{\mbox{\textbf{constrained set of pairs:}\space{}A group of pairs in which no two pairs have the same first component (this}}\newline{}\resizebox{432.001bp}{!}{\mbox{definition corresponds to the mathematical notion of a function). An example would be a group of instance}}\newline{}\resizebox{379.190bp}{!}{\mbox{attribute and value pairs; each instance attribute may have at most one value associated with it.}}\par}
}
\HLAStableID{m3.p018.b08}
\HLAClausePlacedBlock{89.999}{365.761}{431.999}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.996bp}{!}{\mbox{\textbf{corresponding class attribute of an instance attribute:}\space{}The class attribute that, from the perspective of a}}\newline{}\resizebox{431.998bp}{!}{\mbox{given joined federate, is the class attribute of the joined federate’s known class for the object instance}}\newline{}\resizebox{378.090bp}{!}{\mbox{containing the instance attribute that has the same attribute designator as the instance attribute.}}\par}
}
