\HLAStableID{m3.p020.b12}
\HLAClausePlacedBlock{90.000}{475.800}{432.018}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.005bp}{!}{\mbox{\textbf{federation object model (FOM):}\space{}A specification defining the information exchanged at runtime to achieve}}\newline{}\resizebox{432.018bp}{!}{\mbox{a given set of federation objectives. This information includes object classes, object class attributes,}}\newline{}\resizebox{431.919bp}{!}{\mbox{interaction classes, interaction parameters, and other relevant information. The FOM is specified to the}}\newline{}\resizebox{431.982bp}{!}{\mbox{runtime infrastructure (RTI) using one or more FOM modules. The RTI assembles a FOM using these FOM}}\newline{}\resizebox{431.974bp}{!}{\mbox{modules and one Management Object Model (MOM) and Initialization Module (MIM), which is provided}}\newline{}\resizebox{407.150bp}{!}{\mbox{automatically by the RTI or, optionally, provided to the RTI when the federation execution is created.}}\par}
