\HLAClausePlacedBlock{90.000}{69.786}{432.132}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.003bp}{!}{\mbox{\textbf{object class:}\space{}A fundamental element of a conceptual representation for a federate that reflects the real world}}\newline{}\resizebox{431.937bp}{!}{\mbox{at levels of abstraction and resolution appropriate for federate interoperability. An object class is a template}}\newline{}\resizebox{432.013bp}{!}{\mbox{for a set of characteristics that is common to a group of object instances. These characteristics correspond to}}\newline{}\resizebox{432.131bp}{!}{\mbox{the class attributes and class directed interactions that individual federates may publish and to which other}}\newline{}\resizebox{98.516bp}{!}{\mbox{federates may subscribe.}}\par}
