\HLAStableID{m3.p023.b05}
\HLAClausePlacedBlock{90.003}{273.782}{432.078}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.983bp}{!}{\mbox{\textbf{optimistic logical time (OLT):}\space{}A supplementary logical time that facilitates optimistic time advancement.}}\newline{}\resizebox{431.974bp}{!}{\mbox{The optimistic logical time is provided, along with the update to the federate’s logical time, in a\space{}\textit{Flush Queue}}}\newline{}\resizebox{432.000bp}{!}{\mbox{\textit{Grant †}\space{}service call as a response to a\space{}\textit{Flush Queue Request}\space{}service call. It is the minimum of the time}}\newline{}\resizebox{432.078bp}{!}{\mbox{supplied in the\space{}\textit{Flush Queue Request}\space{}and the timestamps of any TSO messages delivered in response to that}}\newline{}\resizebox{432.010bp}{!}{\mbox{\textit{Flush Queue Request}. The optimistic logical time indicates a lower bound on the next logical time the}}\newline{}\resizebox{423.365bp}{!}{\mbox{federate could be advanced to if no TSO messages with a timestamp less than it are received in the future.}}\par}
}
