  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.989bp}{!}{\mbox{\textbf{reflect:}\space{}To receive new values for one or more instance attributes via invocation of the\space{}\textit{Reflect Attribute}}}\newline{}\resizebox{69.350bp}{!}{\mbox{\textit{Values †}\space{}service.}}\par}
}
