\HLAClausePlacedBlock{89.999}{69.786}{432.045}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.044bp}{!}{\mbox{\textbf{region realization:}\space{}A region specification (set of ranges) that is associated with an instance attribute for}}\newline{}\resizebox{431.985bp}{!}{\mbox{update, with a sent interaction, or with a class attribute or interaction class for subscription. Region}}\newline{}\resizebox{432.006bp}{!}{\mbox{realizations are created from region specifications via the\space{}\textit{Commit Region Modifications}\space{}(only when}}\newline{}\resizebox{432.008bp}{!}{\mbox{modifying a region specification from which region realizations are already derived),\space{}\textit{Register Object}}}\newline{}\resizebox{431.971bp}{!}{\mbox{\textit{Instance With Regions},\space{}\textit{Associate Regions for Updates},\space{}\textit{Subscribe Object Class Attributes With Regions},}}\newline{}\resizebox{432.009bp}{!}{\mbox{\textit{Subscribe Interaction Class With Regions},\space{}\textit{Send Interaction With Regions}, or\space{}\textit{Request Attribute Value}}}\newline{}\resizebox{122.087bp}{!}{\mbox{\textit{Update With Regions}\space{}services.}}\par}
}
