\HLAClausePlacedBlock{90.000}{165.981}{162.056}{%
  {\HLATimes\fontsize{9.000bp}{10.620bp}\selectfont\raggedright \resizebox{162.056bp}{!}{\mbox{NOTE—See 9.1.1 of IEEE Std 1516.1-2025.}}\par}
}
\HLAStableID{m3.p026.b03}
\HLAClausePlacedBlock{90.000}{187.806}{432.008}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.008bp}{!}{\mbox{\textbf{region specification:}\space{}A set of ranges. Region specifications are created using the\space{}\textit{Create Region}\space{}service, and}}\newline{}\resizebox{431.984bp}{!}{\mbox{a runtime infrastructure (RTI) is notified of changes to a region specification using the\space{}\textit{Commit Region}}}\newline{}\resizebox{91.310bp}{!}{\mbox{\textit{Modifications}\space{}service.}}\par}
}
