  {\HLATimes\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{162.270bp}{!}{\mbox{NOTE—See 9.1.1 of IEEE Std 1516.1-2025.}}\par}
}
\HLAStableID{m3.p026.b05}
\HLAClausePlacedBlock{90.000}{259.805}{431.970}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.970bp}{!}{\mbox{\textbf{region template:}\space{}A region template is an incomplete region specification where one or more dimensions}}\newline{}\resizebox{123.545bp}{!}{\mbox{have not been assigned ranges.}}\par}
}
\HLAStableID{m3.p026.b06}
