  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.029bp}{!}{\mbox{\textbf{register:}\space{}To invoke the\space{}\textit{Register Object Instance}\space{}or the\space{}\textit{Register Object Instance With Regions}\space{}service to}}\newline{}\resizebox{168.869bp}{!}{\mbox{create a unique object instance designator.}}\par}
}
