}
\HLAStableID{m3.p026.b08}
\HLAClausePlacedBlock{90.000}{353.766}{432.030}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.988bp}{!}{\mbox{\textbf{registered class:}\space{}The object class that was an argument to the\space{}\textit{Register Object Instance}\space{}or the\space{}\textit{Register}}}\newline{}\resizebox{432.029bp}{!}{\mbox{\textit{Object Instance With Regions}\space{}service invocation that resulted in the creation of the object instance}}\newline{}\resizebox{152.020bp}{!}{\mbox{designator for a given object instance.}}\par}
