\HLAClausePlacedBlock{90.001}{449.764}{431.987}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.987bp}{!}{\mbox{\textbf{regular object class description:}\space{}A description of an object class that follows IEEE Std 1516.2-2025 and}}\newline{}\resizebox{308.461bp}{!}{\mbox{contains at a minimum the object class name and publish/subscribe indicator.}}\par}
