  {\HLATimes\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{425.533bp}{!}{\mbox{\textbf{remove:}\space{}To receive an invocation of the\space{}\textit{Remove Object Instance †}\space{}service for a particular object instance.}}\par}
