\HLAClausePlacedBlock{90.000}{531.786}{432.072}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.989bp}{!}{\mbox{\textbf{repeated description:}\space{}A description of a construct (e.g., object class, interaction class, data type,}}\newline{}\resizebox{432.072bp}{!}{\mbox{dimension) in a federation object model (FOM) module with a name and additional properties that are}}\newline{}\resizebox{278.084bp}{!}{\mbox{identical to a description that is already available in the current FOM.}}\par}
}
\HLAStableID{m3.p026.b14}
\HLAClausePlacedBlock{90.000}{579.785}{431.845}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.845bp}{!}{\mbox{\textbf{resolution:}\space{}The smallest resolvable value separating attribute or parameter values that can be discriminated.}}\newline{}\resizebox{237.255bp}{!}{\mbox{Resolution may vary with magnitude for certain data types.}}\par}
}
\HLAStableID{m3.p026.b15}
\HLAClausePlacedBlock{90.000}{615.784}{432.025}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.929bp}{!}{\mbox{\textbf{retraction:}\space{}An action performed by a federate to unschedule a previously scheduled message. Message}}\newline{}\resizebox{432.025bp}{!}{\mbox{retraction may be visible to the federate to whom the scheduled message was to be delivered. Retraction is}}\newline{}\resizebox{431.989bp}{!}{\mbox{widely used in classic event-oriented discrete event simulations to model behaviors such as preemption and}}\newline{}\resizebox{40.749bp}{!}{\mbox{interrupts.}}\par}
}
\HLAStableID{m3.p026.b16}
\HLAClausePlacedBlock{90.000}{675.783}{432.070}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.070bp}{!}{\mbox{\textbf{runtime infrastructure (RTI):}\space{}The software that provides common interface services during a High Level}}\newline{}\resizebox{323.235bp}{!}{\mbox{Architecture (HLA) federation execution for synchronization and data exchange.}}\par}
}
\end{HLAClauseSemanticPage}

