  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.063bp}{!}{\mbox{\textbf{runtime infrastructure (RTI) initialization data (RID):}\space{}RTI vendor-specific information needed to run an}}\newline{}\resizebox{245.805bp}{!}{\mbox{RTI. If required, a RID is supplied when an RTI is initialized.}}\par}
}
\HLAStableID{m3.p027.b02}
\HLAClausePlacedBlock{90.000}{105.785}{432.108}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.108bp}{!}{\mbox{\textbf{scaffolding interaction class description:}\space{}A description of an interaction class in a federation object model}}\newline{}\resizebox{432.020bp}{!}{\mbox{(FOM) module or simulation object model (SOM) module that follows IEEE Std 1516.2-2025. However, it}}\newline{}\resizebox{431.965bp}{!}{\mbox{will contain only the name. The name of the scaffolding interaction class description is identical to the name}}\newline{}\resizebox{432.001bp}{!}{\mbox{of a regular interaction class description provided by another FOM/SOM module. Scaffolding interaction}}\newline{}\resizebox{431.928bp}{!}{\mbox{class descriptions act as placeholders in order to represent the class hierarchy from the other FOM/SOM}}\newline{}\resizebox{332.295bp}{!}{\mbox{module(s) from which a new regular interaction class description can be specified.}}\par}
}
