\HLAClausePlacedBlock{90.000}{189.784}{432.035}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.024bp}{!}{\mbox{\textbf{scaffolding object class description:}\space{}A description of an object class in a federation object model (FOM)}}\newline{}\resizebox{431.956bp}{!}{\mbox{module or simulation object model (SOM) module that follows IEEE Std 1516.2-2025. However, it will}}\newline{}\resizebox{432.035bp}{!}{\mbox{contain only the name. The name of the scaffolding object class description is identical to the name of a}}\newline{}\resizebox{431.968bp}{!}{\mbox{regular object class description provided by another FOM/SOM module. Scaffolding object class}}\newline{}\resizebox{432.006bp}{!}{\mbox{descriptions act as placeholders in order to represent the class hierarchy from the other FOM/SOM}}\newline{}\resizebox{311.383bp}{!}{\mbox{module(s) from which a new regular object class description can be specified.}}\par}
}
\HLAStableID{m3.p027.b04}
