  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \makebox[431.996bp][l]{\textbf{sent class:}\space{}The interaction class that was an argument to the\space{}\textit{Send Interaction,}\hfill{}\space{}\textit{Send Interaction With}}\newline{}\resizebox{415.679bp}{!}{\mbox{\textit{Regions,}or\space{}\textit{Send Directed Interaction}\space{}service invocation that initiated the sending of a given interaction.}}\par}
}
\HLAStableID{m3.p027.b05}
