  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.970bp}{!}{\mbox{\textbf{sent interaction:}\space{}A specific interaction that is transmitted by a joined federate via the\space{}\textit{Send Interaction},}}\newline{}\resizebox{432.014bp}{!}{\mbox{\textit{Send Interaction With Regions,}or\space{}\textit{Send Directed Interaction}\space{}service and received by other joined federates in}}\newline{}\resizebox{383.739bp}{!}{\mbox{the federation execution via the\space{}\textit{Receive Interaction}\space{}\textit{† or Receive Directed Interaction}\space{}\textit{†}\space{}service.}}\par}
