  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.039bp}{!}{\mbox{\textbf{simulation object model (SOM):}\space{}A specification of the types of information that an individual federate}}\newline{}\resizebox{432.060bp}{!}{\mbox{could provide to High Level Architecture (HLA) federations as well as the information that an individual}}\newline{}\resizebox{432.104bp}{!}{\mbox{federate can receive from other federates in HLA federations. The SOM is specified using one or more SOM}}\newline{}\resizebox{432.035bp}{!}{\mbox{modules. The standard format in which SOMs are expressed facilitates determination of the suitability of}}\newline{}\resizebox{168.467bp}{!}{\mbox{federates for participation in a federation.}}\par}
}
\HLAStableID{m3.p027.b11}
\HLAClausePlacedBlock{89.998}{557.824}{432.027}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.001bp}{!}{\mbox{\textbf{simulation object model (SOM) module:}\space{}A subset of the SOM that contains some or all object model}}\newline{}\resizebox{431.975bp}{!}{\mbox{template (OMT) tables. SOM modules and one optional Management Object Model (MOM) and}}\newline{}\resizebox{431.977bp}{!}{\mbox{Initialization Module (MIM) are used to specify the SOM of a federate. A SOM module contains complete}}\newline{}\resizebox{432.027bp}{!}{\mbox{or scaffolding definitions for all object classes and interaction classes that are superclasses of object classes}}\newline{}\resizebox{197.114bp}{!}{\mbox{and interaction classes in the same SOM module.}}\par}
