\HLAClausePlacedBlock{89.999}{213.783}{431.976}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.976bp}{!}{\mbox{The joined federate’s time position will not actually be advanced until the RTI responds with a\space{}\textit{Time}}}\newline{}\resizebox{334.706bp}{!}{\mbox{\textit{Advance Grant † or Flush Queue Grant †}\space{}service invocation at that joined federate.}}\par}
}
\HLAStableID{m3.p029.b05}
\HLAClausePlacedBlock{89.999}{249.783}{432.065}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.047bp}{!}{\mbox{\textbf{time axis:}\space{}A totally ordered sequence of discrete values in which each value typically represents an HLA}}\newline{}\resizebox{432.065bp}{!}{\mbox{instant of time in the physical system being modeled. For any two points, T1 and T2, on the time axis, if T1}}\newline{}\resizebox{431.967bp}{!}{\mbox{< T2, T1 represents an instant of time that occurs before the instant represented by T2. The sequence begins}}\newline{}\resizebox{419.073bp}{!}{\mbox{with an initial value, for which no point is less, and ends with a final value, for which no point is greater.}}\par}
}
\HLAStableID{m3.p029.b06}
