  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.053bp}{!}{\mbox{\textbf{time-constrained federate:}\space{}A joined federate that may receive timestamp order (TSO) messages and whose}}\newline{}\resizebox{343.623bp}{!}{\mbox{time advances are constrained by other joined federates within a federation execution.}}\par}
}
\HLAStableID{m3.p029.b07}
\HLAClausePlacedBlock{90.000}{345.981}{153.057}{%
