}
\HLAStableID{m3.p029.b09}
\HLAClausePlacedBlock{90.000}{415.805}{302.356}{%
  {\HLATimes\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{302.356bp}{!}{\mbox{\textbf{time position:}\space{}A joined federate’s association with a point on the time axis.}}\par}
}
\HLAStableID{m3.p029.b10}
\HLAClausePlacedBlock{90.000}{439.804}{431.983}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.983bp}{!}{\mbox{\textbf{time-regulating federate:}\space{}A joined federate that may send timestamp order (TSO) messages and that}}\newline{}\resizebox{336.445bp}{!}{\mbox{constrains the time advances of other joined federates within a federation execution.}}\par}
}
\HLAStableID{m3.p029.b11}
\HLAClausePlacedBlock{90.000}{476.001}{155.322}{%
