  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.919bp}{!}{\mbox{\textbf{timestamp (of message or save):}\space{}The association of a logical time with an activity of a federate (e.g.,}}\newline{}\resizebox{305.305bp}{!}{\mbox{updating instance attribute values, sending interactions and federation save).}}\par}
}
\HLAStableID{m3.p029.b13}
\HLAClausePlacedBlock{89.999}{533.825}{432.052}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.982bp}{!}{\mbox{\textbf{timestamp order (TSO):}\space{}An ordering of messages provided by a runtime infrastructure (RTI) for joined}}\newline{}\resizebox{432.012bp}{!}{\mbox{federates making use of time management services and messages containing timestamps. Messages having}}\newline{}\resizebox{432.028bp}{!}{\mbox{different timestamps are said to be delivered in TSO if for any two messages, M1 and M2 (timestamped with}}\newline{}\resizebox{432.052bp}{!}{\mbox{T1 and T2, respectively), that are delivered to a single joined federate where T1 < T2, then M1 is delivered}}\newline{}\resizebox{431.981bp}{!}{\mbox{before M2. Messages having the same timestamp will be delivered in an arbitrary order (i.e., no tie-breaking}}\newline{}\resizebox{141.007bp}{!}{\mbox{mechanism is provided by an RTI).}}\par}
}
\HLAStableID{m3.p029.b14}
\HLAClausePlacedBlock{89.999}{617.824}{431.969}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.969bp}{!}{\mbox{\textbf{token:}\space{}An attribute without a value, which conveys the information of which federate, if any, owns the}}\newline{}\resizebox{35.809bp}{!}{\mbox{attribute.}}\par}
}
\HLAStableID{m3.p029.b15}
\HLAClausePlacedBlock{89.999}{653.823}{431.999}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.999bp}{!}{\mbox{\textbf{transportation type:}\space{}A runtime infrastructure (RTI) provided means of transmitting messages between}}\newline{}\resizebox{431.982bp}{!}{\mbox{joined federates. Different categories of service are defined with different characteristics such as reliability}}\newline{}\resizebox{130.046bp}{!}{\mbox{of delivery and message latency.}}\par}
}
