}
\HLAStableID{m3.p032.b16}
\HLAClausePlacedBlock{90.000}{319.806}{432.010}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{432.010bp}{!}{\mbox{Conventions in this standard specify how entries are to be formulated when completing an HLA object}}\newline{}\resizebox{236.435bp}{!}{\mbox{model. The following conventions pertain to this standard.}}\par}
}
\HLAStableID{m3.p032.b17}
\HLAClausePlacedBlock{90.000}{355.666}{57.722}{%
  {\HLAArial\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \resizebox{57.722bp}{!}{\mbox{\textbf{3.3.1 Names}}}\par}
}
\HLAStableID{m3.p032.b18}
\HLAClausePlacedBlock{90.000}{379.805}{432.032}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \resizebox{431.854bp}{!}{\mbox{Names in object models shall adhere to eXtensible Markup Language (XML) naming conventions. XML}}\newline{}\resizebox{432.032bp}{!}{\mbox{conventions state that names cannot begin with a number or punctuation character, and require that names}}\newline{}\resizebox{431.874bp}{!}{\mbox{be constructed from a combination of letters, digits, hyphens, colons, full stops (periods), and underscores}}\newline{}\resizebox{431.977bp}{!}{\mbox{with no spaces or other breaking characters (e.g., tabs, carriage returns). In HLA object models, allowable}}\newline{}\resizebox{174.393bp}{!}{\mbox{names shall be further restricted as follows:}}\par}
}
\HLAStableID{m3.p032.b19}
\HLAClausePlacedBlock{100.020}{445.804}{422.041}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \makebox[421.917bp][l]{a)\hfill{}\space{}The period (full stop) is reserved for qualifying class names and shall not be included in a}\newline{}\hspace*{21.960bp}\resizebox{400.041bp}{!}{\mbox{user-defined name within an object model. When fully qualified, the class name includes all}}\newline{}\hspace*{21.959bp}\resizebox{400.082bp}{!}{\mbox{predecessor class names (separated by periods) beginning at the root and ending at the class name in}}\newline{}\hspace*{21.959bp}\resizebox{36.388bp}{!}{\mbox{question.}}\par}
}
\HLAStableID{m3.p032.b20}
\HLAClausePlacedBlock{100.019}{499.803}{348.003}{%
  {\HLATimes\fontsize{9.960bp}{11.753bp}\selectfont\raggedright \makebox[348.004bp][l]{b)\hfill{}\space{}As recommended in the XML specification, the colon character shall not be used.}\par}
}
\HLAStableID{m3.p032.b21}
\HLAClausePlacedBlock{100.019}{517.802}{421.910}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \makebox[421.910bp][l]{c)\hfill{}\space{}Names beginning with the string “hla,” or any string that would match (('H'|'h') ('L'|'l') ('A'|'a')), are}\newline{}\hspace*{21.960bp}\resizebox{229.413bp}{!}{\mbox{reserved and shall not be included in user-defined names.}}\par}
}
\HLAStableID{m3.p032.b22}
\HLAClausePlacedBlock{100.019}{547.802}{421.975}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \makebox[421.976bp][l]{d)\hfill{}\space{}The case of all textual data within HLA object models (including names) shall be significant; all}\newline{}\hspace*{21.960bp}\resizebox{291.314bp}{!}{\mbox{textual data defined in an object model document shall be case-sensitive.}}\par}
}
\HLAStableID{m3.p032.b23}
\HLAClausePlacedBlock{100.019}{577.802}{422.001}{%
  {\HLATimes\fontsize{9.960bp}{12.000bp}\selectfont\raggedright \makebox[421.982bp][l]{e)\hfill{}\space{}A name consisting of the string “na,” or any string that would match (('N'|'n') ('A'|'a')), is reserved to}\newline{}\hspace*{21.961bp}\resizebox{400.041bp}{!}{\mbox{indicate that a name is not applicable in this circumstance and shall not be included as a user-defined}}\newline{}\hspace*{21.961bp}\resizebox{24.155bp}{!}{\mbox{name.}}\par}
}
\HLAStableID{m3.p032.b24}
\HLAClausePlacedBlock{90.000}{625.801}{259.285}{%
