\HLAClausePlacedBlock{90.000}{204.786}{432.031}{%
  \HLAClauseParagraph{\resizebox{432.031bp}{!}{\mbox{This subclause provides the format for describing the parameters that are associated with interaction classes.}}\newline{}\resizebox{431.966bp}{!}{\mbox{The structure that shall be used for this information is provided in Table 52. A separate row shall be}}\newline{}\resizebox{211.486bp}{!}{\mbox{completed for each parameter of an interaction class.}}}
}
\HLAStableID{m5.p090.b03}
\HLAClausePlacedBlock{89.999}{354.785}{432.001}{%
  \HLAClauseParagraph{\resizebox{431.937bp}{!}{\mbox{The first column (Class) shall contain the name of the interaction class with which a given parameter is}}\newline{}\resizebox{431.995bp}{!}{\mbox{associated. Interaction class names shall use dot notation as necessary to uniquely identify the interaction}}\newline{}\resizebox{212.903bp}{!}{\mbox{class and may include the full parentage of the class.}}}
}
\HLAStableID{m5.p090.b04}
