\HLAStableID{m5.p090.b05}
\HLAClausePlacedBlock{89.999}{426.784}{432.924}{%
  \HLAClauseParagraph{\resizebox{432.924bp}{!}{\mbox{The third column (Semantics) shall describe the specific information that this parameter is designed to convey.}}}
}
\HLAStableID{m5.p090.b06}
