}
\HLAStableID{m5.p090.b08}
\HLAClausePlacedBlock{90.000}{638.826}{432.056}{%
  \HLAClauseParagraph{\resizebox{432.030bp}{!}{\mbox{The OMT tables provide a common representation of an object model. This clause defines the measures for}}\newline{}\resizebox{432.032bp}{!}{\mbox{assessment of object models and object model tools, based upon the normative clauses of this specification.}}\newline{}\resizebox{432.056bp}{!}{\mbox{The spectrum of OMT tools is broad, but conformance is a narrow measure of the object models accepted or}}\newline{}\resizebox{431.984bp}{!}{\mbox{produced by a tool. Other tool capabilities, from user interface visualization to code generation, are}}\newline{}\resizebox{432.007bp}{!}{\mbox{significant but not assessed by these conformance measures. Within the HLA community, verification}}\newline{}\resizebox{342.493bp}{!}{\mbox{capabilities conduct these assessments experimentally and publicly certify the results.}}}
}
