\HLAClausePlacedBlock{90.000}{69.383}{123.357}{%
  \HLASubclauseHeading{6.1 Conformance labels}
}
\HLAStableID{m5.p091.b02}
\HLAClausePlacedBlock{90.000}{94.806}{432.000}{%
  \HLAClauseParagraph{\resizebox{431.874bp}{!}{\mbox{Both object models and tools may be assessed for conformance to this standard. Only when certified results}}\newline{}\resizebox{262.579bp}{!}{\mbox{are publicly available shall the label “HLA Conforming” be used.}}}
}
\HLAStableID{m5.p091.b03}
\HLAClausePlacedBlock{90.000}{128.626}{153.853}{%
  \HLAMinorClauseHeading{6.1.1 Object model conformance}
}
\HLAStableID{m5.p091.b04}
\HLAClausePlacedBlock{90.000}{152.765}{432.050}{%
  \HLAClauseParagraph{\resizebox{432.002bp}{!}{\mbox{An HLA conforming object model shall document all of the OMT components of an HLA object model,}}\newline{}\resizebox{431.925bp}{!}{\mbox{be it a FOM or relevant FOM modules for federations or a SOM or relevant SOM modules for federates.}}\newline{}\resizebox{432.018bp}{!}{\mbox{The HLA-required table content, commonly referred to as MOM data, shall be provided as specified in}}\newline{}\resizebox{431.945bp}{!}{\mbox{Clause 11 of IEEE Std 1516.1-2025, and shall be contained in a MIM. Each OMT table shall be provided,}}\newline{}\resizebox{432.050bp}{!}{\mbox{with empty content only as permitted in the table descriptions. All entries in a conforming object model}}\newline{}\resizebox{253.633bp}{!}{\mbox{shall comply with the conventions given in 3.3 of this standard.}}}
}
\HLAStableID{m5.p091.b05}
\HLAClausePlacedBlock{90.000}{230.624}{174.866}{%
  \HLAMinorClauseHeading{6.1.2 Object model tool conformance}
}
\HLAStableID{m5.p091.b06}
\HLAClausePlacedBlock{89.999}{254.764}{432.102}{%
  \HLAClauseParagraph{\resizebox{431.958bp}{!}{\mbox{An HLA conforming object model tool shall accept any conforming object model and operate on it. The}}\newline{}\resizebox{431.985bp}{!}{\mbox{only required operations shall be parsing the XML product form of the object model and, for tools with}}\newline{}\resizebox{432.032bp}{!}{\mbox{XML output, expressing the model in valid XML. Additional operations provided by the tool are selected by}}\newline{}\resizebox{432.003bp}{!}{\mbox{the developer. Operations with user input shall identify inputs that would cause the resulting object model to}}\newline{}\resizebox{432.102bp}{!}{\mbox{no longer be conforming. An example would be a user entered name that was not a valid XML name or did}}\newline{}\resizebox{431.956bp}{!}{\mbox{not comply with HLA naming conventions. The user shall have the option to produce a non-conforming}}\newline{}\resizebox{431.979bp}{!}{\mbox{object model, based on this input. Future acceptance of the non-conforming object model by conforming}}\newline{}\resizebox{190.404bp}{!}{\mbox{object model tools is desirable but not required.}}}
}
\HLAStableID{m5.p091.b07}
\HLAClausePlacedBlock{89.999}{354.642}{151.547}{%
  \HLAMinorClauseHeading{6.1.3 XML product conformance}
}
\HLAStableID{m5.p091.b08}
\HLAClausePlacedBlock{89.999}{378.781}{432.015}{%
  \HLAClauseParagraph{\resizebox{431.936bp}{!}{\mbox{A conforming object model expressed in XML by a conforming object model tool shall be processed}}\newline{}\resizebox{431.946bp}{!}{\mbox{without validation exception by any fully conforming XML processor, as defined in REC-XML-20060816,}}\newline{}\resizebox{432.015bp}{!}{\mbox{Fourth Edition of XML Schema (www.w3.org), when validated against the OMT XML Schema defined in}}\newline{}\resizebox{37.700bp}{!}{\mbox{Annex E.}}}
}
\HLAStableID{m5.p091.b09}
\HLAClausePlacedBlock{90.000}{440.423}{150.763}{%
  \HLASubclauseHeading{6.2 Conformance verification}
}
\HLAStableID{m5.p091.b10}
\HLAClausePlacedBlock{90.000}{465.786}{432.023}{%
  \HLAClauseParagraph{\resizebox{432.023bp}{!}{\mbox{Tests for conformance may cover any normative part of this standard, and conforming products are expected}}\newline{}\resizebox{431.900bp}{!}{\mbox{to comply with all “shall” statements. The following subclauses define the minimum requirements that shall}}\newline{}\resizebox{431.969bp}{!}{\mbox{be assessed in any conformance test. Invalid entries detected during conformance testing shall be explicitly}}\newline{}\resizebox{40.789bp}{!}{\mbox{identified.}}}
}
\HLAStableID{m5.p091.b11}
\HLAClausePlacedBlock{90.000}{525.645}{179.379}{%
  \HLAMinorClauseHeading{6.2.1 Object model identification table}
}
\HLAStableID{m5.p091.b12}
\HLAClausePlacedBlock{90.000}{549.784}{432.000}{%
  \HLAClauseParagraph{\resizebox{310.666bp}{!}{\mbox{The following tests shall be assessed for the object model identification table:}}}
}
\HLAStableID{m5.p091.b13}
\HLAClausePlacedBlock{121.980}{567.784}{402.120}{%
  \HLAClauseLabeledItem{1)}{\resizebox{227.824bp}{!}{\mbox{The Name shall conform to the name conventions of 3.3.}}}
}
\HLAStableID{m5.p091.b14}
\HLAClausePlacedBlock{121.980}{582.784}{402.120}{%
  \HLAClauseLabeledItem{2)}{\resizebox{273.697bp}{!}{\mbox{The Modification Date shall conform to the format given in Table 1.}}}
}
\HLAStableID{m5.p091.b15}
\HLAClausePlacedBlock{121.980}{597.784}{402.120}{%
  \HLAClauseLabeledItem{3)}{\resizebox{361.408bp}{!}{\mbox{The remaining fields in this table shall not be blank (although some values may be “NA”).}}}
}
