\HLAStableID{m5.p095.b22}
\HLAClausePlacedBlock{90.000}{568.805}{432.079}{%
  \HLAClauseParagraph{\resizebox{431.984bp}{!}{\mbox{HLA supports federates with many different interface requirements.This table allows federate and federation}}\newline{}\resizebox{431.973bp}{!}{\mbox{developers to document the set of HLA Interface Specification services used by federates or federations.}}\newline{}\resizebox{432.079bp}{!}{\mbox{SOMs and FOMs may optionally include the Interface Services Usage Table as it is useful for both types of}}\newline{}\resizebox{81.348bp}{!}{\mbox{HLA object models.}}}
}
\HLAStableID{m5.p095.b23}
\HLAClausePlacedBlock{89.999}{628.804}{432.036}{%
  \HLAClauseParagraph{\resizebox{431.986bp}{!}{\mbox{From the SOM perspective, this table is useful because the HLA federate compliance testing process}}\newline{}\resizebox{431.946bp}{!}{\mbox{requires the submission of a statement documenting which HLA Interface services a federate uses. This}}\newline{}\resizebox{431.836bp}{!}{\mbox{statement is first used in the Conformance Cross Check test to confirm that the federate’s SOM is congruent}}\newline{}\resizebox{432.035bp}{!}{\mbox{with the set of HLA Interface services being used. Later, this statement is used to help determine the federate}}\newline{}\resizebox{431.999bp}{!}{\mbox{Compliance Test Sequence. The inclusion of this table in a SOM would support the HLA Compliance}}\newline{}\resizebox{83.220bp}{!}{\mbox{Testing requirement.}}}
}
