\HLAClausePlacedBlock{90.000}{69.786}{432.029}{%
  \HLAClauseParagraph{\resizebox{432.023bp}{!}{\mbox{From the FOM perspective, this table is useful because this table allows the HLA Interface Specification}}\newline{}\resizebox{432.008bp}{!}{\mbox{services used by federations and federates to be documented in FOMs and reused during federation}}\newline{}\resizebox{431.884bp}{!}{\mbox{preparations. During a federation execution, a federate may need to exercise only a subset of its capabilities.}}\newline{}\resizebox{431.961bp}{!}{\mbox{Federates may associate themselves with different federations, and federations may change federates from}}\newline{}\resizebox{431.975bp}{!}{\mbox{time to time. Federation developers and managers can use this table in two different ways. First, the table}}\newline{}\resizebox{431.966bp}{!}{\mbox{may be used as a tool to document a common set of services that will be supported across the full federation.}}\newline{}\resizebox{431.918bp}{!}{\mbox{As such, this table would be in a readily available, predefined form that would replace the current procedure}}\newline{}\resizebox{431.985bp}{!}{\mbox{of developing an ad hoc federation agreement to document HLA Interface service usage. The second way to}}\newline{}\resizebox{431.951bp}{!}{\mbox{use the table is as a mechanism to review the specific services a federate uses and then assess whether or not}}\newline{}\resizebox{432.028bp}{!}{\mbox{a federate is likely to be compatible with other federates that are already members of a specific federation.}}\newline{}\resizebox{432.026bp}{!}{\mbox{Both ways provide valuable assistance to federation developers and managers in the areas of reuse and}}\newline{}\resizebox{409.144bp}{!}{\mbox{interoperability during Distributed Simulation Engineering and Execution Process (DSEEP) activities.}}}
}
\HLAStableID{m5.p096.b02}
\HLAClausePlacedBlock{90.001}{225.644}{84.959}{%
  \HLAMinorClauseHeading{6.3.2 Table format}
}
\HLAStableID{m5.p096.b03}
\HLAClausePlacedBlock{90.000}{249.783}{432.023}{%
  \HLAClauseParagraph{\resizebox{432.022bp}{!}{\mbox{The template that shall be used for service utilization is illustrated in Table 54. The second column (Service)}}\newline{}\resizebox{432.010bp}{!}{\mbox{shall provide the names of HLA services. The first column shall provide the HLA Interface Specification}}\newline{}\resizebox{431.970bp}{!}{\mbox{clause number associated with each service. The third column (Usage) shall identify the usage of that}}\newline{}\resizebox{431.950bp}{!}{\mbox{service within the federate or federation. Entries\space{}4.5, 4.6, 4.9, and 4.10\space{}shall be “Yes” for FOMs because}}\newline{}\resizebox{431.992bp}{!}{\mbox{these four services are the minimum required to form a valid federation. Entries 4.9 and 4.10 shall be “Yes”}}\newline{}\resizebox{351.887bp}{!}{\mbox{for SOMs because these two services are the minimum required to form a valid federate}}}
}
